# ══════════════════════════════════════════════════════
# 🎨 COLORED BUTTON HELPERS (Bot API 9.4+ "style" field)
# ══════════════════════════════════════════════════════
# Telegram Bot API 9.4 (Feb 9, 2026) যোগ করেছে বাটনের জন্য
# একটা "style" ফিল্ড — যা দিয়ে বাটনের background color সেট
# করা যায়। মাত্র ৩টা প্রিসেট কালার আছে:
#   • primary → নীল   (default/neutral action)
#   • success → সবুজ  (positive/confirm action)
#   • danger  → লাল   (destructive/cancel action)
#
# ⚠️ এই ফিচার কাজ করার জন্য দুইটা শর্ত লাগবে:
#   1) pyTelegramBotAPI লাইব্রেরি এই "style" প্যারামিটার
#      সাপোর্ট করে এমন ভার্সনে থাকতে হবে (pip install -U pyTelegramBotAPI)
#   2) ইউজারের Telegram app 9 Feb 2026 এর পরের ভার্সনের হতে হবে
#
# পুরোনো লাইব্রেরি/ক্লায়েন্টে থাকলেও bot কখনো crash করবে না।
#
# ⚠️ FIX: শুধু constructor-এ style= পাস করলেই যথেষ্ট না —
# pyTelegramBotAPI এর to_dict() মেথড যদি "style" ফিল্ড না চেনে,
# তাহলে সেটা কখনো JSON payload-এ যায়ই না, ফলে Telegram-এ বাটন
# রঙিন দেখা যায় না। তাই নিচে to_dict() নিজেই override করে
# style জোর করে JSON dict-এ ঢুকিয়ে দেওয়া হচ্ছে — লাইব্রেরি
# version যাই থাকুক না কেন, style এখন থেকে গ্যারান্টিড ভাবে
# Telegram API তে পাঠানো হবে।
def _force_style_in_json(btn, style):
    """btn.to_dict()/to_json() কে patch করে 'style' key জোর করে বসিয়ে দেয়।"""
    if not style:
        return btn
    try:
        original_to_dict = btn.to_dict
        def patched_to_dict():
            d = original_to_dict()
            if isinstance(d, dict):
                d["style"] = style
            return d
        btn.to_dict = patched_to_dict
    except Exception:
        pass
    try:
        import json as _json_for_style
        original_to_json = btn.to_json
        def patched_to_json():
            d = btn.to_dict()
            return _json_for_style.dumps(d)
        btn.to_json = patched_to_json
    except Exception:
        pass
    # attribute হিসেবেও রেখে দিচ্ছি, ভবিষ্যতে লাইব্রেরি native সাপোর্ট
    # করলে সেটাও যেন কাজ করে
    try:
        setattr(btn, "style", style)
    except Exception:
        pass
    return btn

def _make_styled(cls, text, style=None, **kwargs):
    if style:
        try:
            btn = cls(text, style=style, **kwargs)
        except TypeError:
            btn = cls(text, **kwargs)
        return _force_style_in_json(btn, style)
    return cls(text, **kwargs)

def InlineBtn(text, style=None, **kwargs):
    """types.InlineKeyboardButton এর color-safe wrapper।"""
    return _make_styled(types.InlineKeyboardButton, text, style=style, **kwargs)

# ══════════════════════════════════════════════════════
# 🎨 KEYBOARD BUTTON — PER-BUTTON COLOR — Admin Panel Controlled
# ══════════════════════════════════════════════════════
# প্রতিটা keyboard (reply) বাটনের color আলাদাভাবে admin panel
# থেকে বদলানো যায়। বাটনগুলোকে "role" দিয়ে গ্রুপ করা হয়েছে
# (একই role এর সব বাটন একসাথে একই color পাবে — যেমন সব "Back"
# বাটন, বা সব "Product" বাটন)। 3টা preset color:
#   primary(🔵নীল) / success(🟢সবুজ) / danger(🔴লাল) / normal(⚪ ডিফল্ট)
# _KB_ROLE_COLORS ইন-মেমরি cache — instant reflect হয়, আর
# MySQL এ persist হয় যাতে bot restart এর পরও মনে থাকে।
_KB_COLOR_CHOICES = {"primary", "success", "danger", "normal"}

# role → (বাংলা লেবেল, ডিফল্ট কালার — কোডে যা আগে হার্ডকোড ছিল)
KB_BUTTON_ROLES = {
    "shop":         ("🛍️ শপ (Shop)",              "primary"),
    "buy_proxy":    ("🌐 প্রক্সি &ভিপিএন (Proxy &Vpn)",  "primary"),
    "deposit":      ("💰 ডিপোজিট (Deposit)",        "success"),
    "balance":      ("💳 ব্যালেন্স (Balance)",       "primary"),
    "orders":       ("📦 অর্ডার (Orders)",          "primary"),
    "refer":        ("🔗 রেফার (Refer)",            "primary"),
    "other":        ("↪️ আদার (Other)",             "primary"),
    "support":      ("🆘 সাপোর্ট (Support)",         "primary"),
    "twofa":        ("🔐 2FA কোড (2FA Code)",        "primary"),
    "edu_reader":   ("📧 এডু রিডার (Edu Reader)",     "primary"),
    "language":     ("🌐 ভাষা (Language)",           "primary"),
    "code":         ("💻 কোড (Code</>)",             "primary"),
    "admin":        ("🛠️ এডমিন (Admin)",            "primary"),
    "back":         ("🔙 ব্যাক (Back)",              "primary"),
    "cancel":       ("❌ ক্যানসেল (Cancel)",         "danger"),
    "skip":         ("⏭️ স্কিপ (Skip)",              "primary"),
    "buy_single":   ("🛒 সিঙ্গেল বাই (Single Buy)", "success"),
    "buy_bulk":     ("📦 বাল্ক বাই (Bulk Buy)",     "success"),
    "product1":     ("🆕 Product1 বাটন",             "success"),
    "product2":     ("🆕 Product2 বাটন",             "success"),
    "product3bulk": ("🆕 Product3Bulk বাটন",          "success"),
    "product_item": ("📦 প্রোডাক্ট লিস্ট বাটন",      "success"),
    "category_item":("📂 ক্যাটাগরি/সাব-আইটেম বাটন", "primary"),
    "misc_option":  ("⚙️ অন্যান্য অপশন বাটন",        "primary"),
    "proxy_real":   ("🌐 Real Proxy",                "primary"),
    "proxy_allvpn": ("🛡️ All VPN",                   "primary"),
    "proxy_abc":    ("🔷 ABC Proxy",                  "primary"),
    "proxy_cli":    ("⚡ Cli Proxy",                  "primary"),
    "proxy_9proxy": ("9️⃣ 9Proxy",                    "primary"),
    "proxy_owl":    ("🦉 Owl Proxy",                  "primary"),
    "proxy_p5":     ("🟢 Proxy Provider 5",           "primary"),
    "proxy_p6":     ("🟣 Proxy Provider 6",           "primary"),
}

_KB_ROLE_COLORS = {role: default for role, (_label, default) in KB_BUTTON_ROLES.items()}

def get_kb_button_color(role=None):
    """একটা নির্দিষ্ট role এর জন্য বর্তমান admin-সেট color।
    role না দিলে সাধারণ ডিফল্ট (primary) রিটার্ন করে।"""
    if role is None:
        return "primary"
    return _KB_ROLE_COLORS.get(role, KB_BUTTON_ROLES.get(role, (None, "primary"))[1])

def set_kb_button_color(role, color):
    """Admin panel থেকে একটা নির্দিষ্ট role এর color পরিবর্তন করলে এখানে সেট হয়।"""
    if color not in _KB_COLOR_CHOICES:
        color = "primary"
    if role in KB_BUTTON_ROLES:
        _KB_ROLE_COLORS[role] = color

def load_kb_button_colors_from_dict(saved):
    """MySQL থেকে লোড করা dict দিয়ে in-memory cache আপডেট করো।"""
    if not isinstance(saved, dict):
        return
    for role, color in saved.items():
        if role in KB_BUTTON_ROLES and color in _KB_COLOR_CHOICES:
            _KB_ROLE_COLORS[role] = color

def KbBtn(text, style=None, role=None, **kwargs):
    """types.KeyboardButton এর color-safe wrapper।
    ⚠️ style প্যারামিটার এখন সরাসরি ব্যবহার হয় না — প্রতিটা কল সাইটে
    একটা `role` দেওয়া থাকে (যেমন role="back", role="cancel"), আর
    সেই role এর জন্য admin panel থেকে সেট করা color ব্যবহার হয়
    (get_kb_button_color(role))। role না দিলে style অথবা primary
    ডিফল্ট হিসেবে ব্যবহার হবে (backward-compat)।
    ✅ "normal" কালার সিলেক্ট করা থাকলে কোনো style পাঠানো হয় না —
    ফলে Telegram এ বাটনটি ডিফল্ট (কালারবিহীন) দেখাবে।
    ✅ role এর জন্য admin-সেট custom label (rename) থাকলে সেটাই
    ব্যবহার হবে (caller যেই default text পাঠাক না কেন)।
    """
    effective_style = get_kb_button_color(role) if role else (style or "primary")
    if effective_style == "normal":
        effective_style = None
    if role:
        _custom_label = get_kb_button_label(role)
        if _custom_label:
            text = _custom_label
    text = _apply_kb_emoji_override(text, role)
    return _make_styled(types.KeyboardButton, text, style=effective_style, **kwargs)

# ══════════════════════════════════════════════════════
# 😀 KEYBOARD BUTTON — PER-BUTTON EMOJI — Admin Panel Controlled
# ══════════════════════════════════════════════════════
# একই role গ্রুপিং ব্যবহার করে (উপরের color ফিচারের মতো), admin
# প্রতিটা বাটনের emoji আলাদাভাবে বদলাতে পারবে। প্রতিটা বাটনের
# টেক্সটের শুরুতে যে emoji থাকে (যেমন "🛍️ Buy Mail"), সেটাকে
# admin-সেট emoji দিয়ে replace করা হয়। কোনো override সেট না
# থাকলে (default) টেক্সট অপরিবর্তিত থাকবে — আগের মতোই কাজ করবে।
import re as _re_kbemoji
_KB_LEADING_EMOJI_RE = _re_kbemoji.compile(
    r'^([\U0001F1E6-\U0001F1FF\U0001F300-\U0001FAFF\U00002600-\U000027BF'
    r'\U00002190-\U000021FF\U00002300-\U000023FF\U000025A0-\U000025FF'
    r'\U00002B00-\U00002BFF\U0001F000-\U0001F0FF\uFE0F\u200D]+)(\s*)'
)

_KB_ROLE_EMOJIS = {}  # {role: custom emoji string} — না থাকলে ডিফল্ট emoji ব্যবহার হবে

def get_kb_button_emoji(role):
    """role এর জন্য বর্তমান admin-সেট custom emoji (না থাকলে None)।"""
    return _KB_ROLE_EMOJIS.get(role) or None

def set_kb_button_emoji(role, emoji):
    """Admin panel থেকে একটা নির্দিষ্ট role এর emoji পরিবর্তন করলে এখানে সেট হয়।
    emoji খালি/None দিলে override মুছে ডিফল্টে ফিরে যায়।"""
    if role not in KB_BUTTON_ROLES:
        return
    if emoji:
        _KB_ROLE_EMOJIS[role] = emoji
    else:
        _KB_ROLE_EMOJIS.pop(role, None)

def reset_kb_button_emoji(role):
    _KB_ROLE_EMOJIS.pop(role, None)

def load_kb_button_emojis_from_dict(saved):
    """MySQL থেকে লোড করা dict দিয়ে in-memory cache আপডেট করো।"""
    if not isinstance(saved, dict):
        return
    for role, emoji in saved.items():
        if role in KB_BUTTON_ROLES and emoji:
            _KB_ROLE_EMOJIS[role] = emoji

def _apply_kb_emoji_override(text, role):
    """role এর জন্য admin-সেট custom emoji থাকলে, টেক্সটের শুরুর emoji-টা
    বদলে দেয়। টেক্সটে emoji না থাকলে সামনে বসিয়ে দেয়। override না থাকলে
    টেক্সট অপরিবর্তিত রাখে।"""
    if not role or not isinstance(text, str):
        return text
    custom = _KB_ROLE_EMOJIS.get(role)
    if not custom:
        return text
    m = _KB_LEADING_EMOJI_RE.match(text)
    if m:
        rest = text[m.end():]
        return f"{custom} {rest}"
    return f"{custom} {text}"

# ══════════════════════════════════════════════════════
# ✏️ KEYBOARD BUTTON — PER-BUTTON RENAME (full text) — Admin Panel Controlled
# ══════════════════════════════════════════════════════
# Admin প্রতিটা keyboard বাটনের (যেমন Owl Proxy, ABC Proxy, 9Proxy...) পুরো
# নামটাই বদলে দিতে পারবে। override সেট থাকলে caller যেই default text
# পাঠাক না কেন (KB_BUTTON_ROLES এর হার্ডকোড করা লেবেল), সেটার বদলে এই
# custom label-ই সবখানে (keyboard বাটন + matching logic) ব্যবহার হবে।
_KB_ROLE_LABELS = {}  # {role: custom full label} — না থাকলে ডিফল্ট label ব্যবহার হবে

def get_kb_button_label(role):
    """role এর জন্য বর্তমান admin-সেট custom label (না থাকলে None)।"""
    if not role:
        return None
    return _KB_ROLE_LABELS.get(role) or None

def kb_label(role):
    """role এর জন্য এই মুহূর্তে দেখানো হবে এমন লেবেল — admin rename করে
    থাকলে সেটা, নাহলে KB_BUTTON_ROLES এর ডিফল্ট।"""
    custom = _KB_ROLE_LABELS.get(role)
    if custom:
        return custom
    return KB_BUTTON_ROLES.get(role, (role, "primary"))[0]

def set_kb_button_label(role, label):
    """Admin panel থেকে একটা নির্দিষ্ট role এর label (নাম) পরিবর্তন করলে এখানে সেট হয়।
    খালি/None দিলে override মুছে ডিফল্টে ফিরে যায়।"""
    if role not in KB_BUTTON_ROLES:
        return
    if label:
        _KB_ROLE_LABELS[role] = label
    else:
        _KB_ROLE_LABELS.pop(role, None)

def reset_kb_button_label(role):
    _KB_ROLE_LABELS.pop(role, None)

def load_kb_button_labels_from_dict(saved):
    """MySQL থেকে লোড করা dict দিয়ে in-memory cache আপডেট করো।"""
    if not isinstance(saved, dict):
        return
    for role, label in saved.items():
        if role in KB_BUTTON_ROLES and label:
            _KB_ROLE_LABELS[role] = label

# ══════════════════════════════════════════════════════
# 🔌 KEYBOARD BUTTON — ON/OFF (Show/Hide) — Admin Panel Controlled
# ══════════════════════════════════════════════════════
# Admin চাইলে নির্দিষ্ট কিছু keyboard বাটন (যেমন কোনো proxy provider
# আপাতত বন্ধ রাখতে চাইলে) সম্পূর্ণ লুকিয়ে (keyboard থেকে বাদ দিয়ে)
# রাখতে পারবেন — বাটন ডিলিট হয় না, শুধু keyboard এ দেখানো বন্ধ থাকে,
# যেকোনো সময় আবার On করলে সব ডেটা (প্রোডাক্ট/দাম/স্টক) অক্ষত থাকে।
_KB_ROLE_DISABLED = set()  # {role, ...} — এখানে থাকা role keyboard এ দেখানো হবে না

def is_kb_button_enabled(role):
    if not role:
        return True
    return role not in _KB_ROLE_DISABLED

def set_kb_button_enabled(role, enabled):
    """Admin panel থেকে একটা role On/Off করলে এখানে সেট হয়।"""
    if role not in KB_BUTTON_ROLES:
        return
    if enabled:
        _KB_ROLE_DISABLED.discard(role)
    else:
        _KB_ROLE_DISABLED.add(role)

def load_kb_button_disabled_from_dict(saved):
    """MySQL থেকে লোড করা dict দিয়ে in-memory cache আপডেট করো।"""
    _KB_ROLE_DISABLED.clear()
    if not isinstance(saved, dict):
        return
    for role, off in saved.items():
        if role in KB_BUTTON_ROLES and off:
            _KB_ROLE_DISABLED.add(role)

