# ===========================

API_TOKEN = os.environ.get('BOT_TOKEN', ' ')
ADMIN_ID = int(os.environ.get('ADMIN_ID', ' '))

def _cw_generic_crash_handler(call, handler_name, e):
    """
    🆕 FIX: বিভিন্ন callback worker (allvpn/admin_vpn/proxy provider/admin_proxyprov ইত্যাদি)
    এ আগে top-level exception handling ছিল না — background thread এ কোনো unexpected error
    হলে সেটা silently swallow হয়ে যেত (ইউজার কোনো response পেতো না, admin ও জানতো না)।
    এই একটা shared helper সব জায়গায় consistent ভাবে ব্যবহার করা হচ্ছে: ইউজারকে friendly
    error মেসেজ দেখানো + admin কে exact handler/button/traceback সহ notify করা
    (realproxy/edumail handler এর প্যাটার্ন অনুসরণ করে)।
    """
    tb = traceback.format_exc()
    _cw_user_id = str(call.message.chat.id) if getattr(call, "message", None) else "unknown"
    logging.error(f"{handler_name} crash | user={_cw_user_id} | data={getattr(call, 'data', '?')} | err={e}\n{tb}")
    try:
        _cw_lang = get_user_lang(_cw_user_id)
    except Exception:
        _cw_lang = "bn"
    try:
        bot.send_message(_cw_user_id,
            "⚠️ কিছু একটা ভুল হয়েছে, আবার চেষ্টা করুন।" if _cw_lang == "bn"
            else "⚠️ Something went wrong, please try again.")
    except Exception:
        pass
    try:
        tb_snip = tb[-1200:]
        bot.send_message(
            ADMIN_ID,
            f"⚠️ <b>{handler_name} crash</b>\n"
            f"👤 User: <code>{_cw_user_id}</code>\n"
            f"🔘 Button: <code>{getattr(call, 'data', '?')}</code>\n"
            f"❌ Error: <code>{e}</code>\n\n"
            f"<pre>{tb_snip}</pre>",
            parse_mode="HTML",
        )
    except Exception as _admin_err:
        logging.error(f"{handler_name} crash: failed to notify admin: {_admin_err}")
