def get_edu_mail_item_name(cat_short, item_no, db=None):
    """Edu Mail item বাটনের (admin-সেট করা) কাস্টম নাম রিটার্ন করে, না থাকলে
    আইটেম নাম্বার-ই ডিফল্ট নাম হিসেবে রিটার্ন করে।"""
    if db is None:
        db = load_db()
    names = db.get("settings", {}).get("edu_mail_names", {})
    return names.get(f"{cat_short}:{item_no}") or str(item_no)

def set_edu_mail_item_name(cat_short, item_no, new_name, db=None):
    """Edu Mail item বাটনের নাম admin panel থেকে সেভ করে (DB persist সহ)।"""
    if db is None:
        db = load_db()
    db.setdefault("settings", {}).setdefault("edu_mail_names", {})
    key = f"{cat_short}:{item_no}"
    db["settings"]["edu_mail_names"][key] = new_name
    update_db_path(f"/settings/edu_mail_names/{key}", new_name)

# ══════════════════════════════════════════════════════
# 📧 EDU MAIL — ক্যাটাগরির item Add / Delete / On-off (dynamic) — Admin Panel
# ══════════════════════════════════════════════════════
# ডিফল্ট অবস্থায় প্রতিটা ক্যাটাগরির item সংখ্যা EDU_MAIL_*_TOTAL_ITEMS constant
# দিয়ে নির্ধারিত (1..total, গ্যাপ ছাড়া)। Admin যখন Add/Delete করে, তখন থেকে
# সেই ক্যাটাগরির আসল active item লিস্ট DB তে সরাসরি সেভ হয়ে যায়।
# DB paths:
#   settings/edu_mail_active_items/{cat_short}   → [item_no, ...] (list)
#   settings/edu_mail_disabled_items/{cat_short} → [item_no, ...] (Off করা item)
#   settings/edu_mail_item_counter/{cat_short}   → int (পরের নতুন item নাম্বার —
#                                                   delete করা নাম্বার কখনো রিইউজ হয় না)

def _edu_mail_default_active_items(cat_short):
    """
    ⚠️ FIX: আগে এখানে 1..total পর্যন্ত সব নাম্বার ডিফল্ট active ধরা হতো,
    ফলে admin কিছু Add না করলেও প্রতিটা ক্যাটাগরিতে ২৫/১৬/৬/৯টা placeholder
    item বাটন এমনিই দেখা যেত — আর কোনো কাস্টম নাম সেট করা না থাকায়
    (get_edu_mail_item_name() এর ফলব্যাক) বাটনগুলোতে খালি নাম্বারই
    ("0", "1", "2" ...) দেখাতো। এখন থেকে admin ➕ নতুন Item Add না করা
    পর্যন্ত কোনো ডিফল্ট/placeholder item থাকবে না — খালি লিস্ট রিটার্ন করে।
    """
    return []

def get_edu_mail_active_items(cat_short, db=None):
    """এই ক্যাটাগরির বর্তমান active item নাম্বারগুলোর লিস্ট (sorted, ascending)।"""
    if db is None:
        db = load_db()
    saved = db.get("settings", {}).get("edu_mail_active_items", {}).get(cat_short)
    if saved is None:
        return _edu_mail_default_active_items(cat_short)
    try:
        return sorted(int(x) for x in saved)
    except (TypeError, ValueError):
        return _edu_mail_default_active_items(cat_short)

def _save_edu_mail_active_items(cat_short, items, db=None):
    if db is None:
        db = load_db()
    items_sorted = sorted(set(int(x) for x in items))
    db.setdefault("settings", {}).setdefault("edu_mail_active_items", {})
    db["settings"]["edu_mail_active_items"][cat_short] = items_sorted
    update_db_path(f"/settings/edu_mail_active_items/{cat_short}", items_sorted)
    return items_sorted

def get_edu_mail_disabled_items(cat_short, db=None):
    """এই ক্যাটাগরির Off করা item নাম্বারগুলোর set (user-facing লিস্টে দেখানো হয় না)।"""
    if db is None:
        db = load_db()
    saved = db.get("settings", {}).get("edu_mail_disabled_items", {}).get(cat_short) or []
    try:
        return set(int(x) for x in saved)
    except (TypeError, ValueError):
        return set()

def _save_edu_mail_disabled_items(cat_short, items_set, db=None):
    if db is None:
        db = load_db()
    items_sorted = sorted(set(int(x) for x in items_set))
    db.setdefault("settings", {}).setdefault("edu_mail_disabled_items", {})
    db["settings"]["edu_mail_disabled_items"][cat_short] = items_sorted
    update_db_path(f"/settings/edu_mail_disabled_items/{cat_short}", items_sorted)

def is_edu_mail_item_enabled(cat_short, item_no, db=None):
    """Item টা user-facing category page এ দেখানো হবে কিনা (Off না করা থাকলে True)।"""
    if db is None:
        db = load_db()
    return int(item_no) not in get_edu_mail_disabled_items(cat_short, db)

def set_edu_mail_item_enabled(cat_short, item_no, enabled, db=None):
    """Admin panel থেকে item On/Off টগল করে (DB persist সহ)।"""
    if db is None:
        db = load_db()
    disabled = get_edu_mail_disabled_items(cat_short, db)
    item_no = int(item_no)
    if enabled:
        disabled.discard(item_no)
    else:
        disabled.add(item_no)
    _save_edu_mail_disabled_items(cat_short, disabled, db)

def _get_edu_mail_item_counter(cat_short, db=None):
    if db is None:
        db = load_db()
    saved = db.get("settings", {}).get("edu_mail_item_counter", {}).get(cat_short)
    if saved is None:
        return _edu_mail_mgr_cats()[cat_short]["total"]
    try:
        return int(saved)
    except (TypeError, ValueError):
        return _edu_mail_mgr_cats()[cat_short]["total"]

def _save_edu_mail_item_counter(cat_short, value, db=None):
    if db is None:
        db = load_db()
    db.setdefault("settings", {}).setdefault("edu_mail_item_counter", {})
    db["settings"]["edu_mail_item_counter"][cat_short] = int(value)
    update_db_path(f"/settings/edu_mail_item_counter/{cat_short}", int(value))

def add_edu_mail_item(cat_short, db=None):
    """এই ক্যাটাগরিতে একটা নতুন (ফাঁকা) item বাটন যোগ করে — নতুন item নাম্বার
    রিটার্ন করে। নতুন নাম্বার সবসময় আগের সব (delete করা সহ) নাম্বারের চেয়ে বড়,
    তাই আগে delete করা কোনো item এর পুরনো data-র সাথে confuse হবে না।"""
    if db is None:
        db = load_db()
    active = get_edu_mail_active_items(cat_short, db)
    counter = _get_edu_mail_item_counter(cat_short, db)
    new_no = max(counter, max(active) if active else 0) + 1
    active.append(new_no)
    _save_edu_mail_active_items(cat_short, active, db)
    _save_edu_mail_item_counter(cat_short, new_no, db)
    return new_no

def delete_edu_mail_item(cat_short, item_no, db=None):
    """একটা item সম্পূর্ণ ডিলিট করে — active লিস্ট, নাম, website connection,
    price, description — সব জায়গা থেকে। ⚠️ এটা irreversible (Off করলে reversible থাকে)।"""
    if db is None:
        db = load_db()
    item_no = int(item_no)
    # ⚠️ FIX: প্রতিটা ধাপ আলাদাভাবে try/except দিয়ে গার্ড করা হলো — কোনো একটা
    # ধাপে (যেমন corrupt/অপ্রত্যাশিত টাইপ ডেটার কারণে) সমস্যা হলেও বাকি
    # ধাপগুলো (বিশেষত active লিস্ট থেকে বাদ দেওয়া) যেন থেমে না যায়, তাই item
    # সবসময় শেষ পর্যন্ত ডিলিট হয়ে যাবে।
    try:
        active = get_edu_mail_active_items(cat_short, db)
        if item_no in active:
            active.remove(item_no)
            _save_edu_mail_active_items(cat_short, active, db)
    except Exception as e:
        logging.error(f"delete_edu_mail_item active-list error ({cat_short}:{item_no}): {e}")
    try:
        disabled = get_edu_mail_disabled_items(cat_short, db)
        if item_no in disabled:
            disabled.discard(item_no)
            _save_edu_mail_disabled_items(cat_short, disabled, db)
    except Exception as e:
        logging.error(f"delete_edu_mail_item disabled-list error ({cat_short}:{item_no}): {e}")
    # নাম মুছে ফেলা
    try:
        key = f"{cat_short}:{item_no}"
        if db.get("settings", {}).get("edu_mail_names", {}).pop(key, None) is not None:
            update_db_path(f"/settings/edu_mail_names/{key}", None)
    except Exception as e:
        logging.error(f"delete_edu_mail_item name-cleanup error ({cat_short}:{item_no}): {e}")
    # Website connection (bulkmail) + virtual product unregister
    try:
        unset_edu_mail_bulkmail_id(cat_short, item_no, db)
    except Exception as e:
        logging.error(f"delete_edu_mail_item unlink error ({cat_short}:{item_no}): {e}")
    # Price/description মুছে ফেলা
    try:
        v_name = edu_mail_virtual_product_name(cat_short, item_no)
        if v_name in db.get("products", {}):
            del db["products"][v_name]
            update_db_path(f"/products/{v_name}", None)
        if v_name in db.get("product_details", {}):
            del db["product_details"][v_name]
            update_db_path(f"/product_details/{v_name}", None)
    except Exception as e:
        logging.error(f"delete_edu_mail_item price/desc cleanup error ({cat_short}:{item_no}): {e}")

def _edu_mail_mgr_cat_view():
    """Edu Mail Manager → কোন ক্যাটাগরির item rename করবে সেটা বেছে নেওয়ার মেনু।"""
    markup = types.InlineKeyboardMarkup(row_width=1)
    for cat_short, meta in _edu_mail_mgr_cats().items():
        markup.add(InlineBtn(
            f"📧 {meta['label']} ({meta['total']}টা)", style="primary",
            callback_data=f"admin_edumgr_cat_{cat_short}"
        ))
    markup.add(InlineBtn("🔙 Admin Panel", style="primary", callback_data="back_admin"))
    text = (
        "📧 <b>Edu Mail Manager</b>\n"
        "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        "কোন ক্যাটাগরির item এর নাম বদলাবেন?"
    )
    return text, markup

def _edu_mail_mgr_item_list_view(cat_short, page=1, db=None):
    """একটা ক্যাটাগরির item গুলোর লিস্ট দেখায় (বর্তমান নাম ও status আইকনসহ) —
    rename/on-off/delete করার জন্য, আর উপরে নতুন item Add করার বাটন।"""
    if db is None:
        db = load_db()
    meta = _edu_mail_mgr_cats()[cat_short]
    active_items = get_edu_mail_active_items(cat_short, db)
    disabled = get_edu_mail_disabled_items(cat_short, db)
    total = len(active_items)
    page_size = 10
    total_pages = max(1, (total + page_size - 1) // page_size)
    page = max(1, min(page, total_pages))

    start = (page - 1) * page_size
    end = min(page * page_size, total)
    page_items = active_items[start:end]

    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn("➕ নতুন Item Add করুন", style="success", callback_data=f"admin_edumgr_add_{cat_short}"))
    for n in page_items:
        cur_name = get_edu_mail_item_name(cat_short, n, db)
        bm_id = get_edu_mail_bulkmail_id(cat_short, n, db)
        cc_pid = EDU_MAIL_CODECRAFT_ITEMS.get((cat_short, str(n)))
        if n in disabled:
            icon = "⚪"
        elif bm_id or cc_pid:
            icon = "✅"
        else:
            icon = "⚠️"
        markup.add(InlineBtn(f"{icon} {n}. {cur_name}", callback_data=f"admin_edumgr_item_{cat_short}_{n}"))

    nav_row = []
    if page > 1:
        nav_row.append(InlineBtn("⬅️ Prev", callback_data=f"admin_edumgr_pg_{cat_short}_{page-1}"))
    if page < total_pages:
        nav_row.append(InlineBtn("Next ➡️", callback_data=f"admin_edumgr_pg_{cat_short}_{page+1}"))
    if nav_row:
        markup.add(*nav_row)

    markup.add(InlineBtn("🔙 Back", style="primary", callback_data="admin_edu_mail_manager"))

    if total:
        text = (
            f"📧 <b>{meta['label']}</b>\n"
            "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
            "✅ কানেক্টেড | ⚠️ ID সেট নেই | ⚪ Off\n"
            + (f"Page {page}/{total_pages} — " if total_pages > 1 else "")
            + "কোনটা edit করবেন?"
        )
    else:
        text = (
            f"📧 <b>{meta['label']}</b>\n"
            "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
            "এখনো কোনো item নেই — উপরের ➕ বাটনে নতুন item Add করুন।"
        )
    return text, markup

# ══════════════════════════════════════════════════════
# 🔗 EDU MAIL ITEM ↔ BULKMAIL.SHOP PRODUCT ID — Admin Panel Mapping
# ══════════════════════════════════════════════════════
# প্রতিটা Edu Mail ক্যাটাগরির (0-1day / 2-7days / 8-13days / 14-90days)
# প্রতিটা নাম্বার বাটনকে (item) admin panel থেকে bulkmail.shop এর
# একটা নির্দিষ্ট website product ID এর সাথে connect করা যাবে —
# ঠিক "Edu Mail 24hr" প্রোডাক্টের মতোই। একবার ID সেট হয়ে গেলে সেই
# আইটেম বাটনে ক্লিক করলে bulkmail API থেকে live stock আনা হবে,
# আর normal product detail + Buy 1pcs/Bulk Buy ফ্লো কাজ করবে —
# কারণ আমরা runtime এ এটাকে API_PRODUCTS/BULKMAIL_PRODUCTS এ একটা
# "virtual product" হিসেবে register করে দিচ্ছি (ঠিক Edu Mail 24hr
# এর মতোই source="bulkmail")।
# DB path: /settings/edu_mail_bulkmail_ids/{cat_short}:{item_no} → int product_id

_EDU_MAIL_VIRTUAL_PREFIXES = None  # lazy-computed cache

def _is_edu_mail_virtual_product(name):
    """
    Edu Mail ক্যাটাগরির item ভার্চুয়াল প্রোডাক্ট হলে True রিটার্ন করে
    (যেমন "Edu Mail 0-1day #3")। এই প্রোডাক্টগুলো শুধুমাত্র Edu Mail
    ক্যাটাগরির নিজস্ব inline বাটন দিয়েই access হওয়ার কথা — তাই এগুলোকে
    মূল Shop menu বা admin এর সাধারণ "product picker" reply-keyboard/লিস্ট
    এ আলাদা করে দেখানো হয় না (সেখানে already inline বাটন আছে)।
    """
    global _EDU_MAIL_VIRTUAL_PREFIXES
    if not isinstance(name, str):
        return False
    if _EDU_MAIL_VIRTUAL_PREFIXES is None:
        _EDU_MAIL_VIRTUAL_PREFIXES = tuple(meta["label"] + " #" for meta in _edu_mail_mgr_cats().values())
    return name.startswith(_EDU_MAIL_VIRTUAL_PREFIXES)

_VPN_CATEGORY_PREFIXES = None  # lazy-computed cache

def _is_vpn_category_product(name):
    """
    🛡️ All VPN ক্যাটাগরির প্রোডাক্ট হলে True রিটার্ন করে
    (যেমন "Vpn 3days - MyVPN", বা পুরনো/জেনেরিক "VPN - MyVPN")।
    এই প্রোডাক্টগুলো শুধুমাত্র VPN ক্যাটাগরির নিজস্ব inline বাটন
    (allvpn_cat_3d/6d/14d/30d) দিয়েই access হওয়ার কথা — তাই এগুলোকে
    মূল Shop menu বা "Choose a product" reply-keyboard এ আলাদা ফ্ল্যাট
    প্রোডাক্ট হিসেবে দেখানো হয় না (ঠিক Edu Mail ভার্চুয়াল প্রোডাক্টের মতোই)।
    """
    global _VPN_CATEGORY_PREFIXES
    if not isinstance(name, str):
        return False
    if _VPN_CATEGORY_PREFIXES is None:
        prefixes = set(f"{label} - " for label in ALLVPN_CAT_LABELS.values())
        # ✅ cat_label lookup fail করলে কোডে "VPN" ফলব্যাক লেবেল ব্যবহার হয়
        #    (ALLVPN_CAT_LABELS.get(cat_data, "VPN")) — সেই কেস, এবং
        #    day-based সাব-ক্যাটাগরি চালু হওয়ার আগের পুরনো/legacy naming
        #    ("VPN - Nord" এর মতো) — দুইটাই এখানে ধরা হচ্ছে।
        prefixes.add("VPN - ")
        _VPN_CATEGORY_PREFIXES = tuple(prefixes)
    return name.startswith(_VPN_CATEGORY_PREFIXES)

_PROXY_PROVIDER_PREFIXES = None  # lazy-computed cache

def _is_proxy_provider_product(name):
    """
    🌐 ABC Proxy / Cli Proxy / 9Proxy / Owl Proxy প্রোভাইডারের প্রোডাক্ট হলে
    True রিটার্ন করে (যেমন "🔷 ABC Proxy - Package 1")। এই প্রোডাক্টগুলো
    শুধুমাত্র সেই প্রোভাইডারের নিজস্ব inline বাটন দিয়েই access হওয়ার কথা —
    তাই এগুলোকে মূল "Buy Mail" Shop menu বা "Choose a product" reply-keyboard
    এ আলাদা ফ্ল্যাট প্রোডাক্ট হিসেবে দেখানো হয় না (ঠিক VPN/Edu Mail এর মতোই)।
    """
    global _PROXY_PROVIDER_PREFIXES
    if not isinstance(name, str):
        return False
    if _PROXY_PROVIDER_PREFIXES is None:
        _PROXY_PROVIDER_PREFIXES = tuple(f"{label} - " for label in PROXY_PROVIDER_LABELS.values())
    return name.startswith(_PROXY_PROVIDER_PREFIXES)

def get_visible_products(db):
    """
    সব প্রোডাক্টের লিস্ট রিটার্ন করে, কিন্তু নিচের internal/sub-item
    প্রোডাক্টগুলো বাদ দিয়ে — কারণ এগুলো শুধু তাদের নিজস্ব ডেডিকেটেড
    ম্যানেজার/ইনলাইন মেনু দিয়েই অ্যাক্সেস/ম্যানেজ হওয়ার কথা, তাই এগুলোর
    raw internal নাম (যেমন "Product1 Item 2") কোনো generic keyboard
    বাটন/product-picker লিস্টে (Edit Price, Delete Product, Flash Sale,
    Upload Stock ইত্যাদি) আলাদা করে দেখানোর দরকার নেই — ঠিক
    _shop_default_item_keys() এ যেভাবে ফিল্টার করা হয় সেভাবেই:
      • Edu Mail item ভার্চুয়াল প্রোডাক্ট (Edu Mail 0-1day #1 এর মতো নাম)
      • Product1 এর sub-item ("Product1 Item N")
      • Product2 এর sub-item ("Product2 Item N")
      • All VPN ক্যাটাগরির প্রোডাক্ট (Vpn 3days - ... এর মতো)
      • Proxy provider এর প্রোডাক্ট (ABC Proxy - ... এর মতো)
    """
    return [
        p for p in db.get("products", {}).keys()
        if not _is_edu_mail_virtual_product(p)
        and not _is_product1_sub_product(p)
        and not _is_product2_sub_product(p)
        and not _is_product3bulk_sub_product(p)
        and not _is_vpn_category_product(p)
        and not _is_proxy_provider_product(p)
    ]

def edu_mail_virtual_product_name(cat_short, item_no):
    """একটা নির্দিষ্ট Edu Mail item এর জন্য stable virtual product name
    (rename করলেও এটা বদলায় না, তাই price/description/order history অক্ষত থাকে)।"""
    meta = _edu_mail_mgr_cats()[cat_short]
    return f"{meta['label']} #{item_no}"

def get_edu_mail_bulkmail_id(cat_short, item_no, db=None):
    """এই item এর জন্য admin-সেট bulkmail.shop product ID রিটার্ন করে, না থাকলে None।"""
    if db is None:
        db = load_db()
    m = db.get("settings", {}).get("edu_mail_bulkmail_ids", {})
    v = m.get(f"{cat_short}:{item_no}")
    if v in (None, ""):
        return None
    try:
        return int(v)
    except (TypeError, ValueError):
        return None

def register_edu_mail_virtual_product(cat_short, item_no, product_id, db=None):
    """
    Edu Mail item কে runtime এ একটা bulkmail-backed "virtual product" হিসেবে
    register করে — API_PRODUCTS, BULKMAIL_PRODUCTS dict এ যোগ করে এবং db["products"]
    এ entry না থাকলে 0 দিয়ে initialize করে (admin পরে price সেট করবে)।
    এটার পর show_product_detail_with_subnav() ও generic purchase engine
    ঠিক "Edu Mail 24hr" এর মতোই এই product কে handle করবে।
    """
    name = edu_mail_virtual_product_name(cat_short, item_no)
    API_PRODUCTS[name] = {"source": "bulkmail", "product_id": int(product_id)}
    BULKMAIL_PRODUCTS[name] = int(product_id)
    if db is not None:
        db.setdefault("products", {})
        if name not in db["products"]:
            db["products"][name] = 0
    return name

# ─── Edu Mail item ↔ codecraftdeveloper.com hardcoded mapping ───
# (cat_short, item_no হিসেবে key) → codecraftdeveloper.com product ID।
# এই ম্যাপিং এ থাকা item গুলো admin এর "Website Product ID" (bulkmail.shop)
# কানেক্ট করার দরকার নেই — বট নিজেই startup এ codecraft product হিসেবে
# register করে দেয়। বর্তমানে শুধু Edu Mail 14-90days এর #৮ নাম্বার বাটন
# ("primes mail") এই ম্যাপিং এ আছে।
EDU_MAIL_CODECRAFT_ITEMS = {
    ("1490", "8"): EDU_MAIL_1490_ITEM8_PRODUCT_ID,
}

def register_edu_mail_codecraft_product(cat_short, item_no, product_id, db=None):
    """
    Edu Mail item কে runtime এ একটা codecraftdeveloper.com-backed "virtual product"
    হিসেবে register করে — API_PRODUCTS dict এ যোগ করে দেয়। db["products"] এ এই
    item এর জন্য price entry একদম না থাকলে (প্রথমবার) 0 দিয়ে initialize করা হয় —
    ওয়েবসাইটের (codecraftdeveloper.com) price এখানে কখনো auto-apply করা হয় না,
    কারণ price/description/name — সবকিছু ১০০% admin (Edu Mail Manager থেকে)
    নিজে সেট করবে, ওয়েবসাইটের প্রাইস শুধু stock check এর জন্য ব্যবহার হয়।
    একবার admin price সেট করলে (এমনকি 0 দিলেও) সেটা আর কখনো ওভাররাইট হবে না।
    """
    name = edu_mail_virtual_product_name(cat_short, item_no)
    API_PRODUCTS[name] = {"source": "codecraft", "product_id": int(product_id)}
    if db is not None:
        db.setdefault("products", {})
        if name not in db["products"]:
            db["products"][name] = 0  # ⚠️ Price শূন্য থাকা অবস্থায় purchase block থাকবে — admin কে সেট করতে হবে
    return name

def set_edu_mail_bulkmail_id(cat_short, item_no, product_id, db=None):
    """Admin panel থেকে একটা Edu Mail item এর সাথে website (bulkmail.shop)
    product ID connect করলে এখানে DB persist হয় এবং সাথে সাথে runtime এ
    virtual product register হয়ে যায়।"""
    if db is None:
        db = load_db()
    db.setdefault("settings", {}).setdefault("edu_mail_bulkmail_ids", {})
    key = f"{cat_short}:{item_no}"
    db["settings"]["edu_mail_bulkmail_ids"][key] = int(product_id)
    update_db_path(f"/settings/edu_mail_bulkmail_ids/{key}", int(product_id))
    return register_edu_mail_virtual_product(cat_short, item_no, product_id, db)

def unset_edu_mail_bulkmail_id(cat_short, item_no, db=None):
    """Admin চাইলে একটা item থেকে website product ID connection মুছে দিতে পারবে।"""
    if db is None:
        db = load_db()
    key = f"{cat_short}:{item_no}"
    if db.get("settings", {}).get("edu_mail_bulkmail_ids", {}).pop(key, None) is not None:
        update_db_path(f"/settings/edu_mail_bulkmail_ids/{key}", None)
    name = edu_mail_virtual_product_name(cat_short, item_no)
    API_PRODUCTS.pop(name, None)
    BULKMAIL_PRODUCTS.pop(name, None)

def init_all_edu_mail_virtual_products(db=None):
    """Bot startup এ MySQL এ persist করা সব Edu Mail ↔ bulkmail ID mapping
    আবার runtime এ (API_PRODUCTS/BULKMAIL_PRODUCTS) register করে দেয়,
    কারণ এগুলো in-memory dict — restart এ খালি হয়ে যায়।"""
    try:
        if db is None:
            db = load_db()
        saved = db.get("settings", {}).get("edu_mail_bulkmail_ids", {})
        count = 0
        for key, pid in saved.items():
            if not pid:
                continue
            try:
                cat_short, item_no = key.split(":", 1)
            except ValueError:
                continue
            register_edu_mail_virtual_product(cat_short, item_no, pid, db)
            count += 1
        if count:
            print(f"✅ Edu Mail ↔ bulkmail.shop mapping restored: {count}টা item")

        # ✅ codecraftdeveloper.com এর সাথে hardcoded connect করা item গুলো (যেমন
        # Edu Mail 14-90days #৮ — "primes mail") রেজিস্টার করো + ডিফল্ট নাম সেট করো
        cc_count = 0
        for (cc_cat, cc_item), cc_pid in EDU_MAIL_CODECRAFT_ITEMS.items():
            try:
                register_edu_mail_codecraft_product(cc_cat, cc_item, cc_pid, db)
                # ডিফল্ট বাটন নাম "primes mail" — admin আগে থেকে rename না করে থাকলে
                existing_name = db.get("settings", {}).get("edu_mail_names", {}).get(f"{cc_cat}:{cc_item}")
                if not existing_name:
                    set_edu_mail_item_name(cc_cat, cc_item, EDU_MAIL_1490_ITEM8_NAME, db)
                cc_count += 1
            except Exception as _cc_e:
                logging.error(f"codecraft item register error ({cc_cat}:{cc_item}): {_cc_e}")
        if cc_count:
            print(f"✅ Edu Mail ↔ codecraftdeveloper.com mapping registered: {cc_count}টা item")
    except Exception as e:
        logging.error(f"init_all_edu_mail_virtual_products error: {e}")

def _edu_mail_mgr_item_detail_view(cat_short, item_no, db=None):
    """একটা নির্দিষ্ট Edu Mail item এর admin detail menu — rename, website product ID
    সংযুক্ত করা, price ও description সেট করার বাটনসহ।"""
    if db is None:
        db = load_db()
    meta = _edu_mail_mgr_cats()[cat_short]
    cur_name = get_edu_mail_item_name(cat_short, item_no, db)
    # ⚠️ FIX: bm_id লুকআপ কখনো কখনো পুরনো/corrupt টাইপ ডেটার কারণে exception
    # ছুঁড়তে পারে (str/dict mismatch) — একটা item এর জন্য এটা ঘটলে যেন পুরো
    # menu (এবং তার সাথে 🗑️ Delete বাটন) না হারায়, তাই try/except দিয়ে গার্ড করা হলো।
    try:
        bm_id = get_edu_mail_bulkmail_id(cat_short, item_no, db)
    except Exception as e:
        logging.error(f"_edu_mail_mgr_item_detail_view bm_id lookup error ({cat_short}:{item_no}): {e}")
        bm_id = None
    cc_pid = EDU_MAIL_CODECRAFT_ITEMS.get((cat_short, str(item_no)))
    v_name = edu_mail_virtual_product_name(cat_short, item_no)
    _price_raw = db.get("products", {}).get(v_name, 0)
    try:
        cur_price = float(_price_raw) if not isinstance(_price_raw, (int, float)) else _price_raw
    except (TypeError, ValueError):
        cur_price = 0
    _details_raw = db.get("product_details", {}).get(v_name, {})
    cur_desc = _details_raw.get("description", "") if isinstance(_details_raw, dict) else ""
    connected = bool(bm_id) or bool(cc_pid)

    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn(f"✏️ নাম বদলান (বর্তমান: {cur_name})", style="primary",
                          callback_data=f"admin_edumgr_rename_{cat_short}_{item_no}"))
    if cc_pid:
        markup.add(InlineBtn(f"🆔 CodeCraft Product ID: {cc_pid} (সংযুক্ত)", style="success",
                              callback_data=f"admin_edumgr_item_{cat_short}_{item_no}"))
    else:
        id_label = f"🆔 Website Product ID: {bm_id}" if bm_id else "🆔 Website Product ID সেট করুন (Connect)"
        markup.add(InlineBtn(id_label, style=("success" if bm_id else "primary"),
                              callback_data=f"admin_edumgr_setid_{cat_short}_{item_no}"))
    if connected:
        markup.add(InlineBtn(f"💰 Price সেট করুন (বর্তমান: {cur_price} BDT)", style="primary",
                              callback_data=f"edit_price_{v_name}"))
        markup.add(InlineBtn("📝 Description সেট করুন", style="primary",
                              callback_data=f"edit_desc_{v_name}"))
        if bm_id:
            markup.add(InlineBtn("❌ Website Connection মুছুন", style="danger",
                                  callback_data=f"admin_edumgr_unlink_{cat_short}_{item_no}"))

    is_off = int(item_no) in get_edu_mail_disabled_items(cat_short, db)
    if is_off:
        markup.add(InlineBtn("🟢 On করুন (ইউজাররা আবার দেখবে)", style="success",
                              callback_data=f"admin_edumgr_toggle_{cat_short}_{item_no}"))
    else:
        markup.add(InlineBtn("🔴 Off করুন (ইউজাররা দেখবে না)", style="danger",
                              callback_data=f"admin_edumgr_toggle_{cat_short}_{item_no}"))
    markup.add(InlineBtn("🗑️ এই Item Delete করুন", style="danger",
                          callback_data=f"admin_edumgr_del_{cat_short}_{item_no}"))
    markup.add(InlineBtn("🔙 Back", style="primary", callback_data=f"admin_edumgr_cat_{cat_short}"))

    text = (
        f"📧 <b>{meta['label']} — #{item_no}</b>\n"
        "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"📛 নাম: <code>{cur_name}</code>\n"
        f"{'⚪ Off — ইউজাররা এই বাটন দেখবে না' if is_off else '🟢 On — ইউজাররা এই বাটন দেখবে'}\n"
    )
    if cc_pid:
        text += f"🆔 CodeCraft Product ID: <code>{cc_pid}</code>\n"
    else:
        text += f"🆔 Website Product ID: <code>{bm_id if bm_id else 'সেট করা নেই'}</code>\n"
    if connected:
        text += (
            f"💰 Price: <code>{cur_price} BDT</code>\n"
            f"📝 Description: <code>{'সেট আছে' if cur_desc else 'নেই'}</code>\n"
            "\n✅ এই item ইউজারদের কাছে live stock/price/description সহ কেনার জন্য দেখানো হবে।"
        )
    else:
        text += "\n⚠️ Website Product ID সেট না করা পর্যন্ত ইউজাররা এই বাটনে শুধু \"শীঘ্রই আসছে\" মেসেজ দেখবে।"
    return text, markup

def _edu_mail_open_item(call, user_id, db, lang, cat_short, cat_label, item_no, back_callback):
    """
    Edu Mail ক্যাটাগরির যেকোনো item বাটনে ক্লিক করলে এই ফাংশন কল হয়।
    - Admin যদি এই item এ website (bulkmail.shop) product ID connect করে রাখে,
      তাহলে ঠিক "Edu Mail 24hr" এর মতোই live stock/price/description + Buy 1pcs/Bulk Buy
      দেখানো হবে (একই generic product detail ও purchase ইঞ্জিন ব্যবহার হয়)।
    - Connect করা না থাকলে আগের মতোই "শীঘ্রই আসছে" প্লেসহোল্ডার মেসেজ দেখাবে।
    - 🆕 FIX: item connected থাকা অবস্থায় স্টক 0/আউট থাকলে এখন buy page না দেখিয়ে
      সরাসরি "⚠️ স্টক আউট!" popup alert দেখানো হয় (Product1/Product2 এর মতোই
      একই প্যাটার্ন) — বাটনের নাম/অবস্থান একই থাকে, শুধু ক্লিক করলে popup আসে।
      স্টক থাকলে আগের মতোই স্বাভাবিক buy page দেখাবে।
    """
    # ✅ codecraftdeveloper.com এর সাথে hardcoded connect করা item (যেমন Edu Mail
    # 14-90days #৮ — "primes mail") — bulkmail এর "Website Product ID" কানেক্ট
    # করার দরকার নেই, সরাসরি সেই API দিয়ে live stock/price/description + Buy
    # 1pcs/Bulk Buy দেখানো হবে, ঠিক অন্য প্রোডাক্টের মতোই।
    cc_pid = EDU_MAIL_CODECRAFT_ITEMS.get((cat_short, str(item_no)))
    if cc_pid:
        v_name = register_edu_mail_codecraft_product(cat_short, item_no, cc_pid, db)
        if get_stock_count(v_name) <= 0:
            try:
                bot.answer_callback_query(call.id, "⚠️ স্টক আউট!", show_alert=True)
            except Exception:
                pass
            return
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        item_display_name = get_edu_mail_item_name(cat_short, item_no, db)
        show_product_detail_with_subnav(user_id, v_name, db, display_name=item_display_name)
        return

    bm_id = get_edu_mail_bulkmail_id(cat_short, item_no, db)
    if not bm_id:
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        item_label = get_edu_mail_item_name(cat_short, item_no, db)
        text = (
            f"📧 <b>{cat_label} — {item_label}</b>\n\nএই আইটেমের জন্য service শীঘ্রই যুক্ত করা হবে।"
            if lang == "bn" else
            f"📧 <b>{cat_label} — {item_label}</b>\n\nService for this item will be added soon."
        )
        markup = types.InlineKeyboardMarkup(row_width=1)
        markup.add(InlineBtn("🔙 Back" if lang != "bn" else "🔙 ব্যাক", callback_data=back_callback))
        _edu_mail_edit(call, text, markup)
        return
    # ✅ Website product ID connected — bulkmail.shop এর সাথে live connect
    v_name = register_edu_mail_virtual_product(cat_short, item_no, bm_id, db)
    if get_stock_count(v_name) <= 0:
        try:
            bot.answer_callback_query(call.id, "⚠️ স্টক আউট!", show_alert=True)
        except Exception:
            pass
        return
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    item_display_name = get_edu_mail_item_name(cat_short, item_no, db)
    show_product_detail_with_subnav(user_id, v_name, db, display_name=item_display_name)

