# ═══════════════════════════════════════════════════════════
# 🧹 AUTO CLEANUP — order / deposit_requests / verified_trxids
# ১০ দিনের বেশি পুরনো হলে অটোম্যাটিক ডিলেট হয়ে যাবে
# ═══════════════════════════════════════════════════════════
DATA_RETENTION_DAYS = 10

def _parse_bd_datetime(date_str):
    """'%d/%m/%Y %I:%M %p' ফরম্যাটের স্ট্রিং কে timezone-aware datetime এ পার্স করে।
    পার্স করতে না পারলে None রিটার্ন করে (এন্ট্রি সেক্ষেত্রে ডিলেট হবে না, নিরাপদ থাকবে)।"""
    if not date_str:
        return None
    try:
        return BD_TZ.localize(datetime.strptime(date_str, "%d/%m/%Y %I:%M %p"))
    except Exception:
        return None

def cleanup_old_deposit_requests(db=None):
    """DATA_RETENTION_DAYS দিনের বেশি পুরনো deposit_requests এন্ট্রি মুছে ফেলো।"""
    if db is None:
        db = load_db()
    deposits = db.get("deposit_requests", {})
    if not deposits:
        return 0
    now_dt = datetime.now(BD_TZ)
    to_delete = []
    for req_id, req in list(deposits.items()):
        # approved/rejected হলে approved_date, না হলে date ব্যবহার করো
        date_str = req.get("approved_date") or req.get("date")
        entry_dt = _parse_bd_datetime(date_str)
        if entry_dt and (now_dt - entry_dt).days >= DATA_RETENTION_DAYS:
            to_delete.append(req_id)
    for req_id in to_delete:
        db["deposit_requests"].pop(req_id, None)
        _fb_ref(f"/deposit_requests/{req_id}").delete()
    if to_delete:
        _update_db_cache_in_place(db)
        logging.info(f"🧹 Deposit cleanup: {len(to_delete)} টা {DATA_RETENTION_DAYS} দিনের পুরনো deposit request মুছে ফেলা হয়েছে।")
    return len(to_delete)

def cleanup_old_orders(db=None):
    """প্রতিটা ইউজারের orders লিস্ট থেকে DATA_RETENTION_DAYS দিনের বেশি পুরনো order মুছে ফেলো।"""
    if db is None:
        db = load_db()
    users = db.get("users", {})
    if not users:
        return 0
    now_dt = datetime.now(BD_TZ)
    total_removed = 0
    for uid, udata in list(users.items()):
        orders = udata.get("orders", [])
        if not orders:
            continue
        kept = []
        removed_here = False
        for order in orders:
            if not isinstance(order, dict):
                removed_here = True  # 🩹 corrupted non-dict entry — drop it during cleanup
                continue
            # 🆕 real_proxy টাইপ অর্ডার এই cleanup থেকে বাদ — "My Proxy" ফিচারের জন্য
            # এই order গুলো লাগে, তাই মেয়াদ (retention days) যাই থাকুক এগুলো কখনো
            # অটো-ডিলিট হবে না। প্রক্সি নিজে expire হয়ে গেলেও এই রেকর্ড থেকে যাবে।
            if order.get("type") == "real_proxy":
                kept.append(order)
                continue
            entry_dt = _parse_bd_datetime(order.get("date", ""))
            if entry_dt and (now_dt - entry_dt).days >= DATA_RETENTION_DAYS:
                removed_here = True
                total_removed += 1
            else:
                kept.append(order)
        if removed_here:
            udata["orders"] = kept
            update_db_path(f"/users/{uid}/orders", kept)
    if total_removed:
        _update_db_cache_in_place(db)
        logging.info(f"🧹 Order cleanup: {total_removed} টা {DATA_RETENTION_DAYS} দিনের পুরনো order মুছে ফেলা হয়েছে।")
    return total_removed

def cleanup_old_verified_trxids(db=None):
    """DATA_RETENTION_DAYS দিনের বেশি পুরনো verified_trxids এন্ট্রি মুছে ফেলো
    (যেই trxid গুলোর তারিখ verified_trxids_dates এ ট্র্যাক করা আছে, পুরনো/legacy
    entry যেগুলোর তারিখ জানা নেই সেগুলো নিরাপত্তার জন্য রেখে দেওয়া হয়)।"""
    if db is None:
        db = load_db()
    trx_list = db.get("verified_trxids", [])
    trx_dates = db.get("verified_trxids_dates", {})
    if not trx_list or not trx_dates:
        return 0
    now_dt = datetime.now(BD_TZ)
    to_delete = []
    for trx_id in list(trx_list):
        entry_dt = _parse_bd_datetime(trx_dates.get(trx_id, ""))
        if entry_dt and (now_dt - entry_dt).days >= DATA_RETENTION_DAYS:
            to_delete.append(trx_id)
    if not to_delete:
        return 0
    for trx_id in to_delete:
        if trx_id in db["verified_trxids"]:
            db["verified_trxids"].remove(trx_id)
        db.get("verified_trxids_dates", {}).pop(trx_id, None)
        _fb_ref(f"/verified_trxids_dates/{trx_id}").delete()
    # পুরো verified_trxids লিস্ট re-write করো (index-based dict হিসেবে সেভ হয়)
    _EXECUTOR.submit(_update_db_path_sync, "/verified_trxids",
                     {str(i): v for i, v in enumerate(db.get("verified_trxids", []))})
    _update_db_cache_in_place(db)
    logging.info(f"🧹 Verified TrxID cleanup: {len(to_delete)} টা {DATA_RETENTION_DAYS} দিনের পুরনো trxid মুছে ফেলা হয়েছে।")
    return len(to_delete)

def cleanup_old_data():
    """order / deposit_requests / verified_trxids — সবগুলো {DATA_RETENTION_DAYS} দিনের
    পুরনো ডাটা একসাথে cleanup করো।"""
    try:
        db = load_db()
        n1 = cleanup_old_deposit_requests(db)
        n2 = cleanup_old_orders(db)
        n3 = cleanup_old_verified_trxids(db)
        if n1 or n2 or n3:
            logging.info(f"🧹 Auto cleanup সম্পন্ন — deposits:{n1} orders:{n2} trxids:{n3}")
    except Exception as e:
        logging.error(f"cleanup_old_data error: {e}", exc_info=True)

def data_retention_worker():
    """Background thread — প্রতি ঘণ্টায় একবার ১০ দিনের পুরনো
    order/deposit/verified_trxids ডাটা অটোম্যাটিক ডিলেট করে।"""
    _time_module.sleep(90)  # bot fully start হওয়ার সময় দাও
    while True:
        try:
            cleanup_old_data()
        except Exception as e:
            logging.error(f"data_retention_worker error: {e}", exc_info=True)
        _time_module.sleep(60 * 60)  # ১ ঘণ্টা পর পর


