# ═══════════════════════════════════════════════════════════
# 🌐 PROXY PROVIDER BUTTONS — ABC Proxy / Cli Proxy / 9Proxy / Owl Proxy
# ✅ প্রতিটা প্রোভাইডার বাটনে ক্লিক করলে সেই প্রোভাইডারের নিজস্ব প্রোডাক্ট
#    বাটন গুলো (ডিফল্ট ৪টা) দেখায় — ঠিক All VPN এর মতোই একটা normal
#    product হিসেবে কাজ করে (Price/Stock/Single-Buy/Bulk-Buy সহ)।
# ✅ Admin Panel থেকে প্রতিটা প্রোডাক্ট বাটনের নাম Rename, নতুন বাটন Add,
#    এবং বিদ্যমান বাটন Delete করা যায় — সম্পূর্ণ admin-controlled।
# ═══════════════════════════════════════════════════════════
PROXY_PROVIDERS = [
    ("proxy_abc",    KB_BUTTON_ROLES["proxy_abc"][0]),
    ("proxy_cli",    KB_BUTTON_ROLES["proxy_cli"][0]),
    ("proxy_9proxy", KB_BUTTON_ROLES["proxy_9proxy"][0]),
    ("proxy_owl",    KB_BUTTON_ROLES["proxy_owl"][0]),
    ("proxy_p5",     KB_BUTTON_ROLES["proxy_p5"][0]),
    ("proxy_p6",     KB_BUTTON_ROLES["proxy_p6"][0]),
]
PROXY_PROVIDER_KEYS   = [k for k, _label in PROXY_PROVIDERS]
PROXY_PROVIDER_LABELS = dict(PROXY_PROVIDERS)

# provider_key → DB এর top-level list key (VPN_CAT_DB_KEY এর একই প্যাটার্ন)
PROXY_PROVIDER_DB_KEY = {
    "proxy_abc":    "proxy_products_abc",
    "proxy_cli":    "proxy_products_cli",
    "proxy_9proxy": "proxy_products_9proxy",
    "proxy_owl":    "proxy_products_owl",
    "proxy_p5":     "proxy_products_p5",
    "proxy_p6":     "proxy_products_p6",
}

PROXY_PROVIDER_DEFAULT_COUNT = 4  # প্রথমবার প্রতিটা প্রোভাইডারে ডিফল্ট কয়টা প্রোডাক্ট বাটন থাকবে


def get_proxy_products(db, provider_key):
    """একটা প্রোভাইডারের প্রোডাক্ট-নামের লিস্ট (DB থেকে) — order-preserving।"""
    key = PROXY_PROVIDER_DB_KEY.get(provider_key)
    if not key:
        return []
    return list(db.get(key) or [])


def _proxy_save_provider_list(db, provider_key, product_list):
    """একটা প্রোভাইডারের প্রোডাক্ট-লিস্ট DB তে targeted-write করো (top-level list key)।"""
    key = PROXY_PROVIDER_DB_KEY.get(provider_key)
    if not key:
        return
    db[key] = product_list
    update_db_path(f"/{key}", product_list)


def _proxy_display_name(product_name, provider_key=None):
    """Internal storage key থেকে provider-prefix ("ABC Proxy - ") বাদ দিয়ে
    অ্যাডমিনের টাইপ করা আসল নামটা রিটার্ন করে (storage key কখনো বদলায় না)।"""
    if not isinstance(product_name, str):
        return product_name
    if provider_key:
        lbl = PROXY_PROVIDER_LABELS.get(provider_key)
        if lbl and product_name.startswith(lbl + " - "):
            return product_name[len(lbl) + 3:]
    for lbl in PROXY_PROVIDER_LABELS.values():
        p = lbl + " - "
        if product_name.startswith(p):
            return product_name[len(p):]
    return product_name


def _proxy_delete_product_everywhere(db, provider_key, product_name):
    """একটা প্রোভাইডার প্রোডাক্ট সম্পূর্ণ ডিলিট করো — provider list, price, details, stock file — সব জায়গা থেকে।"""
    products = get_proxy_products(db, provider_key)
    if product_name in products:
        products.remove(product_name)
        _proxy_save_provider_list(db, provider_key, products)
    if product_name in db.get("products", {}):
        del db["products"][product_name]
        _EXECUTOR.submit(lambda: _fb_ref(f"/products/{product_name}").delete())
    if product_name in db.get("product_details", {}):
        del db["product_details"][product_name]
        _EXECUTOR.submit(lambda: _fb_ref(f"/product_details/{product_name}").delete())
    _update_db_cache_in_place(db)
    try:
        stock_path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
        if os.path.exists(stock_path):
            os.remove(stock_path)
    except Exception:
        pass
    invalidate_stock_cache(product_name)


def _proxy_rename_product(db, provider_key, old_name, new_display_name):
    """একটা প্রোভাইডার প্রোডাক্টের নাম বদলায় — provider list, products dict,
    product_details, ও stock file সব জায়গায় rename করে। রিটার্ন করে নতুন internal name।"""
    lbl = PROXY_PROVIDER_LABELS.get(provider_key, "")
    new_name = f"{lbl} - {new_display_name}" if lbl else new_display_name
    if new_name == old_name:
        return old_name
    products = get_proxy_products(db, provider_key)
    if old_name in products:
        idx = products.index(old_name)
        products[idx] = new_name
        _proxy_save_provider_list(db, provider_key, products)
    if old_name in db.get("products", {}):
        price = db["products"].pop(old_name)
        db["products"][new_name] = price
        update_db_path(f"/products/{new_name}", price)
        _EXECUTOR.submit(lambda: _fb_ref(f"/products/{old_name}").delete())
    if old_name in db.get("product_details", {}):
        detail = db["product_details"].pop(old_name)
        db["product_details"][new_name] = detail
        update_db_path(f"/product_details/{new_name}", detail)
        _EXECUTOR.submit(lambda: _fb_ref(f"/product_details/{old_name}").delete())
    _update_db_cache_in_place(db)
    try:
        old_path = os.path.join(STOCK_DIR, f"{old_name}.xlsx")
        new_path = os.path.join(STOCK_DIR, f"{new_name}.xlsx")
        if os.path.exists(old_path):
            os.rename(old_path, new_path)
    except Exception:
        pass
    invalidate_stock_cache(old_name)
    invalidate_stock_cache(new_name)
    return new_name


def auto_init_proxy_provider_products():
    """Bot startup এ প্রথমবার প্রতিটা প্রোভাইডারে (ABC/Cli/9Proxy/Owl) ডিফল্ট
    ৪টা করে প্রোডাক্ট বাটন তৈরি করে (price=0), যাতে অ্যাডমিন Proxy Provider
    Manager থেকে নাম/দাম/স্টক বসিয়ে সাথে সাথে বিক্রি চালু করতে পারেন।
    যেই প্রোভাইডারে ইতিমধ্যে প্রোডাক্ট আছে সেটা ছোঁয়া হয় না।"""
    try:
        db = load_db()
        changed = False
        db.setdefault("products", {})
        for provider_key, label in PROXY_PROVIDERS:
            products = get_proxy_products(db, provider_key)
            if products:
                continue
            new_list = []
            for i in range(1, PROXY_PROVIDER_DEFAULT_COUNT + 1):
                name = f"{label} - Package {i}"
                if name not in db["products"]:
                    db["products"][name] = 0
                new_list.append(name)
            _proxy_save_provider_list(db, provider_key, new_list)
            changed = True
            print(f"✅ Proxy provider default products initialized: {label}")
        if changed:
            update_db_path("/products", db["products"])
            _update_db_cache_in_place(db)
    except Exception as e:
        logging.error(f"auto_init_proxy_provider_products error: {e}")


def _proxy_products_view(provider_key, lang, db=None):
    """একটা প্রোভাইডারের প্রোডাক্ট লিস্ট (নাম—দাম—স্টক) + Back/Cancel বাটন সহ মার্কআপ বানায়।"""
    if db is None:
        db = load_db()
    label = PROXY_PROVIDER_LABELS.get(provider_key, "Proxy")
    products = get_proxy_products(db, provider_key)
    if lang == "bn":
        title = f"🌐 <b>{label}</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        title += "একটা প্রোডাক্ট বেছে নিন:" if products else "⚠️ এই প্রোভাইডারে এখনো কোনো প্রোডাক্ট যোগ করা হয়নি।"
    else:
        title = f"🌐 <b>{label}</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        title += "Select a product:" if products else "⚠️ No products added in this provider yet."
    markup = types.InlineKeyboardMarkup(row_width=1)
    prod_btns = []
    for i, name in enumerate(products, start=1):
        price = float(db.get("products", {}).get(name) or 0)
        stock = get_stock_count(name)
        stock_icon = "✅" if stock > 0 else "🔴"
        price_txt = str(int(price)) if price == int(price) else f"{price:.2f}"
        btn_label = f"{_proxy_display_name(name, provider_key)} — {price_txt}BDT ({stock_icon}{stock}pcs)"
        prod_btns.append(InlineBtn(btn_label, style="primary", callback_data=f"{provider_key}_p{i}"))
    markup.add(*prod_btns)  # একটার নিচে একটা
    markup.add(
        InlineBtn("❌ ক্যানসেল" if lang == "bn" else "❌ Cancel",
                   style="danger", callback_data="proxyprov_cancel"),
    )
    return title, markup


def show_proxy_provider_products(user_id, provider_key, lang=None):
    """একটা প্রোভাইডার বাটনে (ABC/Cli/9Proxy/Owl) ক্লিক করলে তার প্রোডাক্ট বাটন গুলো (নতুন মেসেজ হিসেবে) পাঠায়।"""
    if lang is None:
        lang = get_user_lang(user_id)
    title, markup = _proxy_products_view(provider_key, lang)
    bot.send_message(user_id, title, parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: (
    any(call.data.startswith(f"{_k}_p") for _k in PROXY_PROVIDER_KEYS)
    or call.data in ("proxyprov_back", "proxyprov_cancel")
))
def handle_proxy_provider_products_callback(call):
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_proxy_provider_products_worker, call)


def _handle_proxy_provider_products_worker(call):
    try:
        _handle_proxy_provider_products_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_proxy_provider_products_callback", e)

def _handle_proxy_provider_products_worker_impl(call):
    user_id = str(call.message.chat.id)
    data = call.data
    lang = get_user_lang(user_id)
    db = load_db()

    if data == "proxyprov_cancel":
        try:
            bot.edit_message_text(
                "❌ ক্যানসেল করা হয়েছে।" if lang == "bn" else "❌ Cancelled.",
                chat_id=call.message.chat.id, message_id=call.message.message_id,
                parse_mode="HTML")
        except Exception:
            try:
                bot.delete_message(call.message.chat.id, call.message.message_id)
            except Exception:
                pass
        return

    if data == "proxyprov_back":
        try:
            bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        handle_buy_proxy(user_id, db)
        return

    # একটা নির্দিষ্ট প্রোডাক্ট বাটনে ক্লিক করলে (যেমন proxy_abc_p2) → normal
    # প্রোডাক্ট ডিটেইল (নাম/দাম/স্টক + single/bulk buy বাটন) দেখাও — বটের
    # বিদ্যমান delivery engine (show_product_detail_with_subnav) reuse করা হচ্ছে
    for provider_key in PROXY_PROVIDER_KEYS:
        prefix = provider_key + "_p"
        if data.startswith(prefix):
            products = get_proxy_products(db, provider_key)
            try:
                idx = int(data[len(prefix):])
                prod_name = products[idx - 1]
            except Exception:
                return
            show_product_detail_with_subnav(
                user_id, prod_name, db,
                display_name=_proxy_display_name(prod_name, provider_key),
                edit_message_id=call.message.message_id,
                origin="buy_proxy",
            )
            return


