    markup.add(InlineBtn("➕ Add New Product", style="success", callback_data=f"admin_proxyprov_add_{provider_key}"))
    markup.add(InlineBtn("🔙 Back to Providers", style="primary", callback_data="admin_proxyprov_manage"))
    text = (f"🌐 <b>{label} — Products</b>\n\n"
            f"{'কোনো প্রোডাক্ট নেই।' if not products else 'এডিট করার জন্য একটা প্রোডাক্ট বেছে নিন:'}")
