@bot.callback_query_handler(func=lambda call: call.data.startswith("admin_proxyprov_") or call.data == "admin_proxyprov_manage")
def handle_admin_proxyprov_callback(call):
    if not _proxyprov_admin_guard(call):
        bot.answer_callback_query(call.id, "❌ Admin access only!", show_alert=True)
        return
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_admin_proxyprov_callback_worker, call)


def _handle_admin_proxyprov_callback_worker(call):
    try:
        _handle_admin_proxyprov_callback_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_admin_proxyprov_callback", e)

def _handle_admin_proxyprov_callback_worker_impl(call):
    chat_id = call.message.chat.id
    mid = call.message.message_id
    data = call.data

    if data == "admin_proxyprov_manage":
        show_proxyprov_admin_providers(chat_id, mid); return

    if data == "admin_proxyprov_back_panel":
        try:
            bot.delete_message(chat_id, mid)
        except Exception:
            pass
        show_admin_panel(str(chat_id)); return

    if data.startswith("admin_proxyprov_cat_"):
        provider_key = data[len("admin_proxyprov_cat_"):]
        show_proxyprov_admin_product_list(chat_id, provider_key, mid); return

    if data.startswith("admin_proxyprov_add_"):
        provider_key = data[len("admin_proxyprov_add_"):]
        msg = bot.send_message(chat_id,
            f"🆕 <b>{PROXY_PROVIDER_LABELS.get(provider_key,'Proxy')} — নতুন প্রোডাক্টের নাম লিখুন:</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_proxyprov_add_step1(m, provider_key))
        return

    if data.startswith("admin_proxyprov_prod_"):
        idx = data[len("admin_proxyprov_prod_"):]
        show_proxyprov_admin_product_detail(chat_id, idx, mid); return

    if data.startswith("admin_proxyprov_rename_"):
        idx = data[len("admin_proxyprov_rename_"):]
        sess = _proxyprov_admin_sessions.get(str(ADMIN_ID), {})
        entry = sess.get("idx_map", {}).get(idx)
        if not entry:
            bot.answer_callback_query(call.id, "❌ Session expired!", show_alert=True); return
        provider_key, name = entry
        msg = bot.send_message(chat_id,
            f"✏️ <b>'{_proxy_display_name(name, provider_key)}' এর নতুন নাম লিখুন:</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
