def admin_proxyprov_rename_step(message, idx):
    chat_id = message.chat.id
    sess = _proxyprov_admin_sessions.get(str(ADMIN_ID), {})
    entry = sess.get("idx_map", {}).get(idx)
    if not entry:
        bot.send_message(chat_id, "❌ Session expired! আবার Provider এ ঢুকুন।"); return
    provider_key, name = entry
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_proxyprov_admin_product_list(chat_id, provider_key); return
    new_display = (message.text or "").strip()
