    if new_name != name and new_name in db.get("products", {}):
        msg = bot.send_message(chat_id, f"❌ <b>'{new_display}' নামে প্রোডাক্ট আগেই আছে!</b> ভিন্ন নাম দিন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
