    _proxy_rename_product(db, provider_key, name, new_display)
    bot.send_message(chat_id, f"✅ <b>নাম পরিবর্তন হয়েছে:</b> {new_display}",
        parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
