def _rp_find_current_parent_id(db, user_id, pid, pkg_id, details):
    """এই প্রক্সির বর্তমান parent_proxy_id বের করে — আগে order এ সেভ করা আছে কিনা দেখে,
    না থাকলে (পুরনো order) country/city/service_provider মিলিয়ে /parent-proxies থেকে
    ম্যাচিং parent খুঁজে বের করে। Switch Conn Type ও Random Location এ ব্যবহার হয়,
    যেখানে বর্তমান parent_proxy_id লাগে (একই লোকেশনে protocol পাল্টাতে হলে)।"""
    order = next((o for o in _rp_get_user_proxy_orders(db, user_id) if str(o.get("proxy_account_id")) == str(pid)), None)
    if order and order.get("parent_proxy_id"):
        return order.get("parent_proxy_id")
    if not pkg_id or not details:
        return None
    parents = realproxy_get_parent_proxies(pkg_id)
    country = str(details.get("country_name") or "").strip().upper()
    city = str(details.get("city_name") or "").strip().upper()
    provider = str(details.get("service_provider") or "").strip().upper()
    for p in parents:
        if (str(p.get("country_name", "")).strip().upper() == country and
                str(p.get("city_name", "")).strip().upper() == city and
                str(p.get("service_provider", "")).strip().upper() == provider):
            return p.get("id")
    return None

# 🆕 (Point 1 fix) — Real Proxy এর মেয়াদ এখন থেকে ক্রয়ের মুহূর্ত (timestamp)
# থেকে লোকালি হিসাব করা হয়, provider API এর raw "expire_at" টেক্সটের ওপর
# ভরসা না করে (সেটার ফরম্যাট/টাইমজোন ভিন্ন হতে পারে)। order এ সেভ করা
# "expires_at_ts" (purchase_ts + duration) থেকে বাকি সময় Day/Hour/Minute
# আকারে কাউন্ট-ডাউন করে দেখানো হয়, ঠিক ক্রয় করার মুহূর্ত থেকেই।
def _rp_format_expiry_countdown(expires_at_ts, lang="en"):
    """expires_at_ts (epoch seconds) থেকে বর্তমান সময় পর্যন্ত বাকি মেয়াদ
    'X Day Y Hour Z Min' ফরম্যাটে রিটার্ন করে। মেয়াদ শেষ হয়ে গেলে Expired দেখায়।
    এর পাশাপাশি বাংলাদেশ টাইমজোনে exact expiry তারিখ-সময়ও যোগ করে দেয়।"""
    if not expires_at_ts:
        return None
    now_ts = _time_module.time()
    remaining = expires_at_ts - now_ts
    exact_dt = datetime.fromtimestamp(expires_at_ts, BD_TZ).strftime("%d/%m/%y %I:%M %p")
    if remaining <= 0:
        return ("❌ মেয়াদ শেষ হয়ে গেছে" if lang == "bn" else "❌ Expired") + f" ({exact_dt})"
    remaining = int(remaining)
    days, rem = divmod(remaining, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, _ = divmod(rem, 60)
    if lang == "bn":
        countdown = f"{days} দিন {hours} ঘন্টা {minutes} মিনিট বাকি"
    else:
        countdown = f"{days} Day {hours} Hour {minutes} Min left"
    return f"{countdown} ({exact_dt})"


def _rp_get_order_by_pid(db, user_id, pid):
    """user_id এর কেনা real proxy order গুলোর মধ্যে থেকে একটা নির্দিষ্ট
    proxy_account_id (pid) এর order record খুঁজে বের করে (expires_at_ts
    এর মতো লোকালি-ট্র্যাক করা তথ্যের জন্য দরকার হয়)।"""
    return next(
        (o for o in _rp_get_user_proxy_orders(db, user_id) if str(o.get("proxy_account_id")) == str(pid)),
        None
    )


def _rp_details_text(details, expires_at_ts=None, lang="en"):
    """একটা proxy details dict থেকে স্ক্রিনশটের ফরম্যাটে ফুল ডিটেইলস টেক্সট বানায়
    (ID/IP/Port/Username/Password/Location/Provider/Expire/Status) — My Proxy অ্যাকশন
    মেনু আর rpm_details_ দুই জায়গাতেই একই ফরম্যাট ব্যবহারের জন্য শেয়ার করা হয়।
    expires_at_ts দেওয়া থাকলে (order এ লোকালি সেভ করা থাকলে) ক্রয়ের মুহূর্ত
    থেকে হিসাব করা Day/Hour/Min countdown দেখানো হয়; না থাকলে provider API এর
    raw expire_at টেক্সট fallback হিসেবে দেখানো হয়।"""
    status = details.get("status", "?")
    countdown = _rp_format_expiry_countdown(expires_at_ts, lang) if expires_at_ts else None
    expire_display = countdown if countdown else details.get('expire_at', '')
    lines = (
        f"🆔 ID: <code>{details.get('id','')}</code>\n"
        f"🌐 IP: <code>{details.get('ip_addr','')}</code>\n"
        f"🔌 Port: <code>{details.get('port','')}</code>\n"
        f"👤 Username: <code>{details.get('username','') or 'N/A (IP-auth)'}</code>\n"
        f"🔑 Password: <code>{details.get('password','') or 'N/A (IP-auth)'}</code>\n"
        f"📍 Location: <code>{details.get('city_name','?')}, {details.get('country_name','?')}</code>\n"
        f"📡 Provider: <code>{details.get('service_provider','?')}</code>\n"
        f"📅 Expire: <code>{expire_display}</code>\n"
        f"📶 Status: <code>{status}</code>"
    )
    return f"🌐 <b>Proxy Details</b>\n\n{lines}"

def _rp_render_action_menu(call, db, lang, user_id, pid):
    """একটা প্রক্সি সিলেক্ট করার পর সরাসরি ফুল Proxy Details দেখায় (স্ক্রিনশট অনুযায়ী),
    সাথে অ্যাকশন বাটন গুলো (Refresh / Renew.../ Switch Conn Type / Change Location / Random Location)।"""
    details = realproxy_get_proxy_details(pid)
    if not details:
        _rp_edit(call, "❌ প্রক্সির তথ্য পাওয়া যায়নি।" if lang == "bn" else "❌ Could not fetch proxy details.", None)
        return
    _order_for_pid = _rp_get_order_by_pid(db, user_id, pid)
    title = _rp_details_text(details, expires_at_ts=(_order_for_pid or {}).get("expires_at_ts"), lang=lang)
    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.row(
        InlineBtn("🔄 Refresh" if lang != "bn" else "🔄 রিফ্রেশ", callback_data=f"rpm_view_{pid}"),
    )
    status = str(details.get("status") or "").upper()
    if status == "ACTIVE":
        def _renew_btn(code):
            _c, bn, en, _d = next(o for o in _RP_RENEW_OPTIONS if o[0] == code)
            return InlineBtn(en if lang != "bn" else bn, callback_data=f"rpm_renew_{code}_{pid}")
        markup.row(_renew_btn("2h"), _renew_btn("12h"))
        markup.row(_renew_btn("1d"), _renew_btn("3d"))
        markup.row(_renew_btn("1w"), _renew_btn("2w"))
        markup.row(_renew_btn("1m"), InlineBtn("🔀 Switch Conn Type" if lang != "bn" else "🔀 কানেকশন টাইপ পাল্টান", callback_data=f"rpm_switch_{pid}"))
        markup.row(
            InlineBtn("🔄 Change Location" if lang != "bn" else "🔄 লোকেশন চেঞ্জ", callback_data=f"rpm_change_{pid}"),
            InlineBtn("🎲 Random Location" if lang != "bn" else "🎲 র‍্যান্ডম লোকেশন", callback_data=f"rpm_random_{pid}"),
        )
    markup.row(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_menu_my"))
    _rp_edit(call, title, markup)



def _rp_edit(call, text, markup):
    """একই মেসেজ edit করে ভিতরেই পরের ধাপ দেখায় (tree navigation) — কোনো বাটনে ক্লিক করলে
    নতুন আলাদা মেসেজ না এসে, ওই একই বাটনের/মেসেজের ভিতর থেকেই রিপ্লাই বদলে যায়।
    edit fail করলে (যেমন মেসেজ অনেক পুরনো/ডিলিটেড) fallback হিসেবে নতুন মেসেজ পাঠায়।"""
    try:
        bot.edit_message_text(text, chat_id=call.message.chat.id, message_id=call.message.message_id,
                               parse_mode="HTML", reply_markup=markup)
    except Exception:
        try:
            bot.send_message(call.message.chat.id, text, parse_mode="HTML", reply_markup=markup)
        except Exception as e:
            logging.error(f"_rp_edit fallback send failed: {e}")


def _rp_show(call, state, text, markup):
    """
    🌳 ROOT MENU বাটন (New Proxy / My Proxy / Price / Terms) থেকে প্রথমবার ঢুকলে
    নতুন মেসেজ পাঠায় (root menu টা তখনও আলাদাভাবে দেখা যাবে, স্ক্রিনশটের মতো) —
    কিন্তু তারপর সেই নতুন মেসেজের ভিতরে যত ধাপ (package → country → city →
    provider → ... ) এগোনো হয়, সবগুলো একই মেসেজ edit করে দেখানো হয় (tree navigation),
    কোনো নতুন মেসেজ আসবে না।

    state["in_new_message"] flag দিয়ে ট্র্যাক করা হয় — এই flow-এ এর আগে কখনো নতুন
    মেসেজ পাঠানো হয়েছে কিনা। প্রথমবার (flag না থাকলে) নতুন মেসেজ পাঠিয়ে flag সেট
    করে দেয়; এরপর থেকে (যেমন Price তালিকায় ফিরে আসা — 'rp_menu_price' যেটা back-target
    হিসেবেও ব্যবহৃত হয়) সবসময় _rp_edit (in-place edit) ব্যবহার হয়।
    রুট মেনুতে ফিরে গেলে (rp_back_to_realproxy_root) state.clear() হয়ে যায়, ফলে
    এই flag আবার রিসেট হয়ে যায় — পরের বার কোনো বাটনে ক্লিক করলে আবার নতুন মেসেজ আসবে।
    """
    if not state.get("in_new_message"):
        try:
            bot.send_message(call.message.chat.id, text, parse_mode="HTML", reply_markup=markup)
            state["in_new_message"] = True
            return
        except Exception as e:
            logging.error(f"_rp_show send failed, falling back to edit: {e}")
    _rp_edit(call, text, markup)


class _RpFakeChat:
    def __init__(self, chat_id):
        self.id = chat_id

class _RpFakeMessage:
    def __init__(self, chat_id, message_id=None):
        self.chat = _RpFakeChat(chat_id)
        self.message_id = message_id

class _RpFakeUser:
    def __init__(self, user_id):
        self.id = user_id

class _RpFakeCall:
    """✅ Keyboard (reply) Back বাটন থেকে ট্রিগার হওয়া 'back' অ্যাকশনের জন্য একটা ছদ্ম
    callback-call অবজেক্ট — বিদ্যমান callback-based render ফাংশনগুলো (যেগুলো
    call.message.chat.id ব্যবহার করে _rp_edit() কল করে) হুবহু রিইউজ করার জন্য।
    message_id ইচ্ছাকৃতভাবে None রাখা হয়েছে, যাতে _rp_edit() এর edit চেষ্টা fail করে
    নতুন মেসেজ পাঠানোর fallback এ যায় (keyboard থেকে ইনলাইন-লিস্ট স্ক্রিনে ফেরার সময়
    নতুন মেসেজ পাঠানোই স্বাভাবিক — এডিট করার মতো আগের ইনলাইন মেসেজ এখানে নেই)।"""
    def __init__(self, user_id):
        uid_int = int(user_id)
        self.message = _RpFakeMessage(uid_int, None)
        self.from_user = _RpFakeUser(uid_int)
        self.id = None

def _rp_fake_call(user_id):
    return _RpFakeCall(user_id)

def _rp_root_menu_view(lang):
    """Real Proxy রুট মেনু: New Proxy / My Proxy / Price / Terms and conditions — পাশাপাশি (২টা করে এক সারিতে) inline বাটন,
    সাথে নিচে শুধু Cancel (লাল) বাটন — এটাই সবচেয়ে প্রথম ধাপ, তাই এখানে আলাদা Back এর দরকার নেই।"""
    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.row(
        InlineBtn("🆕 New Proxy" if lang != "bn" else "🆕 নতুন প্রক্সি", callback_data="rp_menu_new"),
        InlineBtn("📂 My Proxy" if lang != "bn" else "📂 আমার প্রক্সি", callback_data="rp_menu_my"),
    )
    markup.row(
        InlineBtn("💲 Price" if lang != "bn" else "💲 প্রাইস", callback_data="rp_menu_price"),
        InlineBtn("📄 Terms and conditions" if lang != "bn" else "📄 শর্তাবলী", callback_data="rp_menu_terms"),
    )
    markup.row(
        InlineBtn(_rp_cancel_label(lang), style="danger", callback_data="rp_cancel"),
    )
    title = "🌐 <b>Real Proxy</b>\n\nএকটা অপশন বেছে নিন 👇" if lang == "bn" else "🌐 <b>Real Proxy</b>\n\nChoose an option 👇"
    return title, markup

def _rp_render_root_menu(call, lang):
    title, markup = _rp_root_menu_view(lang)
    _rp_edit(call, title, markup)

def start_realproxy_flow(user_id, db=None):
    lang = get_user_lang(user_id, db)
    if not REALPROXY_BASE_URL or not REALPROXY_EMAIL or not REALPROXY_PASSWORD:
        msg = ("⚠️ Real Proxy এখনো কনফিগার করা হয়নি। Admin কে জানান।" if lang == "bn"
               else "⚠️ Real Proxy is not configured yet. Please contact admin.")
        bot.send_message(user_id, msg, parse_mode="HTML")
        return
    _rp_state[str(user_id)] = {}
    title, markup = _rp_root_menu_view(lang)
    bot.send_message(user_id, title, parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("rp_") or call.data.startswith("rpm_"))
def handle_realproxy_callback(call):
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_realproxy_callback_worker, call)


# ─── প্রতিটা ধাপের রেন্ডারার — forward এবং back দুই দিক থেকেই কল হয় ───

def _rp_render_packages(call, db, lang, state):
    packages = realproxy_get_visible_packages()
    if not packages:
        _rp_show(call, state, "❌ কোনো প্যাকেজ পাওয়া যায়নি।" if lang == "bn" else "❌ No packages found.", None)
        return
    markup = types.InlineKeyboardMarkup(row_width=1)
    for pkg in packages:
        markup.add(InlineBtn(f"📦 {pkg.get('package_name','?')}",
                              callback_data=f"rp_pkg_{pkg.get('id')}"))
    markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_realproxy_root"))
    title = "🌐 <b>Real Proxy</b>\n\nএকটা প্যাকেজ বেছে নিন 👇" if lang == "bn" else "🌐 <b>Real Proxy</b>\n\nChoose a package 👇"
    _rp_show(call, state, title, markup)

def _rp_render_countries(call, db, lang, state):
    countries = realproxy_get_countries(state.get("pkg_id"))
    if not countries:
        _rp_edit(call, "❌ কোনো country পাওয়া যায়নি।" if lang == "bn" else "❌ No countries found.", None)
        return
    # 🔧 REMOVED: আগে এখানে একটা "live stock pre-filter" ছিল যেটা country/city/
    # provider — প্রতিটা ধাপেই আগেভাগে অনুমান করে ফেলতো কোথায় স্টক আছে কি নেই
    # (একগুচ্ছ /parent-proxies + /countries + /cities কল একসাথে করে ম্যাপ বানিয়ে)।
    # কিন্তু official Real Proxy bot নিজেই country/city/provider ধাপে কোনো
    # pre-filter করে না — শুধু শেষ ধাপে (নির্দিষ্ট city+provider বেছে নেওয়ার পর)
    # /parent-proxies কল করে আসল লিস্ট দেখায় (স্ক্রিনশটে দেখা গেছে স্টক আসলে ছিল,
    # কিন্তু এই আগাম-ফিল্টার ভুলভাবে সব বাদ দিয়ে "No country available" দেখাচ্ছিল)।
    # তাই এখন এখানে official bot-এর মতোই সব country সরাসরি দেখানো হচ্ছে —
    # আসল availability check শুধু _rp_render_parent_proxies() ধাপেই হবে, যেটা
    # প্রতিটা নির্দিষ্ট service_provider_city_id এর জন্য সরাসরি API কল করে, তাই
    # ভুল হওয়ার সুযোগ নেই।
    back_cb = f"rpm_view_{state.get('migrate_id')}" if state.get("mode") == "migrate" else "rp_back_to_pkg"
    markup = types.InlineKeyboardMarkup(row_width=2)
    btns = [InlineBtn(f"🌍 {c.get('country_name','?')}",
                       callback_data=f"rp_country_{c.get('id')}") for c in countries]
    markup.add(*btns)
    # 🔄 Migrate (location change) mode এ package selection নেই, তাই back করলে সরাসরি
    # প্রক্সির detail view এ ফিরে যাবে, package list এ না।
    markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data=back_cb))
    _rp_edit(call, "একটা Country বেছে নিন 👇" if lang == "bn" else "Choose a country 👇", markup)

