def _rp_parent_label(p):
    """স্ক্রিনশটের স্টাইলে একটা parent proxy-র লেবেল বানায়: 5G 8000 (http) / 9000 (socks) (rotation 30m)"""
    tech = p.get("technology", "?")
    http_port = p.get("http_port", "?")
    socks_port = p.get("socks_port", "?")
    rotation = p.get("rotation_time")
    tail = f"(rotation {rotation}m)" if rotation else "(full)"
    return f"{tech} {http_port} (http) / {socks_port} (socks) {tail}"

def _rp_render_parent_proxies(call, db, lang, state):
    raw_parents, had_error, err = realproxy_get_parent_proxies(
        state.get("pkg_id"), service_provider_city_id=state.get("service_provider_city_id"),
        country_id=state.get("country_id"), city_id=state.get("city_id"), return_error=True
    )
    markup_back = types.InlineKeyboardMarkup(row_width=1)
    markup_back.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_provider"))

    # 🔧 BUG FIX: API call টাই fail করলে (token/network/param issue) সেটাকে
    # genuine "no proxy available" হিসেবে না দেখিয়ে আসল error দেখাও, যাতে ভুল
    # ইনফরমেশনে ইউজার বিভ্রান্ত না হয় আর Admin দ্রুত root cause ধরতে পারে।
    if had_error:
        friendly_err = _realproxy_friendly_error(err)
        logging.error(f"_rp_render_parent_proxies: realproxy API error for user, showing error to user: {err}")
        _rp_edit(call, (f"⚠️ Proxy লিস্ট আনতে সমস্যা হয়েছে: {friendly_err}\n\nআবার চেষ্টা করুন।" if lang == "bn"
                         else f"⚠️ Couldn't fetch the proxy list: {friendly_err}\n\nPlease try again."), markup_back)
        try:
            bot.send_message(ADMIN_ID, f"⚠️ Real Proxy /parent-proxies API error (user {call.from_user.id}): {err}")
        except Exception:
            pass
        return

    parents = [p for p in raw_parents if _rp_is_parent_usable(p)]
    if not parents:
        logging.info(f"_rp_render_parent_proxies: {len(raw_parents)} raw parents fetched, 0 usable after filter "
                      f"(pkg_id={state.get('pkg_id')}, country_id={state.get('country_id')}, "
                      f"city_id={state.get('city_id')}, service_provider_city_id={state.get('service_provider_city_id')})")
        _rp_edit(call, "❌ এই মুহূর্তে কোনো proxy available নেই।" if lang == "bn" else "❌ No proxy available right now.", markup_back)
        return
    state["_parents"] = parents  # আইডি → dict lookup এর জন্য cache
    markup = types.InlineKeyboardMarkup(row_width=1)
    for p in parents:
        markup.add(InlineBtn(_rp_parent_label(p), callback_data=f"rp_parent_{p.get('id')}"))
    markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_provider"))
    title = "একটা Proxy বেছে নিন 👇" if lang == "bn" else "Choose a proxy 👇"
    _rp_edit(call, title, markup)

def _rp_render_migrate_confirm(call, db, lang, state):
    """🔄 My Proxy → Change Location ফ্লো এর শেষ ধাপ — নতুন parent proxy তে migrate করার আগে কনফার্ম চায়।"""
    parent = state.get("_parent") or {}
    pid = state.get("migrate_id")
    if lang == "bn":
        title = (
            f"🔄 <b>লোকেশন চেঞ্জ — কনফার্ম করুন</b>\n\n"
            f"🆔 Proxy ID: <code>{pid}</code>\n"
            f"🆕 নতুন Proxy: <b>{_rp_parent_label(parent)}</b>\n\n"
            f"⚠️ কনফার্ম করলে সাথে সাথে নতুন লোকেশনের আইপি জেনারেট হবে, পুরনো আইপি আর কাজ করবে না। মেয়াদ (expiry) অপরিবর্তিত থাকবে।\n\n"
            f"কনফার্ম করবেন?"
        )
    else:
        title = (
            f"🔄 <b>Location Change — Confirm</b>\n\n"
            f"🆔 Proxy ID: <code>{pid}</code>\n"
            f"🆕 New proxy: <b>{_rp_parent_label(parent)}</b>\n\n"
            f"⚠️ Confirming will instantly generate a new IP for this location — the old IP stops working. Expiry stays the same.\n\n"
            f"Confirm?"
        )
    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineBtn("✅ Confirm", callback_data="rpm_confirm"),
        InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_parent"),
    )
    markup.add(InlineBtn("❌ Cancel" if lang != "bn" else "❌ ক্যানসেল", style="danger", callback_data=f"rpm_view_{pid}"))
    _rp_edit(call, title, markup)

def _rp_duration_prompt_view(db, lang, state):
    """Duration prompt এর title+markup বানায় (prices না পাওয়া গেলে None রিটার্ন করে)।
    callback-edit (_rp_render_durations) এবং plain-send (_rp_send_duration_choice) — দুই জায়গা থেকেই রিইউজ হয়।"""
    prices = realproxy_get_prices(state.get("pkg_id"))
    if not prices:
        return None, None
    # 🆕 Golden/Silver/Turbo হলে admin-সেট price দিয়ে override করা হয় — এটাই এখন
    # আসল charge (নিচে duration বাটনে যা দেখানো হয়, purchase-এও ঠিক সেই দামই কাটবে)
    prices = _rp_apply_price_overrides(state.get("_static_key"), prices)
    rate = get_proxy_usd_bdt_rate(db)
    state["_prices"] = prices  # duration lookup এর জন্য temp cache
    markup = types.InlineKeyboardMarkup(row_width=1)
    for idx, pr in enumerate(prices):
        days = pr.get("days", 0)
        hours = pr.get("hours", 0)
        usd = float(pr.get("price", 0))
        bdt = round(usd * rate, 2)
        label = f"{days}d" if days else f"{hours}h"
        markup.add(InlineBtn(f"⏱️ {label} — ৳{bdt} (${usd})",
                              callback_data=f"rp_dur_{idx}"))
    # ⛓️ অর্ডার (official Real Proxy supplier bot এর সাথে মিলিয়ে): parent proxy →
    # Username → Password → Duration → Protocol → Confirm — তাই Duration এর Back
    # এখন Password ধাপে ফিরে যায়।
    markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_password"))
    title = "একটা Duration বেছে নিন 👇" if lang == "bn" else "Choose a duration 👇"
    return title, markup

def _rp_render_durations(call, db, lang, state):
    title, markup = _rp_duration_prompt_view(db, lang, state)
    if title is None:
        _rp_edit(call, "❌ Price লোড করা যায়নি।" if lang == "bn" else "❌ Could not load prices.", None)
        return
    _rp_edit(call, title, markup)

def _rp_send_duration_choice(user_id, db, lang, state):
    """Password টেক্সট গ্রহণ করার সাথে সাথে — Duration বেছে নেওয়ার বাটন সহ নতুন মেসেজ পাঠায়
    (এই ধাপে কোনো callback/call object থাকে না, তাই edit না করে নতুন মেসেজ)।"""
    title, markup = _rp_duration_prompt_view(db, lang, state)
    if title is None:
        bot.send_message(user_id, "❌ Price লোড করা যায়নি।" if lang == "bn" else "❌ Could not load prices.")
        return
    bot.send_message(user_id, title, parse_mode="HTML", reply_markup=markup)

def _rp_compute_price(db, state):
    """_dur_idx থেকে duration/usd/bdt বের করে state এ বসিয়ে দেয়। সফল হলে True।"""
    prices = state.get("_prices") or []
    idx = state.get("_dur_idx")
    if idx is None or idx >= len(prices):
        return False
    pr = prices[idx]
    days = float(pr.get("days", 0) or 0)
    hours = float(pr.get("hours", 0) or 0)
    duration = days if days >= 1 else round(hours / 100.0, 2)
    usd = float(pr.get("price", 0))
    rate = get_proxy_usd_bdt_rate(db)
    bdt = round(usd * rate, 2)
    state["duration"] = duration
    state["usd_price"] = usd
    state["bdt_price"] = bdt
    state["_dur_label"] = f"{int(days)} day(s)" if days >= 1 else f"{hours} hour(s)"
    # 🆕 আসল মেয়াদ (real-world seconds) — purchase timestamp থেকে সঠিক
    # day/hour/minute countdown হিসাব করার জন্য (expire_at API text এর
    # ওপর নির্ভর না করে, ক্রয়ের মুহূর্ত থেকে লোকালি হিসাব করা হয়)
    state["_dur_seconds"] = int(days * 86400 + hours * 3600)
    return True

# ── Credentials ধাপ: Duration বেছে নেওয়ার পর — এখন Username ও Password আলাদা আলাদা
# ধাপে (এক মেসেজে না) নেওয়া হয়, তারপর Protocol (HTTP/SOCKS ইনলাইন বাটন), তারপর Confirm ──

def _rp_credential_back_markup(lang):
    """✅ Username/Password ধাপের Back বাটন — আগে ইনলাইন বাটন ছিল, এখন persistent
    keyboard (reply) বাটন। কাজ ঠিক আগের মতোই (একধাপ পিছনে যাবে), শুধু UI বদলেছে।"""
    markup = types.ReplyKeyboardMarkup(resize_keyboard=True)
    markup.add(KbBtn(_rp_back_label(lang), role="back"))
    return markup

def _rp_username_prompt_view(lang):
    msg = "👤 <b>Set your username:</b>" if lang != "bn" else "👤 <b>আপনার Username দিন:</b>"
    return msg

def _rp_render_ask_username(call, db, lang, state):
    """Parent proxy বেছে নেওয়ার পর (বা Password ধাপ থেকে Back করলে) — Username চাওয়া হয়।
    Duration এখনো বেছে নেওয়া হয়নি এই ধাপে, তাই এখানে price compute করা হয় না।
    ✅ Back বাটন এখন ইনলাইনের বদলে keyboard বাটন — edit করা মেসেজে reply-keyboard
    যোগ করা যায় না বলে, মূল মেসেজ (কোনো ইনলাইন বাটন ছাড়া) edit করার পর ছোট্ট একটা
    আলাদা মেসেজে persistent keyboard Back বাটন পাঠানো হচ্ছে (deposit flow এর একই প্যাটার্ন)।"""
    state["awaiting_username_text"] = True
    state["awaiting_password_text"] = False
    state["cred_chat_id"] = call.message.chat.id
    state.pop("username", None)
    state.pop("password", None)
    msg = _rp_username_prompt_view(lang)
    _rp_edit(call, msg, types.InlineKeyboardMarkup())
    try:
        bot.send_message(call.message.chat.id, "👇", reply_markup=_rp_credential_back_markup(lang))
    except Exception as e:
        logging.error(f"_rp_render_ask_username: back-keyboard send failed: {e}")

def _rp_password_prompt_view(lang, username):
    msg = (f"👤 Username: <code>{username}</code>\n\n🔑 <b>Set your password:</b>" if lang != "bn"
           else f"👤 Username: <code>{username}</code>\n\n🔑 <b>আপনার Password দিন:</b>")
    return msg

def _rp_render_ask_password_edit(call, lang, state):
    """Protocol ধাপ থেকে Back করলে — Password আবার চাওয়া হয় (Username আগের থেকেই মনে থাকে)।
    ✅ Back বাটন এখানেও keyboard বাটন (username ধাপের মতোই)।"""
    state["awaiting_password_text"] = True
    state["awaiting_username_text"] = False
    username = state.get("username", "")
    msg = _rp_password_prompt_view(lang, username)
    _rp_edit(call, msg, types.InlineKeyboardMarkup())
    try:
        bot.send_message(call.message.chat.id, "👇", reply_markup=_rp_credential_back_markup(lang))
    except Exception as e:
        logging.error(f"_rp_render_ask_password_edit: back-keyboard send failed: {e}")



def _rp_protocol_prompt_view(lang, state):
    parent = state.get("_parent") or {}
    http_port = parent.get("http_port", "?")
    socks_port = parent.get("socks_port", "?")
    if lang == "bn":
        title = f"🔌 <b>কানেকশন টাইপ বেছে নিন</b>\n\nHTTP পোর্ট: <code>{http_port}</code>\nSOCKS পোর্ট: <code>{socks_port}</code>"
    else:
        title = f"🔌 <b>Choose connection type</b>\n\nHTTP port: <code>{http_port}</code>\nSOCKS port: <code>{socks_port}</code>"
    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineBtn("🌐 HTTP", callback_data="rp_proto_http"),
        InlineBtn("🧦 SOCKS", callback_data="rp_proto_socks"),
    )
    # ⛓️ Protocol এখন Duration এর পরের ধাপ (official supplier bot এর ফ্লো: Username →
    # Password → Duration → Protocol) — তাই Back এখন Duration ধাপে ফিরে যায়।
    markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_duration"))
    return title, markup

def _rp_render_protocol(call, db, lang, state):
    """Duration বেছে নেওয়ার পর Protocol বেছে নেওয়ার ধাপ — এটা "Back" থেকে callback দিয়ে
    কল হলে edit হিসেবে দেখায়।"""
    title, markup = _rp_protocol_prompt_view(lang, state)
    _rp_edit(call, title, markup)

def _rp_send_protocol_choice(user_id, lang, state):
    """Password টেক্সট গ্রহণ করার সাথে সাথে — Protocol বেছে নেওয়ার বাটন সহ নতুন মেসেজ পাঠায়
    (এই ধাপে কোনো callback/call object থাকে না, তাই edit না করে নতুন মেসেজ)।"""
    title, markup = _rp_protocol_prompt_view(lang, state)
    bot.send_message(user_id, title, parse_mode="HTML", reply_markup=markup)

def _rp_build_confirm_view(db, lang, state):
    """Confirm স্ক্রিনের টেক্সট ও মার্কআপ তৈরি করে — callback ও text message দুই জায়গা থেকেই রিইউজ হয়।"""
    user_id = str(state.get("_user_id"))
    balance = float(db.get("users", {}).get(user_id, {}).get("balance", 0))
    bdt = state.get("bdt_price")
    usd = state.get("usd_price")
    label = state.get("_dur_label", "")
    username = state.get("username")
    password = state.get("password")
    parent = state.get("_parent") or {}
    protocol = (state.get("protocol") or "http").upper()
    port = parent.get("http_port") if protocol == "HTTP" else parent.get("socks_port")
    proxy_line = f"🔌 Type: <b>{protocol}</b> (port {port})\n" if port is not None else f"🔌 Type: <b>{protocol}</b>\n"
    if username and password:
        cred_line = f"👤 Username: <code>{username}</code>\n🔑 Password: <code>{password}</code>\n"
    else:
        cred_line = ("👤 Username/Password: <b>অটো জেনারেট হবে</b>\n" if lang == "bn"
                     else "👤 Username/Password: <b>Auto-generated</b>\n")
    if lang == "bn":
        summary = (
            f"🌐 <b>Real Proxy — Confirm Order</b>\n\n"
            f"⏱️ Duration: <b>{label}</b>\n"
            f"{proxy_line}"
            f"{cred_line}"
            f"💰 Price: <b>৳{bdt} BDT</b> (${usd})\n"
            f"💳 আপনার ব্যালেন্স: <b>৳{balance} BDT</b>\n\n"
            f"কনফার্ম করবেন?"
        )
    else:
        summary = (
            f"🌐 <b>Real Proxy — Confirm Order</b>\n\n"
            f"⏱️ Duration: <b>{label}</b>\n"
            f"{proxy_line}"
            f"{cred_line}"
            f"💰 Price: <b>৳{bdt} BDT</b> (${usd})\n"
            f"💳 Your balance: <b>৳{balance} BDT</b>\n\n"
            f"Confirm purchase?"
        )
    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineBtn("✅ Confirm", callback_data="rp_confirm"),
        InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_protocol"),
    )
    markup.add(
        InlineBtn("❌ Cancel" if lang != "bn" else "❌ ক্যানসেল", style="danger", callback_data="rp_cancel"),
    )
    return summary, markup

def _rp_render_confirm(call, db, lang, state):
    if not state.get("bdt_price") and not _rp_compute_price(db, state):
        _rp_edit(call, "⚠️ আবার শুরু করুন।" if lang == "bn" else "⚠️ Please start again.", None)
        return
    state["_user_id"] = call.from_user.id
    summary, markup = _rp_build_confirm_view(db, lang, state)
    _rp_edit(call, summary, markup)


def _handle_realproxy_callback_worker(call):
    user_id = str(call.from_user.id)
    data = call.data
    db = load_db()
    lang = get_user_lang(user_id, db)
    state = _rp_state.setdefault(user_id, {})

    try:
        # ── Cancel — পুরো ফ্লো বাতিল করে Buy Proxy মেনুতে ফিরে যাও ──
        if data == "rp_cancel":
            _rp_state.pop(user_id, None)
            try:
                bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
            except Exception:
                pass
            # 🔧 FIX: reply_markup আবার পাঠানো হচ্ছে না — এই কীবোর্ড (Buy Proxy menu) আগে থেকেই
            # নিচে দেখানো আছে, তাই বারবার একই কীবোর্ড পাঠালে Telegram এ সেটা কেঁপে/রিলোড হয়ে ওঠে।
            bot.send_message(user_id, "❌ বাতিল করা হয়েছে।" if lang == "bn" else "❌ Cancelled.")
            return

        # ── Back to Buy Proxy menu (root ছেড়ে বেরিয়ে যাওয়া) ──
        if data == "rp_back_to_root":
            _rp_state.pop(user_id, None)
            try:
                bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
            except Exception:
                pass
            # 🔧 FIX: এখানেও একই কারণে reply_markup আবার পাঠানো হচ্ছে না (কীবোর্ড স্থির থাকবে)
            bot.send_message(user_id, "🌐 Buy Proxy" if lang != "bn" else "🌐 বাই প্রক্সি")
            return

        # ── Back to Real Proxy root menu (New Proxy/My Proxy/Price/Terms) ──
        if data == "rp_back_to_realproxy_root":
            state.clear()
            _rp_render_root_menu(call, lang)
            return

        # ── Back বাটনগুলো — আগের ধাপে ফিরে যাও ──
        if data == "rp_back_to_pkg":
            _rp_render_packages(call, db, lang, state); return
        if data == "rp_back_to_country":
            _rp_render_countries(call, db, lang, state); return
        if data == "rp_back_to_city":
            _rp_render_cities(call, db, lang, state); return
        if data == "rp_back_to_provider":
            _rp_render_providers(call, db, lang, state); return
        if data == "rp_back_to_parent":
            _rp_render_parent_proxies(call, db, lang, state); return
        if data == "rp_back_to_protocol":
            _rp_render_protocol(call, db, lang, state); return
        if data == "rp_back_to_duration":
            state.pop("awaiting_username_text", None)
            state.pop("awaiting_password_text", None)
            _rp_render_durations(call, db, lang, state); return
        if data == "rp_back_to_username":
            _rp_render_ask_username(call, db, lang, state); return
        if data == "rp_back_to_password":
            _rp_render_ask_password_edit(call, lang, state); return

        # ── Real Proxy রুট মেনুর ৪টা বাটন ──
        if data == "rp_menu_new":
            state.clear()
            state["mode"] = "new"
            _rp_render_packages(call, db, lang, state)
            return

        if data == "rp_menu_terms":
            text = REALPROXY_TERMS_BN if lang == "bn" else REALPROXY_TERMS_EN
            markup = types.InlineKeyboardMarkup(row_width=1)
            markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_realproxy_root"))
            _rp_show(call, state, text, markup)
            return

        if data == "rp_menu_price":
            packages = realproxy_get_visible_packages()
            if not packages:
                _rp_show(call, state, "❌ কোনো প্যাকেজ পাওয়া যায়নি।" if lang == "bn" else "❌ No packages found.", None)
                return
            markup = types.InlineKeyboardMarkup(row_width=1)
            for pkg in packages:
                markup.add(InlineBtn(f"📦 {pkg.get('package_name','?')}", callback_data=f"rp_price_pkg_{pkg.get('id')}"))
            markup.row(
                InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_realproxy_root"),
                InlineBtn(_rp_cancel_label(lang), style="danger", callback_data="rp_cancel"),
            )
            title = "💲 <b>Price</b>\n\nকোন প্যাকেজের প্রাইস দেখতে চান? 👇" if lang == "bn" else "💲 <b>Price</b>\n\nWhich package's price do you want to see? 👇"
            _rp_show(call, state, title, markup)
            return

        if data.startswith("rp_price_pkg_"):
            pkg_id = data.replace("rp_price_pkg_", "")

            # 🏷️ প্যাকেজের নাম বের করা — static (Golden/Silver/Turbo) price list দেখানোর জন্য
            packages = realproxy_get_visible_packages() or []
            pkg_name = ""
            for pkg in packages:
                if str(pkg.get("id")) == str(pkg_id):
                    pkg_name = pkg.get("package_name", "")
                    break

            static_key = _rp_static_price_key(pkg_name)
            if static_key:
                # ✅ হার্ডকোড করা Golden/Silver/Turbo প্যাকেজের প্রাইস লিস্ট
                lines = [f"⏱️ {label} — ${usd}" for label, usd in REALPROXY_STATIC_PRICES[static_key]]
                body = "\n".join(lines)
                display_name = pkg_name or static_key.title()
                title = f"💲 <b>{display_name} Package</b>\n\n{body}"
            else:
                # ⚙️ Fallback — Real Proxy API থেকে লাইভ প্রাইস আনো (আগের মতো)
                prices = realproxy_get_prices(pkg_id)
                if not prices:
                    _rp_edit(call, "❌ Price লোড করা যায়নি।" if lang == "bn" else "❌ Could not load prices.", None)
                    return
                rate = get_proxy_usd_bdt_rate(db)
                lines = []
                for pr in prices:
                    days = pr.get("days", 0); hours = pr.get("hours", 0)
                    usd = float(pr.get("price", 0)); bdt = round(usd * rate, 2)
                    label = (f"{int(days)} day(s)" if days else f"{hours} hour(s)")
                    lines.append(f"⏱️ {label} — ৳{bdt} (${usd})")
                body = "\n".join(lines)
                title = f"💲 <b>Price</b>\n\n{body}"

            markup = types.InlineKeyboardMarkup(row_width=2)
            markup.row(
                InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_menu_price"),
                InlineBtn(_rp_cancel_label(lang), style="danger", callback_data="rp_cancel"),
            )
            _rp_edit(call, title, markup)
            return

        if data == "rp_menu_my":
            my_orders = _rp_get_user_proxy_orders(db, user_id)
            if not my_orders:
                markup = types.InlineKeyboardMarkup(row_width=1)
                markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_realproxy_root"))
                _rp_show(call, state, "📂 আপনার কোনো Real Proxy নেই।" if lang == "bn" else "📂 You don't have any Real Proxy yet.", markup)
                return
            markup = types.InlineKeyboardMarkup(row_width=1)
            proxy_count = 0
            skipped = []
            for o in my_orders:
                try:
                    pid = o.get("proxy_account_id")
                    label = _rp_order_list_label(o)
                    markup.add(InlineBtn(f"🌐 {label}", callback_data=f"rpm_view_{pid}"))
                    proxy_count += 1
                except Exception as _e:
                    logging.error(f"rp_menu_my: skipping bad order entry: {_e}")
                    skipped.append((o.get("order_id"), str(_e)))
                    continue
            # 🆕 সব order যদি skip হয়ে যায় (my_orders খালি না, কিন্তু একটাও বাটন বানানো যায়নি) —
            # আগে এই কেসে চুপচাপ খালি লিস্ট দেখাত (ইউজার ভাবত bug, কিন্তু কোনো error message পেত না)।
            # এখন স্পষ্ট error দেখানো হয় এবং এডমিনকে জানানো হয় কোন order গুলোতে সমস্যা হয়েছে।
            if proxy_count == 0:
                try:
                    bot.send_message(
                        ADMIN_ID,
                        f"⚠️ <b>My Proxy: all order entries failed to render</b>\n"
                        f"👤 User: <code>{user_id}</code>\n"
                        f"📦 Total orders: {len(my_orders)}\n"
                        f"❌ Skipped: <code>{skipped}</code>",
                        parse_mode="HTML",
                    )
                except Exception as _admin_err:
                    logging.error(f"rp_menu_my: failed to notify admin: {_admin_err}")
                markup = types.InlineKeyboardMarkup(row_width=1)
                markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_realproxy_root"))
                _rp_show(call, state, "❌ প্রক্সি লিস্ট লোড করতে সমস্যা হয়েছে। এডমিনকে জানানো হয়েছে।" if lang == "bn"
                          else "❌ Couldn't load your proxy list. Admin has been notified.", markup)
                return
            markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data="rp_back_to_realproxy_root"))
            title = (f"📂 <b>আপনার প্রক্সি লিস্ট [{proxy_count}]</b>\n\nদেখতে একটা বেছে নিন 👇" if lang == "bn"
                     else f"📂 <b>Your proxies list [{proxy_count}]</b>\n\nChoose one to view 👇")
            _rp_show(call, state, title, markup)
            return

        if data.startswith("rpm_view_"):
            pid = data.replace("rpm_view_", "")
            _rp_render_action_menu(call, db, lang, user_id, pid)
            return

        if data.startswith("rpm_details_"):
            pid = data.replace("rpm_details_", "")
            details = realproxy_get_proxy_details(pid)
            if not details:
                _rp_edit(call, "❌ প্রক্সির তথ্য পাওয়া যায়নি।" if lang == "bn" else "❌ Could not fetch proxy details.", None)
                return
            _order_for_pid = _rp_get_order_by_pid(db, user_id, pid)
            title = _rp_details_text(details, expires_at_ts=(_order_for_pid or {}).get("expires_at_ts"), lang=lang)
            markup = types.InlineKeyboardMarkup(row_width=1)
            markup.add(InlineBtn(_rp_back_label(lang), style="primary", callback_data=f"rpm_view_{pid}"))
            _rp_edit(call, title, markup)
            return

        if data.startswith("rpm_renew_"):
            rest = data.replace("rpm_renew_", "")
            code, _, pid = rest.partition("_")
            duration = _RP_RENEW_DURATION_BY_CODE.get(code)
            if not pid or duration is None:
                return
            ok, resp_data, err = realproxy_renew_proxy(pid, duration)
            if not ok:
                friendly_err = _realproxy_friendly_error(err)
                bot.answer_callback_query(call.id, (f"❌ রিনিউ ব্যর্থ: {friendly_err}" if lang == "bn" else f"❌ Renew failed: {friendly_err}"), show_alert=True)
                return
            label = _RP_RENEW_LABEL_BY_CODE.get(code, code)
            # 🆕 (Point 1 fix) — renew সফল হলে order এ সেভ করা expires_at_ts
            # renew এর পরিমাণ অনুযায়ী বাড়িয়ে দাও, যাতে My Proxy তে সঠিক
            # নতুন countdown দেখা যায়। মেয়াদ শেষ হয়ে যাওয়া প্রক্সির ক্ষেত্রে
            # renew করার মুহূর্ত থেকে গোনা হয়, না হয় আগের expiry থেকে যোগ হয়।
            add_seconds = _RP_RENEW_SECONDS_BY_CODE.get(code, 0)
            if add_seconds:
                fresh_db = load_db()
                order = _rp_get_order_by_pid(fresh_db, user_id, pid)
                if order is not None:
                    now_ts = _time_module.time()
                    base_ts = order.get("expires_at_ts") or now_ts
                    if base_ts < now_ts:
                        base_ts = now_ts
                    order["expires_at_ts"] = base_ts + add_seconds
                    update_db_path(f"/users/{user_id}/orders", fresh_db["users"][user_id]["orders"])
                    db = fresh_db
            bot.answer_callback_query(call.id, (f"✅ {label} এর জন্য রিনিউ হয়েছে।" if lang == "bn" else f"✅ Renewed for {label}."), show_alert=True)
            _rp_render_action_menu(call, db, lang, user_id, pid)
            return

        if data.startswith("rpm_switch_"):
            pid = data.replace("rpm_switch_", "")
            order = next((o for o in _rp_get_user_proxy_orders(db, user_id) if str(o.get("proxy_account_id")) == str(pid)), None)
            pkg_id = order.get("pkg_id") if order else None
            details = realproxy_get_proxy_details(pid)
            if not details:
                _rp_edit(call, "❌ প্রক্সির তথ্য পাওয়া যায়নি।" if lang == "bn" else "❌ Could not fetch proxy details.", None)
                return
            current_protocol = str(details.get("type") or "http").lower()
            new_protocol = "socks" if current_protocol == "http" else "http"
            parent_id = _rp_find_current_parent_id(db, user_id, pid, pkg_id, details)
            if not parent_id:
                _rp_edit(call, ("⚠️ বর্তমান লোকেশন খুঁজে পাওয়া যায়নি, তাই কানেকশন টাইপ পাল্টানো যাচ্ছে না। Admin কে জানান।" if lang == "bn"
                                else "⚠️ Could not determine this proxy's current location, so switching connection type isn't available. Please contact admin."), None)
                return
            ok, resp_data, err = realproxy_modify_proxy(pid, parent_id, new_protocol)
            if not ok:
                friendly_err = _realproxy_friendly_error(err)
                bot.answer_callback_query(call.id, (f"❌ ব্যর্থ: {friendly_err}" if lang == "bn" else f"❌ Failed: {friendly_err}"), show_alert=True)
                return
            bot.answer_callback_query(call.id, (f"✅ কানেকশন টাইপ এখন {new_protocol.upper()}।" if lang == "bn" else f"✅ Connection type is now {new_protocol.upper()}."), show_alert=True)
            if order is not None:
                order["cached_type"] = new_protocol.upper()
                update_db_path(f"/users/{user_id}/orders", db["users"][user_id]["orders"])
            _rp_render_action_menu(call, db, lang, user_id, pid)
            return

        if data.startswith("rpm_random_"):
            pid = data.replace("rpm_random_", "")
            order = next((o for o in _rp_get_user_proxy_orders(db, user_id) if str(o.get("proxy_account_id")) == str(pid)), None)
            pkg_id = order.get("pkg_id") if order else None
            details = realproxy_get_proxy_details(pid)
            if not pkg_id or not details:
                _rp_edit(call, "❌ প্রক্সির প্যাকেজ তথ্য পাওয়া যায়নি।" if lang == "bn" else "❌ Could not determine this proxy's package.", None)
                return
            parents = realproxy_get_parent_proxies(pkg_id)
            usable = [p for p in parents if _rp_is_parent_usable(p) and str(p.get("id")) != str(_rp_find_current_parent_id(db, user_id, pid, pkg_id, details) or "")]
            if not usable:
                usable = [p for p in parents if _rp_is_parent_usable(p)]
            if not usable:
                _rp_edit(call, "❌ এই মুহূর্তে কোনো লোকেশন available নেই।" if lang == "bn" else "❌ No location is available right now.", None)
                return
            new_parent = random.choice(usable)
            current_protocol = str(details.get("type") or "http").lower()
            ok, resp_data, err = realproxy_modify_proxy(pid, new_parent.get("id"), current_protocol)
            if not ok:
                friendly_err = _realproxy_friendly_error(err)
                bot.answer_callback_query(call.id, (f"❌ ব্যর্থ: {friendly_err}" if lang == "bn" else f"❌ Failed: {friendly_err}"), show_alert=True)
                return
            # 🆕 order এ নতুন parent_proxy_id + cached ip/port সেভ করো — যাতে পরের বার Switch Conn Type/
            # Random Location নির্ভুলভাবে কাজ করে, আর My Proxy লিস্টের লেবেলও আপডেটেড থাকে
            if order is not None:
                order["parent_proxy_id"] = new_parent.get("id")
                d = resp_data if isinstance(resp_data, dict) else {}
                if d.get("ip_addr"):   order["cached_ip_addr"] = d.get("ip_addr")
                if d.get("port"):      order["cached_port"] = d.get("port")
                if d.get("username") is not None: order["cached_username"] = d.get("username")
                update_db_path(f"/users/{user_id}/orders", db["users"][user_id]["orders"])
            bot.answer_callback_query(call.id, ("✅ নতুন র‍্যান্ডম লোকেশনে মাইগ্রেট হয়েছে!" if lang == "bn" else "✅ Migrated to a new random location!"), show_alert=True)
            _rp_render_action_menu(call, db, lang, user_id, pid)
            return

        if data.startswith("rpm_change_"):
            pid = data.replace("rpm_change_", "")
            order = next((o for o in _rp_get_user_proxy_orders(db, user_id) if str(o.get("proxy_account_id")) == str(pid)), None)
            if not order or not order.get("pkg_id"):
                _rp_edit(call, ("⚠️ এই প্রক্সির প্যাকেজ তথ্য পাওয়া যায়নি, তাই লোকেশন চেঞ্জ করা যাচ্ছে না। Admin কে জানান।" if lang == "bn"
                                else "⚠️ Could not determine this proxy's package, so location change isn't available. Please contact admin."), None)
                return
            state.clear()
            state["mode"] = "migrate"
            state["migrate_id"] = pid
            state["pkg_id"] = order.get("pkg_id")
            _rp_render_countries(call, db, lang, state)
            return

        # ── Forward ধাপগুলো ──
        if data.startswith("rp_pkg_"):
            state["pkg_id"] = data.replace("rp_pkg_", "")
            # 🆕 প্যাকেজের নাম থেকে static_key (golden/silver/turbo) বের করে state এ রাখা —
            # যাতে Duration ধাপে admin-সেট price override করা যায় (শুধু display না, actual charge ও)
            _pkgs = realproxy_get_visible_packages() or []
            _pkg_name = next((p.get("package_name", "") for p in _pkgs if str(p.get("id")) == str(state["pkg_id"])), "")
            state["_static_key"] = _rp_static_price_key(_pkg_name)
            _rp_render_countries(call, db, lang, state)

        elif data.startswith("rp_country_"):
            state["country_id"] = data.replace("rp_country_", "")
            _rp_render_cities(call, db, lang, state)

        elif data.startswith("rp_city_"):
            state["city_id"] = data.replace("rp_city_", "")
            _rp_render_providers(call, db, lang, state)

        elif data.startswith("rp_provider_"):
            state["service_provider_city_id"] = data.replace("rp_provider_", "")
            _rp_render_parent_proxies(call, db, lang, state)

        elif data.startswith("rp_parent_"):
            parent_id = data.replace("rp_parent_", "")
            state["parent_proxy_id"] = parent_id
            parent = next((p for p in state.get("_parents", []) if str(p.get("id")) == str(parent_id)), None)
            state["_parent"] = parent or {}
            if state.get("mode") == "migrate":
                # 🔄 লোকেশন চেঞ্জ ফ্লো — protocol/duration/credentials লাগবে না, সরাসরি কনফার্ম
                _rp_render_migrate_confirm(call, db, lang, state)
            else:
                # ⛓️ অর্ডার (official Real Proxy supplier bot এর সাথে মিলিয়ে):
                # parent proxy → Username → Password → Duration → Protocol → Confirm
                _rp_render_ask_username(call, db, lang, state)

        elif data in ("rp_proto_http", "rp_proto_socks"):
            state["protocol"] = "http" if data == "rp_proto_http" else "socks"
            _rp_render_confirm(call, db, lang, state)

        elif data.startswith("rp_dur_"):
            state["_dur_idx"] = int(data.replace("rp_dur_", ""))
            state["_user_id"] = call.from_user.id
            if not _rp_compute_price(db, state):
                _rp_edit(call, "⚠️ আবার শুরু করুন।" if lang == "bn" else "⚠️ Please start again.", None)
            else:
                _rp_render_protocol(call, db, lang, state)

        elif data == "rp_confirm":
            # ⚡ ডাবল-ক্লিক/রেস-কন্ডিশন গার্ড — একই ইউজারের জন্য একসাথে একটাই purchase চলবে
            with _rp_confirm_lock:
                if user_id in _rp_confirming:
                    return  # আগের ক্লিকটা এখনো প্রসেস হচ্ছে — এই ক্লিকটা উপেক্ষা করো
                _rp_confirming.add(user_id)
            try:
                finalize_realproxy_purchase(call, db, state, lang)
            finally:
                with _rp_confirm_lock:
                    _rp_confirming.discard(user_id)

        elif data == "rpm_confirm":
            # ⚡ একই গার্ড — লোকেশন চেঞ্জেও ডাবল-ক্লিক ঠেকাতে
            with _rp_confirm_lock:
                if user_id in _rp_confirming:
                    return
                _rp_confirming.add(user_id)
            try:
                finalize_realproxy_migration(call, db, state, lang)
            finally:
                with _rp_confirm_lock:
                    _rp_confirming.discard(user_id)

    except Exception as e:
        tb = traceback.format_exc()
        logging.error(f"realproxy callback error: {e}\n{tb}")
        bot.send_message(user_id, "⚠️ কিছু একটা ভুল হয়েছে, আবার চেষ্টা করুন।" if lang == "bn" else "⚠️ Something went wrong, please try again.")
        # 🆕 এডমিনকে আসল error + কোন বাটনে হয়েছে সেটা জানানো — যাতে server log না ঘেঁটেও
        # সমস্যাটা সাথে সাথে ধরা যায় (ইউজার শুধু generic error দেখে, কিন্তু এডমিন exact কারণ পায়)।
        try:
            tb_snip = tb[-1200:]  # শেষের অংশটাই সবচেয়ে গুরুত্বপূর্ণ (আসল raise যেখানে হয়েছে)
            bot.send_message(
                ADMIN_ID,
                f"⚠️ <b>Real Proxy callback error</b>\n"
                f"👤 User: <code>{user_id}</code>\n"
                f"🔘 Button: <code>{data}</code>\n"
                f"❌ Error: <code>{e}</code>\n\n"
                f"<pre>{tb_snip}</pre>",
                parse_mode="HTML",
            )
        except Exception as _admin_err:
            logging.error(f"realproxy callback error: failed to notify admin: {_admin_err}")


# ══════════════════════════════════════════════════════
# 📧 EDU MAIL — Categories inline menu callback (0-1day / 2-7days / 8-13days / 14-90days)
# ══════════════════════════════════════════════════════
def _edu_mail_edit(call, text, markup):
    """মেসেজ edit করে, না পারলে নতুন মেসেজ পাঠায়।"""
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id,
                               parse_mode="HTML", reply_markup=markup)
    except Exception:
        try:
            bot.send_message(call.message.chat.id, text, parse_mode="HTML", reply_markup=markup)
        except Exception as e:
            logging.error(f"_edu_mail_edit fallback send failed: {e}")

@bot.callback_query_handler(func=lambda call: call.data.startswith("edumail_"))
def handle_edu_mail_category_callbacks(call):
    # ⚡ FIX: item বাটনে ক্লিক করলে (edumail_XX_item_N) ack এখানে instant না দিয়ে
    # deferred রাখা হচ্ছে — কারণ stock না থাকলে worker থ্রেডে "⚠️ স্টক আউট!"
    # popup (show_alert=True) দেখাতে হবে, আর Telegram একটা callback_query
    # মাত্র একবারই answer করতে দেয় (product1_item_/product2_item_ এর মতোই প্যাটার্ন)।
    _needs_deferred_ack = "_item_" in call.data
    if not _needs_deferred_ack:
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
    _EXECUTOR.submit(_edu_mail_category_worker, call)

def _edu_mail_category_worker(call):
    user_id = str(call.message.chat.id)
    data = call.data
    db = load_db()
    lang = get_user_lang(user_id, db)

    try:
        # ── Cancel — মেনু বন্ধ করে shop menu তে ফিরে যাও ──
        if data == "edumail_cancel":
            try:
                bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
            except Exception:
                pass
            # 🔧 FIX: show_shop_menu() আবার কল করা হচ্ছে না — bottom keyboard (Shop menu)
            # এই পুরো ফ্লো জুড়ে আগে থেকেই দেখানো ছিল (edu mail categories ইনলাইন কীবোর্ড
            # ব্যবহার করে), তাই আবার একই কীবোর্ড পাঠালে Telegram এ সেটা কেঁপে/রিলোড হয়ে ওঠে।
            bot.send_message(user_id, "❌ বাতিল করা হয়েছে।" if lang == "bn" else "❌ Cancelled.")
            return

        # ── Terms & Conditions ──
        if data == "edumail_terms":
            text = EDU_MAIL_TERMS_BN if lang == "bn" else EDU_MAIL_TERMS_EN
            markup = types.InlineKeyboardMarkup(row_width=1)
            markup.add(InlineBtn("🔙 Back" if lang != "bn" else "🔙 ব্যাক", callback_data="edumail_back_categories"))
            _edu_mail_edit(call, text, markup)
            return

        # ── Back → Categories মেনুতে ফিরে যাও ──
        if data == "edumail_back_categories":
            text, markup = _edu_mail_categories_view(user_id)
            _edu_mail_edit(call, text, markup)
            return

        # ── Edu Mail 0-1day: ২৫টা placeholder item বাটন (পাশাপাশি), pagination সহ ──
        if data == "edumail_cat_0_1":
            text, markup = _edu_mail_0_1_page_view(1, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_01_page_"):
            page = int(data.rsplit("_", 1)[-1])
            text, markup = _edu_mail_0_1_page_view(page, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_01_item_"):
            item_no = data.rsplit("_", 1)[-1]
            _edu_mail_open_item(call, user_id, db, lang, "01", "Edu Mail 0-1day", item_no, "edumail_01_page_1")
            return

        # ── Edu Mail 2-7days: ১৬টা placeholder item বাটন (পাশাপাশি), pagination সহ ──
        if data == "edumail_cat_2_7":
            text, markup = _edu_mail_2_7_page_view(1, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_27_page_"):
            page = int(data.rsplit("_", 1)[-1])
            text, markup = _edu_mail_2_7_page_view(page, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_27_item_"):
            item_no = data.rsplit("_", 1)[-1]
            _edu_mail_open_item(call, user_id, db, lang, "27", "Edu Mail 2-7days", item_no, "edumail_27_page_1")
            return

        # ── Edu Mail 8-13days: ৬টা placeholder item বাটন (পাশাপাশি) ──
        if data == "edumail_cat_8_13":
            text, markup = _edu_mail_8_13_page_view(1, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_813_page_"):
            page = int(data.rsplit("_", 1)[-1])
            text, markup = _edu_mail_8_13_page_view(page, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_813_item_"):
            item_no = data.rsplit("_", 1)[-1]
            _edu_mail_open_item(call, user_id, db, lang, "813", "Edu Mail 8-13days", item_no, "edumail_813_page_1")
            return

        # ── Edu Mail 14-90days: ৯টা placeholder item বাটন (পাশাপাশি) ──
        if data == "edumail_cat_14_90":
            text, markup = _edu_mail_14_90_page_view(1, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_1490_page_"):
            page = int(data.rsplit("_", 1)[-1])
            text, markup = _edu_mail_14_90_page_view(page, db, user_id)
            _edu_mail_edit(call, text, markup)
            return

        if data.startswith("edumail_1490_item_"):
            item_no = data.rsplit("_", 1)[-1]
            _edu_mail_open_item(call, user_id, db, lang, "1490", "Edu Mail 14-90days", item_no, "edumail_1490_page_1")
            return

        # ── এখন EDU_MAIL_CATEGORIES এর সব ৪টা ক্যাটাগরিই আলাদাভাবে হ্যান্ডল হয়ে গেছে ──
        if data in EDU_MAIL_CATEGORIES:
            label = EDU_MAIL_CATEGORIES[data]
            text = (
                f"📧 <b>{label}</b>\n\nএই ক্যাটাগরির জন্য service শীঘ্রই যুক্ত করা হবে।"
                if lang == "bn" else
                f"📧 <b>{label}</b>\n\nService for this category will be added soon."
            )
            markup = types.InlineKeyboardMarkup(row_width=1)
            markup.add(InlineBtn("🔙 Back" if lang != "bn" else "🔙 ব্যাক", callback_data="edumail_back_categories"))
            _edu_mail_edit(call, text, markup)
            return

    except Exception as e:
        tb = traceback.format_exc()
        logging.error(f"edu mail category callback error: {e}\n{tb}")
        # 🆕 FIX: item ক্লিকের ack deferred রাখা হয় (স্টক আউট popup দেখানোর জন্য) —
        # যদি সেই ack পৌঁছানোর আগেই এখানে exception হয়, তাহলে callback answer না
        # হওয়ায় ইউজারের বাটনে loading spinner আটকে থাকতে পারে। তাই safety net
        # হিসেবে এখানে answer করে দেওয়া হচ্ছে (আগে থেকে answered থাকলে silently fail করবে, ক্ষতি নেই)।
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        bot.send_message(user_id, "⚠️ কিছু একটা ভুল হয়েছে, আবার চেষ্টা করুন।" if lang == "bn" else "⚠️ Something went wrong, please try again.")
        # 🆕 এডমিনকে আসল error + কোন বাটনে হয়েছে সেটা জানানো (realproxy handler এর মতো) —
        # যাতে server log না ঘেঁটেও কোন item/button এ সমস্যা হচ্ছে সাথে সাথে ধরা যায়।
        try:
            tb_snip = tb[-1200:]
            bot.send_message(
                ADMIN_ID,
                f"⚠️ <b>Edu Mail callback error</b>\n"
                f"👤 User: <code>{user_id}</code>\n"
                f"🔘 Button: <code>{data}</code>\n"
                f"❌ Error: <code>{e}</code>\n\n"
                f"<pre>{tb_snip}</pre>",
                parse_mode="HTML",
            )
        except Exception as _admin_err:
            logging.error(f"edu mail category callback error: failed to notify admin: {_admin_err}")


# ── Real Proxy: Username ও Password আলাদা আলাদা টেক্সট মেসেজ হিসেবে নেওয়া হয় ──
_RP_CRED_RE = re.compile(r"^[A-Za-z0-9_]{3,20}$")
_RP_CRED_LIKE_RE = re.compile(r"^[A-Za-z0-9_]+$")

def _rp_is_plausible_credential_text(text):
    """ইউজার সত্যিই username/password টাইপ করেছে কিনা যাচাই করে (letter/digit/underscore ছাড়া
    কিছু না থাকলে সেটাই ধরে নেওয়া হয়)। এটা False মানে ইউজার আসলে মেনুর অন্য কোনো বাটনে ক্লিক
    করেছে (স্পেস/ইমোজি/বাংলা টেক্সট আসে) — তখন username/password চাওয়ার বদলে সেই বাটনের কাজটাই
    করা উচিত, পুরনো awaiting সেশন আটকে রাখা উচিত না।"""
    text = (text or "").strip()
    return bool(text) and bool(_RP_CRED_LIKE_RE.match(text))

def _rp_is_awaiting_username(message):
    st = _rp_state.get(str(message.chat.id))
    return bool(st and st.get("awaiting_username_text"))

def _rp_is_awaiting_password(message):
    st = _rp_state.get(str(message.chat.id))
    return bool(st and st.get("awaiting_password_text"))

@bot.message_handler(func=_rp_is_awaiting_username)
def handle_realproxy_username_text(message):
    _EXECUTOR.submit(_handle_realproxy_username_text_worker, message)

@bot.message_handler(func=_rp_is_awaiting_password)
def handle_realproxy_password_text(message):
    _EXECUTOR.submit(_handle_realproxy_password_text_worker, message)

def _handle_realproxy_username_text_worker(message):
    user_id = str(message.chat.id)
    db = load_db()
    lang = get_user_lang(user_id, db)
    state = _rp_state.get(user_id)
    if not state or not state.get("awaiting_username_text"):
        return

    username = (message.text or "").strip()

    # ✅ Keyboard Back বাটন — আগে যা ইনলাইন "rp_back_to_parent" বাটনে হতো (parent
    # proxy লিস্টে ফিরে যাওয়া), এখন keyboard বাটনেও ঠিক একই কাজ করে।
    if username in (_rp_back_label("en"), _rp_back_label("bn")):
        state["awaiting_username_text"] = False
        state["awaiting_password_text"] = False
        # ✅ পরের স্ক্রিন (parent proxy লিস্ট) পুরোপুরি ইনলাইন-বাটন ভিত্তিক, তাই এখানে
        # আর persistent keyboard দরকার নেই — সেটা সরিয়ে দেওয়া হচ্ছে।
        try:
            bot.send_message(user_id, "🔙", reply_markup=types.ReplyKeyboardRemove())
        except Exception:
            pass
        _rp_render_parent_proxies(_rp_fake_call(user_id), db, lang, state)
        return

    # ── এটা আসলে username না, ইউজার অন্য কোনো (মেনু) বাটনে ক্লিক করেছে —
    # তাহলে আগের awaiting সেশন বাদ দিয়ে সেই বাটনের কাজ স্বাভাবিকভাবে করতে দাও ──
    if not _rp_is_plausible_credential_text(username):
        state["awaiting_username_text"] = False
        state["awaiting_password_text"] = False
        _text_message_worker(message)
        return

    if not _RP_CRED_RE.match(username):
        err = ("❌ Username শুধু ইংরেজি লেটার, সংখ্যা, আন্ডারস্কোর (৩-২০ ক্যারেক্টার) হতে পারবে — স্পেস/বিশেষ চিহ্ন চলবে না।" if lang == "bn"
               else "❌ Username can only contain letters, numbers, underscore (3-20 chars) — no spaces/special characters.")
        bot.send_message(user_id, err, parse_mode="HTML")
        return

    # ── Purchase করার আগেই username availability চেক করে নিচ্ছি ──
    check_result = realproxy_check_username(username)
    if check_result == "ALREADY_USER":
        err = (f"❌ Username <code>{username}</code> আগে থেকেই ব্যবহার হচ্ছে। অন্য একটা দিন।" if lang == "bn"
               else f"❌ Username <code>{username}</code> is already taken. Please choose another.")
        bot.send_message(user_id, err, parse_mode="HTML")
        return
    if check_result is None:
        err = ("⚠️ Username চেক করা যায়নি, একটু পরে আবার চেষ্টা করুন।" if lang == "bn"
               else "⚠️ Couldn't verify username right now, please try again shortly.")
        bot.send_message(user_id, err, parse_mode="HTML")
        return

    state["username"] = username
    state["awaiting_username_text"] = False
    state["awaiting_password_text"] = True
    state["_user_id"] = message.from_user.id

    msg = _rp_password_prompt_view(lang, username)
    bot.send_message(user_id, msg, parse_mode="HTML", reply_markup=_rp_credential_back_markup(lang))

def _handle_realproxy_password_text_worker(message):
    user_id = str(message.chat.id)
    db = load_db()
    lang = get_user_lang(user_id, db)
    state = _rp_state.get(user_id)
    if not state or not state.get("awaiting_password_text"):
        return

    password = (message.text or "").strip()

    # ✅ Keyboard Back বাটন — আগে যা ইনলাইন "rp_back_to_username" বাটনে হতো (username
    # ধাপে ফিরে যাওয়া), এখন keyboard বাটনেও ঠিক একই কাজ করে।
    if password in (_rp_back_label("en"), _rp_back_label("bn")):
        state["awaiting_password_text"] = False
        state["awaiting_username_text"] = False
        _rp_render_ask_username(_rp_fake_call(user_id), db, lang, state)
        return

    # ── এটা আসলে password না, ইউজার অন্য কোনো (মেনু) বাটনে ক্লিক করেছে —
    # তাহলে আগের awaiting সেশন বাদ দিয়ে সেই বাটনের কাজ স্বাভাবিকভাবে করতে দাও ──
    if not _rp_is_plausible_credential_text(password):
        state["awaiting_username_text"] = False
        state["awaiting_password_text"] = False
        _text_message_worker(message)
        return

    if not _RP_CRED_RE.match(password):
        err = ("❌ Password শুধু ইংরেজি লেটার, সংখ্যা, আন্ডারস্কোর (৩-২০ ক্যারেক্টার) হতে পারবে — স্পেস/বিশেষ চিহ্ন চলবে না।" if lang == "bn"
               else "❌ Password can only contain letters, numbers, underscore (3-20 chars) — no spaces/special characters.")
        bot.send_message(user_id, err, parse_mode="HTML")
        return

    state["password"] = password
    state["awaiting_password_text"] = False
    state["_user_id"] = message.from_user.id

    _rp_send_duration_choice(user_id, db, lang, state)


def finalize_realproxy_purchase(call, db, state, lang):
    user_id = str(call.from_user.id)
    bdt_price = state.get("bdt_price")
    pkg_id = state.get("pkg_id")
    provider_city_id = state.get("service_provider_city_id")
    duration = state.get("duration")
    parent_proxy_id = state.get("parent_proxy_id")
    protocol = state.get("protocol") or "http"

    if bdt_price is None or pkg_id is None or duration is None or parent_proxy_id is None:
        bot.send_message(user_id, "⚠️ Session expired, আবার শুরু করুন।" if lang == "bn" else "⚠️ Session expired, please start again.")
        return

    # ── Confirm মেসেজের বাটন সরিয়ে দাও, যাতে ডাবল-ক্লিক না হয় ──
    try:
        bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    except Exception:
        pass

    db = load_db()  # ফ্রেশ balance আনো
    current_balance = float(db.get("users", {}).get(user_id, {}).get("balance", 0))
    if current_balance < bdt_price:
        shortage = round(bdt_price - current_balance, 2)
        bot.send_message(user_id,
            (f"❌ ব্যালেন্স অপর্যাপ্ত! প্রয়োজন ৳{bdt_price}, আপনার আছে ৳{current_balance} (৳{shortage} কম)."
             if lang == "bn" else
             f"❌ Insufficient balance! Need ৳{bdt_price}, you have ৳{current_balance} (short ৳{shortage})."),
            reply_markup=get_main_menu(user_id))
        return

    # ── ইউজার যে নির্দিষ্ট parent proxy বেছেছিল সেটা এখনো available কিনা রিফ্রেশ করে চেক করো ──
    # 🔧 BUG FIX: এখানেও আগে API error আর genuine "proxy আর নেই" — দুটো একই মেসেজে
    # মিশে যেত। এখন API সত্যিই fail করলে ইউজারকে সেটা বলা হয় ও admin কে notify
    # করা হয়, যাতে সে "session আবার শুরু করুন" লুপে আটকে না থাকে।
    parents, had_error, err = realproxy_get_parent_proxies(
        pkg_id, service_provider_city_id=provider_city_id,
        country_id=state.get("country_id"), city_id=state.get("city_id"), return_error=True
    )
    if had_error:
        friendly_err = _realproxy_friendly_error(err)
        bot.send_message(user_id, (f"⚠️ Proxy স্ট্যাটাস চেক করতে সমস্যা হয়েছে: {friendly_err}\n\nআবার চেষ্টা করুন।" if lang == "bn"
                                    else f"⚠️ Couldn't verify the proxy status: {friendly_err}\n\nPlease try again."),
                          reply_markup=get_main_menu(user_id))
        try:
            bot.send_message(ADMIN_ID, f"⚠️ Real Proxy /parent-proxies API error during purchase confirm (user {user_id}): {err}")
        except Exception:
            pass
        return
    parent = next((p for p in parents if str(p.get("id")) == str(parent_proxy_id)), None)
    if not parent or not _rp_is_parent_usable(parent):
        bot.send_message(user_id, "❌ আপনার বেছে নেওয়া proxy টা এখন আর available নেই। আবার শুরু করুন।" if lang == "bn"
                          else "❌ The proxy you selected is no longer available. Please start again.",
                          reply_markup=get_main_menu(user_id))
        return

    ok, resp_data, err = realproxy_create_proxy(
        parent.get("id"), pkg_id, protocol, duration,
        username=state.get("username"), password=state.get("password"),
    )
    if not ok:
        friendly_err = _realproxy_friendly_error(err)
        bot.send_message(user_id, f"❌ ক্রয় ব্যর্থ হয়েছে: {friendly_err}" if lang == "bn" else f"❌ Purchase failed: {friendly_err}",
                          reply_markup=get_main_menu(user_id))
        try:
            bot.send_message(ADMIN_ID, f"⚠️ Real Proxy purchase failed for {user_id}: {err}")
        except Exception:
            pass
        return

    # ── Balance কাটো (targeted write) ──
    new_balance = round(current_balance - bdt_price, 2)
    db["users"][user_id]["balance"] = new_balance
    update_db_path(f"/users/{user_id}/balance", new_balance, _async=False)

    d = resp_data if isinstance(resp_data, dict) else {}
    order_id = f"RP-{uuid.uuid4().hex[:8].upper()}"
    dur_label = state.get("_dur_label", "")
    # 🆕 (Point 1 fix) — মেয়াদ (expiry) এখন ক্রয় করার এই মুহূর্ত (timestamp)
    # থেকে গোনা শুরু হয়। provider API এর "expire_at" টেক্সটের বদলে এই
    # লোকাল timestamp থেকেই সবসময় Day/Hour/Min countdown দেখানো হবে।
    purchased_at_ts = _time_module.time()
    dur_seconds = state.get("_dur_seconds") or 0
    expires_at_ts = purchased_at_ts + dur_seconds if dur_seconds else None
    order_record = {
        "order_id": order_id, "product": "Real Proxy", "price": bdt_price,
        "date": get_now(), "type": "real_proxy",
        # 🆕 Order history (My Orders) তে duration দেখানোর জন্য
        "duration": duration,
        "duration_label": dur_label,
        # 🆕 (Point 1 fix) — ক্রয়ের মুহূর্ত ও তার থেকে গণনা করা expiry timestamp
        "purchased_at_ts": purchased_at_ts,
        "expires_at_ts": expires_at_ts,
        # 🆕 "My Proxy" ফিচারের জন্য — কোন telegram user কোন real proxy account কিনেছে সেটা মনে রাখা দরকার
        "proxy_account_id": d.get("id"),
        "pkg_id": pkg_id,
        "protocol": protocol,
        # 🆕 Switch Conn Type / Random Location ফিচারের জন্য — বর্তমান parent proxy id মনে রাখা দরকার
        "parent_proxy_id": parent.get("id"),
        # 🆕 My Proxy লিস্ট ইনস্ট্যান্ট রেন্ডার করার জন্য — এগুলো ক্যাশ করে রাখলে লিস্ট দেখাতে
        # প্রতিটা প্রক্সির জন্য আলাদা লাইভ API কল লাগে না (দ্রুত + বেশি রিলায়েবল)
        "cached_username": d.get("username") or "",
        "cached_ip_addr": d.get("ip_addr") or "",
        "cached_port": d.get("port") or "",
        "cached_type": d.get("type") or protocol.upper(),
    }
    orders = _normalize_orders_list(db["users"][user_id].get("orders", []))
    orders.append(order_record)
    db["users"][user_id]["orders"] = orders
    # 🆕 (Data-loss fix) — real money purchase order, তাই _async=False দিয়ে
    # সরাসরি synchronous MySQL write করা হচ্ছে। এটা না করলে write টা
    # ব্যাকগ্রাউন্ড থ্রেড-পুলে queue হয়ে থাকতো, আর ঠিক তখনই bot redeploy/kill
    # হলে MySQL এ কখনো পৌঁছাতো না (RAM cache এ purchase দেখা যেত কিন্তু
    # restart এর পর "My Proxy" খালি দেখাতো)। synchronous write নিশ্চিত করে
    # user কে success message দেখানোর আগেই order টা MySQL এ persist হয়ে গেছে।
    update_db_path(f"/users/{user_id}/orders", orders, _async=False)

    # ── 🆕 Purchase log — LOG_CHANNEL_ID তে পাঠানো হয় (অন্য প্রোডাক্টগুলোর মতোই ফরম্যাটে) ──
    try:
        bot.send_message(LOG_CHANNEL_ID,
            f"🛒 <b>Purchase Successful!</b>🎉\n\n"
            f"👤 <b>User ID:</b> <code>{mask_id(user_id)}</code>\n"
            f"📦 <b>Product:</b> Real Proxy\n"
            f"⏱️ <b>Duration:</b> {dur_label}\n"
            f"💰 <b>Total:</b> {bdt_price} BDT\n"
            f"🆔 <b>Order ID:</b> <code>{mask_id(order_id)}</code>\n"
            f"✅ <b>Status:</b> Delivered\n"
            f"📅 <b>Date:</b> {order_record['date']}",
            parse_mode="HTML")
    except Exception:
        pass

    _rp_state.pop(user_id, None)

    # 🆕 (Point 1 fix) — raw API expire_at টেক্সটের বদলে ক্রয়ের মুহূর্ত থেকে
    # হিসাব করা Day/Hour/Min countdown দেখানো হচ্ছে
    _expire_display = _rp_format_expiry_countdown(expires_at_ts, lang) or d.get('expire_at', '')
    proxy_lines = (
        f"🆔 ID: <code>{d.get('id','')}</code>\n"
        f"🌐 IP: <code>{d.get('ip_addr','')}</code>\n"
        f"🔌 Port: <code>{d.get('port','')}</code>\n"
        f"👤 Username: <code>{d.get('username','') or 'N/A (IP-auth)'}</code>\n"
        f"🔑 Password: <code>{d.get('password','') or 'N/A (IP-auth)'}</code>\n"
        f"📅 Expire: <code>{_expire_display}</code>"
    )
    msg = (
        f"✅ <b>Real Proxy কেনা হয়েছে!</b>\n\n"
        f"🆔 Order: <code>{order_id}</code>\n\n{proxy_lines}\n\n"
        f"💳 নতুন ব্যালেন্স: <b>৳{new_balance} BDT</b>" if lang == "bn" else
        f"✅ <b>Real Proxy purchased!</b>\n\n"
        f"🆔 Order: <code>{order_id}</code>\n\n{proxy_lines}\n\n"
        f"💳 New balance: <b>৳{new_balance} BDT</b>"
    )
    bot.send_message(user_id, msg, parse_mode="HTML", reply_markup=get_main_menu(user_id))


def _normalize_orders_list(raw):
    """Firebase Realtime Database-এ sparse (gap-ওয়ালা) array কে dict/object হিসেবে স্টোর করে,
    list হিসেবে না — কোনো order index দিয়ে ডিলিট করলে বা আংশিক আপডেট হলে এটা ঘটে। ফলে
    db তে 'orders' মাঝে মাঝে dict আকারে আসে (list না), আর তার উপর .append() করলে crash হয়
    ('dict' object has no attribute 'append')। এই ফাংশন dict বা list — দুটো ফরম্যাট থেকেই
    robust ভাবে একটা পরিষ্কার list বানায় (index অনুযায়ী sorted, non-dict entry বাদ দিয়ে)।
    যেখানেই orders read করা হয় সব জায়গায় এটা ব্যবহার করা উচিত, যাতে ভবিষ্যতে এই bug না হয়।"""
    if isinstance(raw, dict):
        try:
            items = sorted(raw.items(), key=lambda kv: int(kv[0]))
        except (ValueError, TypeError):
            items = list(raw.items())
        raw = [v for _k, v in items]
    if not isinstance(raw, list):
        return []
    return [o for o in raw if isinstance(o, dict)]


def _rp_get_user_proxy_orders(db, user_id):
    """এই ইউজারের কেনা real proxy account গুলোর order record রিটার্ন করে (My Proxy লিস্টের জন্য)।"""
    orders = _normalize_orders_list(db.get("users", {}).get(str(user_id), {}).get("orders", []))
    return [o for o in orders if o.get("type") == "real_proxy" and o.get("proxy_account_id")]


def finalize_realproxy_migration(call, db, state, lang):
    """🔄 My Proxy → Change Location কনফার্মের পর PUT /proxies/{id} কল করে নতুন parent proxy তে
    migrate করে (নতুন IP জেনারেট হয়)। এটা কোনো নতুন purchase না, তাই balance কাটা হয় না
    (Modify API এর "Affect Balance" = No, doc অনুযায়ী), আর expiry ও অপরিবর্তিত থাকে।"""
    user_id = str(call.from_user.id)
    pid = state.get("migrate_id")
    parent = state.get("_parent") or {}
    new_parent_id = parent.get("id")
    if not pid or not new_parent_id:
        bot.send_message(user_id, "⚠️ Session expired, আবার শুরু করুন।" if lang == "bn" else "⚠️ Session expired, please start again.")
        return

    # ── কনফার্ম মেসেজের বাটন সরিয়ে দাও, যাতে ডাবল-ক্লিক না হয় ──
    try:
        bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    except Exception:
        pass

    # ── প্রক্সির বর্তমান protocol জেনে নাও — সেটা পরিবর্তন করা হচ্ছে না, শুধু লোকেশন ──
    details = realproxy_get_proxy_details(pid)
    if not details:
        bot.send_message(user_id, "❌ প্রক্সির তথ্য পাওয়া যায়নি।" if lang == "bn" else "❌ Could not fetch proxy details.",
                          reply_markup=get_main_menu(user_id))
        return
    protocol = str(details.get("type") or "http").lower()

    ok, resp_data, err = realproxy_modify_proxy(pid, new_parent_id, protocol)
    if not ok:
        friendly_err = _realproxy_friendly_error(err)
        bot.send_message(user_id,
                          f"❌ লোকেশন চেঞ্জ ব্যর্থ হয়েছে: {friendly_err}" if lang == "bn" else f"❌ Location change failed: {friendly_err}",
                          reply_markup=get_main_menu(user_id))
        return

    _rp_state.pop(user_id, None)
    d = resp_data if isinstance(resp_data, dict) else {}

    # 🆕 order এ নতুন parent_proxy_id + cached ip/port/type সেভ করো — যাতে Switch Conn Type/
    # Random Location পরের বার নির্ভুলভাবে কাজ করে, আর My Proxy লিস্টের লেবেলও আপডেটেড থাকে
    fresh_db = load_db()
    order = next((o for o in _rp_get_user_proxy_orders(fresh_db, user_id) if str(o.get("proxy_account_id")) == str(pid)), None)
    if order is not None:
        order["parent_proxy_id"] = new_parent_id
        if d.get("ip_addr"):   order["cached_ip_addr"] = d.get("ip_addr")
        if d.get("port"):      order["cached_port"] = d.get("port")
        if d.get("username") is not None: order["cached_username"] = d.get("username")
        if d.get("type"):      order["cached_type"] = d.get("type")
        update_db_path(f"/users/{user_id}/orders", fresh_db["users"][user_id]["orders"])

    proxy_lines = (
        f"🆔 ID: <code>{d.get('id', pid)}</code>\n"
        f"🌐 New IP: <code>{d.get('ip_addr','')}</code>\n"
        f"🔌 Port: <code>{d.get('port','')}</code>\n"
        f"📍 Location: <code>{d.get('city_name','?')}, {d.get('country_name','?')}</code>\n"
        f"📅 Expire: <code>{(_rp_format_expiry_countdown((order or {}).get('expires_at_ts'), lang) or d.get('expire_at',''))}</code>"
    )
    msg = (
        f"✅ <b>লোকেশন চেঞ্জ হয়েছে!</b>\n\n{proxy_lines}" if lang == "bn"
        else f"✅ <b>Location changed!</b>\n\n{proxy_lines}"
    )
    bot.send_message(user_id, msg, parse_mode="HTML", reply_markup=get_main_menu(user_id))


