@bot.message_handler(func=lambda message: True)
def handle_text_messages(message):
    # ⚡ FAST: dedicated _UI_EXECUTOR ব্যবহার করো (heavy purchase/API pool থেকে আলাদা) —
    # যাতে ভারী ব্যাকগ্রাউন্ড কাজের কারণে keyboard বাটন ক্লিকের রেসপন্স কখনো আটকে না থাকে।
    _UI_EXECUTOR.submit(_text_message_worker, message)

def _text_message_worker(message):
    user_id = str(message.chat.id)
    text = message.text or ""

    # ⚡ Rate limit আগে check করো — DB load লাগে না
    if not is_admin(user_id) and is_rate_limited(user_id):
        bot.send_message(user_id,
            "⚠️ <b>একটু ধীরে!</b>\n\nপরপর অনেক message পাঠাচ্ছেন।\nকয়েক সেকেন্ড অপেক্ষা করুন। 🙏",
            parse_mode="HTML")
        return

    # ✅ Subscription gate — admin বাদে সবাইকে channel join enforce করো
    if not is_admin(user_id):
        # ⚡ stale-while-revalidate — cache থাকলে instant, expire হলে ব্যাকগ্রাউন্ডে
        # রিফ্রেশ হয়, ইউজারকে কখনো Telegram API কলের জন্য আটকে থাকতে হয় না
        _sub_ok = is_subscribed(user_id)
        if not _sub_ok:
            _lang_now = _lang_cache.get(user_id, 'en')
            _join_markup = types.InlineKeyboardMarkup(row_width=1)
            for i, ch in enumerate(CHANNELS, 1):
                _btn_text = LANG.get(_lang_now, LANG['en'])['join_channel_btn'].format(n=i)
                _join_markup.add(InlineBtn(_btn_text, style="primary", url=ch['link']))
            _join_markup.add(InlineBtn(
                LANG.get(_lang_now, LANG['en'])['verify_join'], style="success", callback_data='check_join'))
            bot.send_message(user_id,
                LANG.get(_lang_now, LANG['en'])['join_channels'],
                reply_markup=_join_markup, parse_mode='HTML')
            return

    # ⚡ Lang cache দিয়ে check — DB load না করে
    lang = _lang_cache.get(user_id, "en")
    L = LANG[lang]

    # ⚡ Ban check fast path — lang cache দিয়ে
    # সাধারণ command গুলো DB ছাড়াই handle করো
    if text == "💻 Code</>":
        handle_code_command(message); return
    if text == "/language":
        show_language_selection(user_id); return
    if text == "/stock":
        handle_stock_command(message); return
    if text == "/apitest" and is_admin(user_id):
        handle_apitest_command(message); return
    if text == "/token" or text == "/get_code":
        handle_get_code_command(message); return
    if text.startswith("/2fa_key"):
        handle_2fa_command(message); return
    if text == "/code" or text.startswith("/code "):
        handle_code_command(message); return
    if text == "/tn_verify" or text.startswith("/tn_verify "):
        handle_tn_verify_command(message); return
    if text in (L["support"], LANG["en"]["support"], LANG["bn"]["support"]):
        show_support_info(user_id); return
    if text in (L.get("twofa",""), LANG["en"].get("twofa",""), LANG["bn"].get("twofa","")):
        start_2fa_key_flow(user_id); return
    if text in (L.get("edu_reader",""), LANG["en"].get("edu_reader",""), LANG["bn"].get("edu_reader","")):
        start_edu_reader_flow(user_id); return
    if text in (L["back"], L["cancel"], LANG["en"]["back"], LANG["bn"]["back"]):
        _pending_product_cache.pop(user_id, None)
        _pending_product_origin.pop(user_id, None)
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
    if text == "🔙 Back":
        db_quick = load_db()
        # Edu Mail sub-products এর Back → Edu Mail submenu তে যাবে
        # Buy Proxy → All VPN থেকে আসা product এর Back → Buy Proxy মেনুতে যাবে
        # অন্য (Shop Now থেকে আসা) products এর Back → shop menu তে যাবে
        last_product = _pending_product_cache.get(user_id)
        last_origin = _pending_product_origin.get(user_id)
        _pending_product_cache.pop(user_id, None)
        _pending_product_origin.pop(user_id, None)
        if last_product in (EDU_MAIL_SUB_24H, EDU_MAIL_SUB_72H, EDU_MAIL_SUB_24HR):
            _show_edu_mail_submenu(user_id, db_quick)
        elif last_origin == "buy_proxy":
            handle_buy_proxy(user_id, db_quick)
        else:
            show_shop_menu(user_id, db_quick)
        return

    # ⚡ এখন DB load করো (cache hit হলে μs, miss হলে MySQL call)
    db = load_db()

    # Ban check
    if user_id in db["banned_users"]:
        bot.send_message(user_id, LANG["en"]["banned"], parse_mode="HTML")
        return

    # Lang cache sync
    if user_id in db["users"]:
        _lang_cache[user_id] = db["users"][user_id].get("lang", "en")
        lang = _lang_cache[user_id]
        L = LANG[lang]

    if text == L["shop"] or text == LANG["en"]["shop"] or text == LANG["bn"]["shop"]:
        show_shop_menu(user_id, db); return
    elif text in (L["orders"], LANG["en"]["orders"], LANG["bn"]["orders"]):
        show_user_orders(user_id, db); return
    elif text in (L["balance"], LANG["en"]["balance"], LANG["bn"]["balance"]):
        show_user_balance(user_id, db); return
    elif text in (L["refer"], LANG["en"]["refer"], LANG["bn"]["refer"]):
        show_referral_info(user_id, db); return
    elif text in (L["deposit"], LANG["en"]["deposit"], LANG["bn"]["deposit"]):
        show_deposit_menu(user_id); return
    elif text in (L.get("other",""), LANG["en"].get("other",""), LANG["bn"].get("other","")):
        show_other_menu(user_id, db); return
    elif text in (L.get("buy_proxy",""), LANG["en"].get("buy_proxy",""), LANG["bn"].get("buy_proxy","")):
        handle_buy_proxy(user_id, db); return
    elif text in {kb_label(_r) for _r in (["proxy_real", "proxy_allvpn"] + PROXY_PROVIDER_KEYS)}:
        handle_proxy_provider_selected(user_id, text, db); return
    elif text in (L.get("admin",""), LANG["en"]["admin"]) and is_admin(user_id):
        show_admin_panel(user_id); return
    # ── Edu Mail parent button → submenu দেখাও ──
    elif text == EDU_MAIL_PARENT:
        _show_edu_mail_submenu(user_id, db); return
    # ── Edu Mail sub-buttons ──
    elif text == "Edu Mail 24H":
        _pending_product_cache[user_id] = EDU_MAIL_SUB_24H
        show_product_detail_with_subnav(user_id, EDU_MAIL_SUB_24H, db); return
    elif text == "Edu Mail 72H":
        _pending_product_cache[user_id] = EDU_MAIL_SUB_72H
        show_product_detail_with_subnav(user_id, EDU_MAIL_SUB_72H, db); return
    elif text == EDU_MAIL_SUB_24HR:
        _pending_product_cache[user_id] = EDU_MAIL_SUB_24HR
        show_product_detail_with_subnav(user_id, EDU_MAIL_SUB_24HR, db); return
    # ── Hotmail ও Outlook — API products ──
    elif text == HOTMAIL_PROD:
        _pending_product_cache[user_id] = HOTMAIL_PROD
        show_product_detail_with_subnav(user_id, HOTMAIL_PROD, db); return
    elif text == OUTLOOK_PROD:
        _pending_product_cache[user_id] = OUTLOOK_PROD
        show_product_detail_with_subnav(user_id, OUTLOOK_PROD, db); return
    # ── Product1 — placeholder বাটন ──
    elif text == get_product1_btn_label(db):
        show_product1_item_select(user_id, db); return
    # ── Product2 — placeholder বাটন (ফিচার পরে যোগ হবে) ──
    elif text == get_product2_btn_label(db):
        show_product2_item_select(user_id, db); return
    # ── Product3Bulk — placeholder বাটন (ফিচার পরে যোগ হবে) ──
    elif text == get_product3bulk_btn_label(db):
        show_product3bulk_item_select(user_id, db); return
    elif text in db["products"]:
        show_product_detail_with_subnav(user_id, text, db); return
    elif text in (L["single_buy"], LANG["en"]["single_buy"], LANG["bn"].get("single_buy", "")):
        handle_single_buy_from_keyboard(user_id, db); return
    elif text in (L["bulk_buy"], LANG["en"]["bulk_buy"], LANG["bn"].get("bulk_buy", "")):
        handle_bulk_buy_from_keyboard(user_id, db); return

# ===========================
# SHOP FUNCTIONS
# ===========================

# ══════════════════════════════════════════════════════
# 🔢 SHOP BUTTON ORDER — Admin Panel Controlled
# ══════════════════════════════════════════════════════
# Buy Mail শপ মেনুর ভিতরের বাটনগুলোর (Edu Mail, সাধারণ প্রোডাক্ট, Product1,
# Product2) পজিশন/অবস্থান admin panel থেকে সেট করা যায় (🔢 Shop Button
# Order)। db["settings"]["shop_button_order"] এ item-key গুলোর ক্রম অনুযায়ী
# একটা list persist হয়। কোনো নতুন প্রোডাক্ট/বাটন যোগ হলে সেটা স্বয়ংক্রিয়ভাবে
# লিস্টের শেষে যোগ হয়ে যায় (আগের কাস্টম অর্ডার নষ্ট না করেই), আর ডিলিট হওয়া/
# hide হওয়া বাটন বাদ পড়ে যায়। show_shop_menu() ও go_to_shop/back_to_shop
# callback — দুই জায়গাতেই build_shop_reply_markup() ব্যবহার হয়, যাতে অর্ডার
# সবসময় সিঙ্ক থাকে।
PRODUCT1_ORDER_KEY = "__product1__"
PRODUCT2_ORDER_KEY = "__product2__"
PRODUCT3BULK_ORDER_KEY = "__product3bulk__"

# ── কীবোর্ড-বাটন-only hide/restore — Buy Mail মেনু থেকে শুধু বাটনটা সরায়,
#    ভিতরের স্টক/ডেটা কখনো মোছে না। 🗑️ Delete Product প্যানেল থেকেই
#    Edu Mail / Product1 / Product2 বাটন hide/restore করা যায়। ──
def get_hidden_shop_buttons(db=None):
    """যেসব Buy Mail keyboard বাটন admin hide করে রেখেছেন তাদের key-set।"""
    if db is None:
        db = load_db()
    return set(db.get("settings", {}).get("shop_hidden_buttons", []))

def hide_shop_button(item_key, db=None):
    """একটা Buy Mail বাটন (Edu Mail/Product1/Product2) hide করো — শুধু বাটন,
    ভিতরের ডেটা/স্টক অক্ষত থাকবে, পরে চাইলে unhide_shop_button দিয়ে ফেরানো যাবে।"""
    if db is None:
        db = load_db()
    hidden = db.setdefault("settings", {}).setdefault("shop_hidden_buttons", [])
    if item_key not in hidden:
        hidden.append(item_key)
    update_db_path("/settings/shop_hidden_buttons", hidden)

def unhide_shop_button(item_key, db=None):
    """hide করা Buy Mail বাটন আবার ফিরিয়ে আনে।"""
    if db is None:
        db = load_db()
    hidden = db.setdefault("settings", {}).setdefault("shop_hidden_buttons", [])
    if item_key in hidden:
        hidden.remove(item_key)
    update_db_path("/settings/shop_hidden_buttons", hidden)

def _shop_button_only_display_map(db=None):
    """Delete Product প্যানেলে Edu Mail/Product1/Product2 বাটনগুলোর জন্য
    display label — Product1/Product2 এর ক্ষেত্রে admin-সেট rename থাকলে সেটাই দেখাবে।"""
    if db is None:
        db = load_db()
    return {
        EDU_MAIL_PARENT: "📧 Edu Mail",
        PRODUCT1_ORDER_KEY: f"🅰️ {get_product1_btn_label(db)}",
        PRODUCT2_ORDER_KEY: f"🅱️ {get_product2_btn_label(db)}",
        PRODUCT3BULK_ORDER_KEY: f"🅲️ {get_product3bulk_btn_label(db)}",
    }

def _shop_default_item_keys(db=None):
    """বর্তমানে Buy Mail শপ মেনুতে যেই আইটেমগুলো দেখানো হবে, তাদের key —
    কোডে যে ডিফল্ট ক্রমে ছিল (admin-সেট কাস্টম order প্রয়োগের আগে) সেই ক্রমে।"""
    if db is None:
        db = load_db()
    _hidden_sub = {EDU_MAIL_SUB_24H, EDU_MAIL_SUB_72H, EDU_MAIL_SUB_24HR, EDU_MAIL_PARENT}
    db_product_keys = set(db["products"].keys())
    products = [p for p in db["products"].keys() if p not in _hidden_sub and not _is_edu_mail_virtual_product(p) and not _is_vpn_category_product(p) and not _is_product1_sub_product(p) and not _is_product2_sub_product(p) and not _is_product3bulk_sub_product(p) and not _is_proxy_provider_product(p)]
    _bulkmail_edu_enabled = is_bulkmail_enabled(EDU_MAIL_SUB_24HR, db)
    _h143_24h_enabled     = is_hotmail143_enabled(EDU_MAIL_SUB_24H, db) and EDU_MAIL_SUB_24H in db_product_keys
    _h143_72h_enabled     = is_hotmail143_enabled(EDU_MAIL_SUB_72H, db) and EDU_MAIL_SUB_72H in db_product_keys
    show_edu_mail_btn = _bulkmail_edu_enabled or _h143_24h_enabled or _h143_72h_enabled or EDU_MAIL_PARENT in db_product_keys
    if show_edu_mail_btn:
        products = [EDU_MAIL_PARENT] + products  # প্রথমে Edu Mail
    result = products + [PRODUCT1_ORDER_KEY, PRODUCT2_ORDER_KEY, PRODUCT3BULK_ORDER_KEY]
    hidden = get_hidden_shop_buttons(db)
    return [k for k in result if k not in hidden]

def get_shop_button_order(db=None):
    """Buy Mail শপ মেনুর বাটনগুলোর admin-সেট (persist করা) ক্রম রিটার্ন করে।
    কাস্টম order এ না থাকা নতুন আইটেম স্বয়ংক্রিয়ভাবে শেষে যোগ হয়ে যায়, আর
    ডিলিট/hide হওয়া আইটেম বাদ পড়ে যায়। কোনো কাস্টম order সেভ করা না থাকলে
    ডিফল্ট ক্রম রিটার্ন করে।"""
    if db is None:
        db = load_db()
    default_keys = _shop_default_item_keys(db)
    saved = db.get("settings", {}).get("shop_button_order")
    if not isinstance(saved, list) or not saved:
        return default_keys
    default_set = set(default_keys)
    ordered = [k for k in saved if k in default_set]
    ordered_set = set(ordered)
    ordered += [k for k in default_keys if k not in ordered_set]
    return ordered

def set_shop_button_order(order_list, db=None):
    """সম্পূর্ণ নতুন order list সেভ করে (DB persist সহ)। খালি list দিলে
    ডিফল্ট ক্রমে রিসেট হয়ে যাবে।"""
    if db is None:
        db = load_db()
    db.setdefault("settings", {})["shop_button_order"] = list(order_list)
    update_db_path("/settings/shop_button_order", list(order_list))

def set_shop_button_position(item_key, new_pos, db=None):
    """একটা নির্দিষ্ট শপ বাটনকে (item_key) new_pos (1-indexed) অবস্থানে নিয়ে
    যায় — বাকি বাটনগুলো স্বয়ংক্রিয়ভাবে শিফট হয়ে যাবে। Return: সেভ করা নতুন
    সম্পূর্ণ order list।"""
    if db is None:
        db = load_db()
    order = get_shop_button_order(db)
    if item_key not in order:
        return order
    order.remove(item_key)
    n = len(order)
    try:
        new_pos = int(new_pos)
    except (TypeError, ValueError):
        new_pos = n + 1
    new_pos = max(1, min(new_pos, n + 1))
    order.insert(new_pos - 1, item_key)
    set_shop_button_order(order, db)
    return order

def _shop_item_display_label(item_key, db=None):
    """একটা shop item key এর জন্য বর্তমান display label (Product1/Product2
    এর জন্য admin-সেট কাস্টম নাম, বাকি সব প্রোডাক্টের জন্য নিজের নাম)।"""
    if db is None:
        db = load_db()
    if item_key == PRODUCT1_ORDER_KEY:
        return get_product1_btn_label(db)
    if item_key == PRODUCT2_ORDER_KEY:
        return get_product2_btn_label(db)
    if item_key == PRODUCT3BULK_ORDER_KEY:
        return get_product3bulk_btn_label(db)
    return item_key

def _shop_item_role(item_key):
    if item_key == PRODUCT1_ORDER_KEY:
        return "product1"
    if item_key == PRODUCT2_ORDER_KEY:
        return "product2"
    if item_key == PRODUCT3BULK_ORDER_KEY:
        return "product3bulk"
    return "category_item"

def build_shop_reply_markup(db, lang="en", row_width=2, include_back=True):
    """Buy Mail শপ মেনুর পুরো Reply Keyboard বানায় — admin-সেট order অনুযায়ী
    (get_shop_button_order) সব বাটন 2-by-2 করে সাজিয়ে, সাথে শেষে Back বাটন।"""
    markup = types.ReplyKeyboardMarkup(row_width=row_width, resize_keyboard=True)
    ordered_keys = get_shop_button_order(db)
    for i in range(0, len(ordered_keys), row_width):
        row_keys = ordered_keys[i:i + row_width]
        markup.add(*[KbBtn(_shop_item_display_label(k, db), role=_shop_item_role(k)) for k in row_keys])
    if include_back:
        markup.add(KbBtn(LANG[lang]["back"], role="back"))
    return markup

def show_shop_menu(user_id, db=None):
    if db is None:
        db = load_db()
    lang = get_user_lang(user_id, db)
    markup = build_shop_reply_markup(db, lang=lang)
    bot.send_message(user_id, "🛍️ <b>Choose a product:</b>",
        reply_markup=markup, parse_mode="HTML")

def _product1_item_select_view(page=1, db=None):
    """Product1 এর item বাটনগুলো পেজ-আকারে (২টা করে এক সারি, প্রতি পেজে
    PRODUCT1_ITEM_PAGE_SIZE টা) রিটার্ন করে (text, markup) সহ ⬅️ Prev/Next ➡️
    pagination বাটন (Edu Mail এর মতোই প্যাটার্ন)। বাটনগুলোর নাম admin panel
    (Product1 Manager) থেকে কাস্টোমাইজ করা থাকলে সেটাই দেখাবে — ➕ Add দিয়ে
    নতুন item যোগ হলে সেগুলোও (পরের পেজে) স্বয়ংক্রিয়ভাবে দেখা যাবে।"""
    if db is None:
        db = load_db()
    order = get_product1_active_display_order(db)
    page_size = PRODUCT1_ITEM_PAGE_SIZE
    total = len(order)
    total_pages = max(1, (total + page_size - 1) // page_size)
    page = max(1, min(page, total_pages))
    start = (page - 1) * page_size
    end = min(page * page_size, total)
    page_items = order[start:end]

    markup = types.InlineKeyboardMarkup(row_width=2)
    btns = [InlineBtn(f"📦 {get_product1_item_name(i, db)}", style="primary",
                callback_data=f"product1_item_{i}") for i in page_items]
    for i in range(0, len(btns), 2):
        markup.row(*btns[i:i+2])

    nav_row = []
    if page > 1:
        nav_row.append(InlineBtn("⬅️ Prev", callback_data=f"product1_page_{page-1}"))
    if page < total_pages:
        nav_row.append(InlineBtn("Next ➡️", callback_data=f"product1_page_{page+1}"))
    if nav_row:
        markup.row(*nav_row)

    text = (
        "📦 <b>Product items select করুন:</b>"
        + (f"\nPage {page}/{total_pages}" if total_pages > 1 else "")
    )
    return text, markup

def show_product1_item_select(user_id, db=None):
    """Product1 বাটনে ক্লিক করলে — item select করতে বলে + item বাটন গুলো
    পেজ-আকারে (প্রতি পেজে PRODUCT1_ITEM_PAGE_SIZE টা, ২টা করে এক সারি) দেখায়,
    বাকি item গুলোর জন্য Next ➡️ বাটন সহ (Item 1 → Outlook; Item 12 → নতুন
    long_live/outlook_mixed item, ২ নাম্বার অবস্থানে; বাকিগুলো তাদের normal
    ক্রমে)। প্রতিটা ফিক্সড item hotmail143 API + local .xlsx stock — combined,
    ➕ Add দিয়ে যোগ করা নতুন item শুধু local stock দিয়ে চলে।"""
    if db is None:
        db = load_db()
    text, markup = _product1_item_select_view(1, db)
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)

