def _product3bulk_item_select_view(page=1, db=None):
    """Product3Bulk এর item বাটনগুলো পেজ-আকারে (২টা করে এক সারি, প্রতি পেজে
    PRODUCT3BULK_ITEM_PAGE_SIZE টা) রিটার্ন করে (text, markup) সহ ⬅️ Prev/Next ➡️
    pagination বাটন (Product1 এর মতোই প্যাটার্ন)। 🗑️ Delete করা বা 🔴 Off করা
    item এখানে দেখানো হয় না। বাটনগুলোর নাম admin panel (Product3Bulk Manager)
    থেকে কাস্টোমাইজ করা থাকলে সেটাই দেখাবে — ➕ Add দিয়ে নতুন item যোগ হলে
    সেগুলোও (পরের পেজে) স্বয়ংক্রিয়ভাবে দেখা যাবে।"""
    if db is None:
        db = load_db()
    order = get_product3bulk_active_display_order(db)
    page_size = PRODUCT3BULK_ITEM_PAGE_SIZE
    total = len(order)
    total_pages = max(1, (total + page_size - 1) // page_size)
    page = max(1, min(page, total_pages))
    start = (page - 1) * page_size
    end = min(page * page_size, total)
    page_items = order[start:end]

    markup = types.InlineKeyboardMarkup(row_width=2)
    btns = [InlineBtn(f"📦 {get_product3bulk_item_name(i, db)}", style="primary",
                callback_data=f"product3bulk_item_{i}") for i in page_items]
    for i in range(0, len(btns), 2):
        markup.row(*btns[i:i+2])

    nav_row = []
    if page > 1:
        nav_row.append(InlineBtn("⬅️ Prev", callback_data=f"product3bulk_page_{page-1}"))
    if page < total_pages:
        nav_row.append(InlineBtn("Next ➡️", callback_data=f"product3bulk_page_{page+1}"))
    if nav_row:
        markup.row(*nav_row)

    text = (
        "📦 <b>Product item সিলেক্ট করুন:</b>"
        + (f"\nPage {page}/{total_pages}" if total_pages > 1 else "")
    )
    return text, markup

def show_product3bulk_item_select(user_id, db=None):
    """Product3Bulk বাটনে ক্লিক করলে — item select করতে বলে + item বাটন গুলো
    পেজ-আকারে (প্রতি পেজে PRODUCT3BULK_ITEM_PAGE_SIZE টা, ২টা করে এক সারি) দেখায়,
    বাকি item গুলোর জন্য Next ➡️ বাটন সহ (সংখ্যা ও নাম admin panel থেকে
    কাস্টোমাইজ করা)। যেই item এর Website Product ID কানেক্ট করা হয়নি সেটা
    ক্লিক করলে "🚧 Coming Soon" alert দেখাবে, আসল ফিচার/প্রোডাক্ট admin
    পরে যোগ করবে।"""
    if db is None:
        db = load_db()
    text, markup = _product3bulk_item_select_view(1, db)
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)

# ─── Edu Mail ক্যাটাগরি item বাটন — pagination (৪টা ক্যাটাগরিতেই একই সাইজ) ───
# ⚠️ item সংখ্যা আর fixed না — admin এখন Edu Mail Manager থেকে item Add/Delete/
# On-off করতে পারে (দেখুন get_edu_mail_active_items() / get_edu_mail_disabled_items())।
# এই constants গুলো শুধু ডিফল্ট/প্রাথমিক item সংখ্যা হিসেবে থেকে গেছে (migration base)।
EDU_MAIL_0_1_TOTAL_ITEMS   = 25
EDU_MAIL_2_7_TOTAL_ITEMS   = 16
EDU_MAIL_8_13_TOTAL_ITEMS  = 6
EDU_MAIL_14_90_TOTAL_ITEMS = 9
EDU_MAIL_ITEM_PAGE_SIZE = 10   # প্রতি পেজে ১০টা (৫টা করে ২ সারি) — বাকিগুলো Next দিয়ে
EDU_MAIL_ITEM_ROW_WIDTH = 2

def _edu_mail_generic_page_view(cat_short, page=1, db=None, user_id=None):
    """
    একটা Edu Mail ক্যাটাগরির item বাটনগুলো পেজ-আকারে দেখায় (৫টা পাশাপাশি, প্রতি
    পেজে ১০টা) — শুধু active + On থাকা item গুলোই দেখানো হয় (admin Add করা নতুন
    item এখানেই যোগ হবে, Off/Delete করা item এখানে দেখা যাবে না)।
    বাটনের নাম admin panel (Edu Mail Manager) থেকে চেঞ্জ করা থাকলে সেটাই দেখাবে।
    (item বাটনগুলোর কালার এই ইউজারের current Edu Mail random combo থেকে নেওয়া হয়)
    """
    if db is None:
        db = load_db()
    meta = _edu_mail_mgr_cats()[cat_short]
    disabled = get_edu_mail_disabled_items(cat_short, db)
    visible_items = [n for n in get_edu_mail_active_items(cat_short, db) if n not in disabled]

    page_size = EDU_MAIL_ITEM_PAGE_SIZE
    total = len(visible_items)
    total_pages = max(1, (total + page_size - 1) // page_size)
    page = max(1, min(page, total_pages))
    start = (page - 1) * page_size
    end = min(page * page_size, total)
    page_items = visible_items[start:end]

    item_style = _get_edu_mail_combo(user_id)["item"] if user_id is not None else random.choice(_EDU_MAIL_COLOR_CHOICES)
    markup = types.InlineKeyboardMarkup(row_width=EDU_MAIL_ITEM_ROW_WIDTH)
    if page_items:
        markup.add(*[
            InlineBtn(get_edu_mail_item_name(cat_short, n, db), style=item_style,
                      callback_data=f"edumail_{cat_short}_item_{n}")
            for n in page_items
        ])

    nav_row = []
    if page > 1:
        nav_row.append(InlineBtn("⬅️ Prev", callback_data=f"edumail_{cat_short}_page_{page-1}"))
    if page < total_pages:
        nav_row.append(InlineBtn("Next ➡️", callback_data=f"edumail_{cat_short}_page_{page+1}"))
    if nav_row:
        markup.add(*nav_row)

    markup.add(InlineBtn("🔙 Back", callback_data="edumail_back_categories"))

    if not total:
        text = f"📧 <b>{meta['label']}</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n⚠️ এই ক্যাটাগরির item শীঘ্রই যুক্ত করা হবে।"
    else:
        text = (
            f"📧 <b>{meta['label']}</b>\n"
            "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
            + (f"Page {page}/{total_pages} — " if total_pages > 1 else "")
            + "একটা সিলেক্ট করুন:"
        )
    return text, markup

def _edu_mail_0_1_page_view(page=1, db=None, user_id=None):
    return _edu_mail_generic_page_view("01", page, db, user_id)

def _edu_mail_2_7_page_view(page=1, db=None, user_id=None):
    return _edu_mail_generic_page_view("27", page, db, user_id)

def _edu_mail_8_13_page_view(page=1, db=None, user_id=None):
    return _edu_mail_generic_page_view("813", page, db, user_id)

def _edu_mail_14_90_page_view(page=1, db=None, user_id=None):
    return _edu_mail_generic_page_view("1490", page, db, user_id)


# ══════════════════════════════════════════════════════
# 🎲 EDU MAIL — RANDOM COLOR COMBINATION (per Edu Mail session)
# ══════════════════════════════════════════════════════
# Edu Mail বাটনে ক্লিক করলে category বাটন (4টা) ও sub-product/item
# বাটনগুলোর জন্য একটা random color কম্বিনেশন জেনারেট হয় এবং সেই
# ইউজারের জন্য মেমরিতে রাখা হয়। ইউজার যতক্ষণ categories/sub-items
# এর মধ্যে ঘোরাঘুরি করে (back/next/prev করে), ততক্ষণ এই একই
# কম্বিনেশন দেখানো হয়। ইউজার যখন আবার নতুন করে Edu Mail বাটনে
# ক্লিক করে, তখন নতুন একটা random কম্বিনেশন জেনারেট হয়। প্রতিটা
# ইউজারের জন্য এই লজিক আলাদাভাবে (independent) কাজ করে।
_EDU_MAIL_COLOR_CHOICES = ["primary", "success", "danger"]
_edu_mail_color_session = {}   # user_id(str) -> combo dict

def _gen_edu_mail_color_combo():
    """৪টা ক্যাটাগরি বাটন + sub-product/item বাটনের জন্য একটা নতুন random কালার কম্বিনেশন তৈরি করে।"""
    return {
        "edumail_cat_0_1":   random.choice(_EDU_MAIL_COLOR_CHOICES),
        "edumail_cat_2_7":   random.choice(_EDU_MAIL_COLOR_CHOICES),
        "edumail_cat_8_13":  random.choice(_EDU_MAIL_COLOR_CHOICES),
        "edumail_cat_14_90": random.choice(_EDU_MAIL_COLOR_CHOICES),
        "item":              random.choice(_EDU_MAIL_COLOR_CHOICES),
    }

def _get_edu_mail_combo(user_id, refresh=False):
    """
    ইউজারের current Edu Mail color combo রিটার্ন করে।
    refresh=True দিলে (নতুন Edu Mail সেশন শুরু হলে) নতুন random combo জেনারেট
    করে সেভ করে দেয়, নাহলে আগের সেভ করা combo-ই রিটার্ন করে (না থাকলে নতুন
    একটা বানিয়ে সেভ করে)।
    """
    user_id = str(user_id)
    if refresh or user_id not in _edu_mail_color_session:
        _edu_mail_color_session[user_id] = _gen_edu_mail_color_combo()
    return _edu_mail_color_session[user_id]


def _edu_mail_categories_view(user_id=None):
    """
    Edu Mail → Categories inline menu এর text + markup তৈরি করে।
    Buttons (1 by 1 — একটার নিচে একটা): 0-1day / 2-7days / 8-13days / 14-90days
    তারপর: Cancel | Terms & Conditions
    (৪টা ক্যাটাগরি বাটনের কালার এই ইউজারের current random combo থেকে নেওয়া হয়)
    """
    combo = _get_edu_mail_combo(user_id) if user_id is not None else _gen_edu_mail_color_combo()
    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn("Edu Mail 0-1day",   style=combo["edumail_cat_0_1"],   callback_data="edumail_cat_0_1"))
    markup.add(InlineBtn("Edu Mail 2-7days",  style=combo["edumail_cat_2_7"],   callback_data="edumail_cat_2_7"))
    markup.add(InlineBtn("Edu Mail 8-13days",  style=combo["edumail_cat_8_13"],  callback_data="edumail_cat_8_13"))
    markup.add(InlineBtn("Edu Mail 14-90days", style=combo["edumail_cat_14_90"], callback_data="edumail_cat_14_90"))
    markup.add(
        InlineBtn("❌ Cancel", style="danger", callback_data="edumail_cancel"),
        InlineBtn("📄 Terms & Conditions", callback_data="edumail_terms"),
    )
    text = (
        "🏷 <b>Categories</b>\n"
        "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        "Select a category:"
    )
    return text, markup

def _show_edu_mail_submenu(user_id, db=None):
    """
    Edu Mail parent বাটন ক্লিক করলে এই Categories inline menu আসবে।
    (আগে এখানে Edu Mail 24H / 72H / 24hr — এই ৩টা reply-keyboard বাটন ছিল,
    এখন সেগুলোর বদলে ৪টা day-range category ইনলাইন বাটন দেখানো হয়।)
    এখানেই Edu Mail বাটন ক্লিকের নতুন random color combo জেনারেট হয় (refresh=True),
    যা এই সেশনে categories ও sub-item বাটনগুলোতে ব্যবহার হবে।
    """
    _get_edu_mail_combo(user_id, refresh=True)
    text, markup = _edu_mail_categories_view(user_id)
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)


def show_product_detail_with_subnav(user_id, product_name, db=None, display_name=None, edit_message_id=None, origin="shop"):
    if db is None:
        db = load_db()

    # ══════════════════════════════════════════
    # EDU MAIL PARENT → sub-keyboard দেখাও
    # ══════════════════════════════════════════
    if product_name == EDU_MAIL_PARENT:
        _show_edu_mail_submenu(user_id, db)
        return

    # API sub-product (Edu Mail 24H / 72H) — DB তে না থাকলেও চলবে
    _is_api_prod = product_name in API_PRODUCTS

    if not _is_api_prod and product_name not in db["products"]:
        # ✅ FIX: প্রোডাক্ট না পাওয়া গেলে origin অনুযায়ী সঠিক মেনুতে ফেরত পাঠাও —
        # আগে সবসময় Buy Mail এর show_shop_menu() এ পাঠানো হতো, যার ফলে
        # Buy Proxy / All VPN থেকে আসা প্রোডাক্ট (যেমন 9Proxy Package) না
        # পাওয়া গেলেও ভুল করে Buy Mail এর sub-product কীবোর্ড দেখাতো।
        if origin == "buy_proxy":
            handle_buy_proxy(user_id, db)
        else:
            show_shop_menu(user_id, db)
        return

    # Price: DB তে থাকলে সেটা, না থাকলে 0
    # ✅ NOTE: Edu Mail 24H / 72H এর price অবশ্যই DB তে (products node এ) সেট করতে হবে
    # ⚠️ FIX: কিছু item এর price DB তে non-numeric/corrupt ভ্যালু আকারে সেভ থাকলে
    # (যেমন খালি string, dict, বা garbage) সরাসরি float() কল করলে ValueError/TypeError
    # ছুঁড়ে পুরো handler crash করে দিতো — ইউজার তখন "Something went wrong" দেখতো,
    # কিন্তু আসল কারণ (কোন product, কী value) কোথাও লগ হতো না। এখন safe-parse করা
    # হচ্ছে, ব্যর্থ হলে 0 ধরে নিয়ে চালিয়ে যাওয়া হয় (আর কারণটা লগ হয়)।
    _raw_price = db["products"].get(product_name)
    try:
        price = float(_raw_price or 0)
    except (TypeError, ValueError):
        logging.error(f"show_product_detail_with_subnav: bad price value for {product_name!r}: {_raw_price!r}")
        price = 0.0
    # ⚡ Stock: cache hit হলে instant, miss হলে background এ fetch
    # pending_product সেট করো
    _pending_product_cache[user_id] = product_name
    # ✅ FIX: origin ও সেট করো (default "shop") — যেনো পুরনো/stale origin কখনো
    # ভুল product এ লিক না করে; "🔙 Back" এই origin দেখে সঠিক মেনুতে ফেরত যাবে
    _pending_product_origin[user_id] = origin
    # Stock — cache থেকে নাও (10s TTL), API call হলেও background এ হবে না
    stock = get_stock_count(product_name)

    # Flash Sale check
    flash_info = get_flash_sale_info(db, product_name)
    flash_text = ""
    display_price = price  # user কে দেখানো price
    if flash_info:
        remaining = flash_info.get("remaining_seconds", 0)
        if remaining > 0:
            h = remaining // 3600
            m = (remaining % 3600) // 60
            s = remaining % 60
            orig_price = flash_info.get("original_price", price)
            discount = flash_info.get("discount_percent", 0)
            discounted = flash_info.get("discounted_price", price)
            display_price = discounted  # flash sale price দেখাবে
            flash_text = (
                f"\n🔥 <b>FLASH SALE!</b> ⏱ <code>{h:02d}:{m:02d}:{s:02d}</code> বাকি\n"
                f"💥 <s>{orig_price} BDT</s> → <b>{discounted} BDT</b> ({discount}% OFF)\n"
            )

    # Flash sale থাকলে strikethrough দিয়ে original price + discounted price দেখাও
    personal_disc_user = get_effective_personal_discount(db, user_id, product_name)
    if flash_info:
        orig_price = flash_info.get("original_price", price)
        discounted = flash_info.get("discounted_price", price)
        def _fmt(p):
            if p == int(p):
                return str(int(p))
            return f"{p:.2f}"
        price_line = f"💵 <b>Price:</b> <s>{_fmt(orig_price)} BDT</s> → <code>{_fmt(discounted)} BDT</code>\n"
    elif personal_disc_user > 0:
        # Personal discount আছে — দেখাও
        discounted_personal = apply_discount(price, personal_disc_user)
        def _fmt(p):
            if p == int(p): return str(int(p))
            return f"{p:.2f}"
        _disc_label_lang = get_user_lang(user_id, db)
        _disc_label = (f"🏷️ <b>আপনার Personal Discount:</b> <code>{personal_disc_user:.0f}% OFF</code>\n"
                       if _disc_label_lang == "bn" else
                       f"🏷️ <b>Your Personal Discount:</b> <code>{personal_disc_user:.0f}% OFF</code>\n")
        price_line = (f"💵 <b>Price:</b> <s>{_fmt(price)} BDT</s> → <code>{_fmt(discounted_personal)} BDT</code>\n"
                      + _disc_label)
    else:
        price_line = f"💵 <b>Price:</b> <code>{price} BDT</code>\n"

    # ✅ FIX: শুধু Edu Mail parent — stock line দেখাবে না
    if product_name == EDU_MAIL_PARENT:
        stock_line = ""
    elif is_bulkmail_product(product_name):
        # Bulkmail product — bulkmail API থেকে stock আনো
        _bm_pid    = API_PRODUCTS[product_name]["product_id"]
        _cached_bm = _stock_count_cache.get(product_name)
        _now_bm    = _time_module.time()
        if _cached_bm and (_now_bm - _cached_bm[1]) < _STOCK_CACHE_TTL:
            bm_stock = _cached_bm[0]
        else:
            bm_stock = bulkmail_get_stock(_bm_pid)
            if bm_stock >= 0:
                _stock_count_cache[product_name] = (bm_stock, _now_bm)
        if bm_stock < 0:
            stock_line = "📦 <b>Stock:</b> <code>⚠️ চেক করা যায়নি</code>\n"
        elif bm_stock == 0:
            stock_line = "📦 <b>Stock:</b> 🔴 <b>Out of Stock</b>\n"
        else:
            stock_line = f"📦 <b>Stock:</b> <code>{bm_stock} pcs ✅</code>\n"
    elif is_codecraft_product(product_name):
        # CodeCraft (codecraftdeveloper.com) product — live stock আনো
        _cc_pid    = API_PRODUCTS[product_name]["product_id"]
        _cached_cc = _stock_count_cache.get(product_name)
        _now_cc    = _time_module.time()
        if _cached_cc and (_now_cc - _cached_cc[1]) < _STOCK_CACHE_TTL:
            cc_stock = _cached_cc[0]
        else:
            cc_stock = codecraft_get_stock(_cc_pid)
            if cc_stock >= 0:
                _stock_count_cache[product_name] = (cc_stock, _now_cc)
        if cc_stock < 0:
            stock_line = "📦 <b>Stock:</b> <code>⚠️ চেক করা যায়নি</code>\n"
        elif cc_stock == 0:
            stock_line = "📦 <b>Stock:</b> 🔴 <b>Out of Stock</b>\n"
        else:
            stock_line = f"📦 <b>Stock:</b> <code>{cc_stock} pcs ✅</code>\n"
    elif product_name in API_PRODUCTS:
        # API product — সরাসরি API call করে real stock আনো
        api_conf_r = API_PRODUCTS[product_name]
        # Cache আছে কিনা চেক করো (TTL মধ্যে থাকলে instant)
        _cached_entry = _stock_count_cache.get(product_name)
        _now_ts_s = _time_module.time()
        if _cached_entry and (_now_ts_s - _cached_entry[1]) < _STOCK_CACHE_TTL:
            cached_stock = _cached_entry[0]
        else:
            # Cache নেই বা expire — API call করো
            try:
                fresh_api = hotmail143_get_stock(api_conf_r["product_type"], api_conf_r["account_type"])

                # Local xlsx stock যোগ করো
                local_path_r = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
                local_r = 0
                if os.path.exists(local_path_r):
                    try:
                        _wb_r = openpyxl.load_workbook(local_path_r, read_only=True)
                        _ws_r = _wb_r.active
                        for _ri_r, _row_r in enumerate(_ws_r.iter_rows(values_only=True), start=1):
                            if _ri_r == 1: continue
                            if any(c is not None and str(c).strip() != "" for c in _row_r):
                                local_r += 1
                        _wb_r.close()
                    except Exception:
                        pass

                if fresh_api < 0:
                    # API error — পুরনো cache থাকলে সেটা রাখো, না থাকলে শুধু local দেখাও
                    if _cached_entry:
                        cached_stock = _cached_entry[0]
                        logging.warning(f"API stock error for {product_name}, using stale cache={cached_stock}")
                    else:
                        cached_stock = local_r if local_r > 0 else -1
                else:
                    cached_stock = fresh_api + local_r
                    _stock_count_cache[product_name] = (cached_stock, _now_ts_s)

            except Exception as _e:
                logging.warning(f"API stock fetch error {product_name}: {_e}")
                cached_stock = _cached_entry[0] if _cached_entry else -1

        if cached_stock < 0:
            stock_line = "📦 <b>Stock:</b> <code>⚠️ চেক করা যায়নি</code>\n"
        elif cached_stock == 0:
            stock_line = "📦 <b>Stock:</b> 🔴 <b>Out of Stock</b>\n"
        else:
            stock_line = f"📦 <b>Stock:</b> <code>{cached_stock} pcs ✅</code>\n"
    elif stock <= 0:
        stock_line = "📦 <b>Stock:</b> 🔴 <b>Out of Stock</b>\n"
    else:
        stock_line = f"📦 <b>Stock:</b> <code>{stock} pcs</code>\n"

    detail_msg = (
        f"🏷️ <b>{display_name or product_name}</b>\n"
        f"\n"
        f"{price_line}"
        f"{stock_line}"
    )
    if flash_text:
        detail_msg += flash_text

    # ✅ FIX 3: Description আগে, তারপর italic Features
    description = (db.get("product_details", {}).get(product_name) or {}).get("description", "")
    features = (db.get("product_details", {}).get(product_name) or {}).get("features", "")

    if description:
        detail_msg += f"\n📝 <b>Description:</b>\n{description}\n"
    if features:
        detail_msg += f"\n✨ <b>Features:</b>\n<i>{features}</i>\n"

    # ✅ FIX: Out of Stock হলে "নিচে অপশন বেছে নিন" prompt দেখানোর দরকার নেই —
    # কেনার কোনো valid অপশন নেই তাই এই লাইনটা suppress করা হচ্ছে।
    _is_out_of_stock = "Out of Stock" in stock_line
    if not _is_out_of_stock:
        detail_msg += f"\n\n<i>নিচে অপশন বেছে নিন 👇</i>"

    # ── Sub-product check: Gmail বা Facebook হলে sub-buttons দেখাও ──
    sub_config = db.get("sub_products", {}).get(product_name)
    if sub_config and sub_config.get("sub_items"):
        # Sub-items আছে → inline sub-buttons দেখাবে, সরাসরি কেনা যাবে না
        sub_items = sub_config["sub_items"]
        # enabled গুলো filter করো
        enabled_items = [s for s in sub_items if s.get("enabled", True)]
        if enabled_items:
            markup_sub = types.InlineKeyboardMarkup(row_width=2)
            btns = []
            for item in enabled_items:
                sub_name = item.get("name", "")
                sub_price = item.get("price", price)
                sub_stock = get_stock_count(f"{product_name}__{sub_name}")
                stock_icon = "✅" if sub_stock > 0 else "❌"
                btns.append(InlineBtn(
                    f"{stock_icon} {sub_name} — {sub_price}BDT", style="success",
                    callback_data=f"sub_buy_{product_name}__{sub_name}"
                ))
            # 2 পাশাপাশি
            for i in range(0, len(btns), 2):
                pair = btns[i:i+2]
                markup_sub.row( *[InlineBtn(_x, style="primary") for _x in pair])
            markup_sub.add(InlineBtn("🔙 Back", style="primary", callback_data="back_to_shop"))
            if edit_message_id:
                try:
                    bot.edit_message_text(detail_msg, user_id, edit_message_id,
                        parse_mode="HTML", reply_markup=markup_sub)
                    return
                except Exception:
                    pass
            bot.send_message(user_id, detail_msg,
                parse_mode="HTML", reply_markup=markup_sub)
            return

    # ✅ FIX 2: Custom product buttons (inline) দেখাও
    custom_buttons = db.get("product_buttons", {}).get(product_name) or []
    inline_btns = [b for b in custom_buttons if b.get("type") == "inline"]
    keyboard_btns = [b for b in custom_buttons if b.get("type") == "keyboard"]

    # Inline keyboard — flash timer + custom inline buttons
    inline_markup = types.InlineKeyboardMarkup(row_width=1)
    if flash_info:
        inline_markup.add(
            InlineBtn("🔄 Timer Refresh", style="primary", callback_data=f"refresh_flash_{product_name}")
        )
    for btn in inline_btns:
        if btn.get("url"):
            inline_markup.add(InlineBtn(btn["text"], style="primary", url=btn["url"]))

    # Reply keyboard — buy options + custom keyboard buttons
    buy_markup = get_product_buy_keyboard(user_id)
    # keyboard_btns থাকলে নতুন markup বানাও
    if keyboard_btns:
        lang = get_user_lang(user_id)
        L = LANG[lang]
        buy_markup = types.ReplyKeyboardMarkup(row_width=1, resize_keyboard=True)
        buy_markup.add( KbBtn(L["single_buy"], role="buy_single"))
        buy_markup.add( KbBtn(L["bulk_buy"], role="buy_bulk"))
        for kb in keyboard_btns:
            buy_markup.add( KbBtn(kb["text"], role="misc_option"))
        buy_markup.add( KbBtn("🔙 Back", role="back"))

    has_inline = flash_info or inline_btns
    if edit_message_id:
        # ✅ FIX: আগের লিস্ট/মেনু মেসেজ delete না করে সেটাই edit করে product
        # detail দেখানো হচ্ছে। শুধু persistent (reply/bottom) keyboard
        # edit_message_text দিয়ে বদলানো যায় না, তাই buy_markup attach করতে
        # ছোট্ট একটা prompt আলাদা মেসেজে পাঠানো হচ্ছে — কোনো মেসেজ ডিলিট হচ্ছে না।
        edited_ok = False
        try:
            bot.edit_message_text(detail_msg, user_id, edit_message_id,
                parse_mode="HTML", reply_markup=(inline_markup if has_inline else None))
            edited_ok = True
        except Exception:
            edited_ok = False
        if not edited_ok:
            bot.send_message(user_id, detail_msg, parse_mode="HTML",
                reply_markup=(inline_markup if has_inline else None))
        _lang_now2 = get_user_lang(user_id)
        _buy_prompt2 = "👇 Choose an option below:" if _lang_now2 == "en" else "👇 কেনার অপশন বেছে নিন:"
        bot.send_message(user_id, _buy_prompt2, reply_markup=buy_markup)
        return

    if has_inline:
        bot.send_message(user_id, detail_msg, parse_mode="HTML", reply_markup=inline_markup)
        # ✅ FIX: Language-aware buy option message
        _lang_now = get_user_lang(user_id)
        _buy_prompt = "👇 Choose an option below:" if _lang_now == "en" else "👇 কেনার অপশন বেছে নিন:"
        bot.send_message(user_id, _buy_prompt, reply_markup=buy_markup)
    else:
        bot.send_message(user_id, detail_msg, reply_markup=buy_markup, parse_mode="HTML")

def handle_single_buy_from_keyboard(user_id, db):
    product_name = _pending_product_cache.get(user_id) or db["users"].get(user_id, {}).get("pending_product")
    is_api = product_name in API_PRODUCTS if product_name else False
    if not product_name or (not is_api and product_name not in db["products"]):
        # product আবার select করতে বলো, main menu তে না
        bot.send_message(user_id, "⚠️ Please select a product first.",
            reply_markup=get_product_buy_keyboard(user_id)); return
    # ✅ BUG FIX: API product (Edu Mail 24H / 72H) DB তে নেই,
    # তাই db["products"].get() করলে 0 আসে এবং delivery হয় না।
    # সমাধান: DB তে না থাকলে API_PRODUCTS থেকে price নাও।
    # Admin যদি DB তে price সেট করে থাকে সেটাই priority পাবে।
    price = db["products"].get(product_name) 
    if price is None:
        # API product এর price DB তে নেই — admin কে price সেট করতে হবে
        bot.send_message(user_id,
            f"⚠️ <b>{product_name}</b> এর price সেট করা নেই!\n\n"
            f"Admin panel থেকে এই product এর price সেট করুন।",
            parse_mode="HTML", reply_markup=get_main_menu(user_id))
        logging.error(f"Price not set for API product: {product_name}")
        return
    price = float(price)

    # ── Out of Stock check ──
    stock = get_stock_count(product_name)
    # API product — API তে live stock থাকলে allow করো (local 0 হলেও চলবে)
    _is_api_single = product_name in API_PRODUCTS
    if stock <= 0 and not _is_api_single:
        bot.send_message(user_id,
            f"🔴 <b>Out of Stock!</b>\n\n"
            f"😔 দুঃখিত! <b>{_proxy_display_name(product_name)}</b> এখন স্টকে নেই।\n"
            f"পরে আবার চেষ্টা করুন।\n\n"
            f"⬅️ Back চাপুন বা অন্য product বেছে নিন।",
            parse_mode="HTML", reply_markup=get_product_buy_keyboard(user_id))
        return

    # ── Promo feature চেক ──
    promo_feature_on = db.get("settings", {}).get("promo_feature_enabled", True)

    # ── Personal Discount (Admin দেওয়া) check — global + product-specific ──
    personal_disc = get_effective_personal_discount(db, user_id, product_name)

    # New user discount auto-apply
    new_user_disc = get_new_user_discount(db)
    user_orders = db.get("users", {}).get(user_id, {}).get("orders", [])

    # Personal discount থাকলে সেটা সব discount এর চেয়ে বড় হিসেবে নাও
    auto_discount = max(personal_disc, new_user_disc if (new_user_disc > 0 and not user_orders) else 0)

    if auto_discount > 0:
        discounted_price = apply_discount(price, auto_discount)
        disc_label = f"🏷️ Personal {auto_discount:.0f}% ছাড়" if personal_disc >= auto_discount else f"🎁 নতুন user {auto_discount:.0f}% ছাড়"
        if promo_feature_on:
            cancel_btn = types.ReplyKeyboardMarkup(resize_keyboard=True)
            cancel_btn.add( KbBtn("⏭️ Skip", role="skip"), KbBtn("🔙 Back", role="back"))
            msg = bot.send_message(user_id,
                f"🎟️ <b>Promo / Coupon Code</b>\n\n{disc_label} পাবেন!\nঅথবা একটি <b>Promo Code</b> দিন বড় ছাড়ের জন্য।\n\n💡 Code না থাকলে <b>Skip</b> করুন।",
                parse_mode="HTML", reply_markup=cancel_btn)
            bot.register_next_step_handler(msg, lambda m: _single_buy_promo_step(m, product_name, price, auto_discount))
        else:
            final_price = apply_discount(price, auto_discount)
            current_balance = db["users"].get(user_id, {}).get("balance", 0)
            if current_balance < final_price:
                bot.send_message(user_id,
                    t(user_id, "insufficient_balance", total=final_price, bal=current_balance, short=round(final_price-current_balance,2), usd=with_usd_equiv(user_id, current_balance)),
                    reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
            _dispatch_purchase(user_id, product_name, 1, final_price, final_price, discount_percent=auto_discount)
        return

    if promo_feature_on:
        # Promo ON — promo code জিজ্ঞেস করো (personal_discount pass করো)
        cancel_btn = types.ReplyKeyboardMarkup(resize_keyboard=True)
        cancel_btn.add( KbBtn("⏭️ Skip", role="skip"), KbBtn("🔙 Back", role="back"))
        msg = bot.send_message(user_id,
            f"🎟️ <b>Promo / Coupon Code আছে?</b>\n\nথাকলে লিখুন, না থাকলে <b>Skip</b> করুন।",
            parse_mode="HTML", reply_markup=cancel_btn)
        # ✅ BUG FIX: personal_disc pass করো যাতে promo step এ combine হয়
        bot.register_next_step_handler(msg, lambda m: _single_buy_promo_step(m, product_name, price, personal_disc))
    else:
        # Promo OFF — personal discount apply করে buy করো
        final_price_direct = apply_discount(price, personal_disc)
        current_balance = db["users"].get(user_id, {}).get("balance", 0)
        if current_balance < final_price_direct:
            bot.send_message(user_id,
                t(user_id, "insufficient_balance", total=final_price_direct, bal=current_balance, short=round(final_price_direct-current_balance,2), usd=with_usd_equiv(user_id, current_balance)),
                reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
        _dispatch_purchase(user_id, product_name, 1, final_price_direct, final_price_direct, discount_percent=personal_disc)

def _single_buy_promo_step(message, product_name, price, auto_discount):
    user_id = str(message.chat.id)
    db = load_db()
    text = (message.text or "").strip()
    if text == "❌ Cancel":
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
    if text == "🔙 Back":
        # এক ধাপ back — buy one pcs / bulk buy / back অপশনে ফিরে যাও
        show_product_detail_with_subnav(user_id, product_name, db); return
    final_discount = auto_discount
    promo_code_used = None
    if text and text != "⏭️ Skip":
        is_valid, disc, msg_txt = validate_promo(db, user_id, text)
        if not is_valid:
            bot.send_message(user_id, msg_txt, parse_mode="HTML",
                reply_markup=get_main_menu(user_id)); return
        final_discount = max(disc, auto_discount)  # বড় discount নাও
        promo_code_used = text.strip().upper()
        bot.send_message(user_id, msg_txt, parse_mode="HTML")
    final_price = apply_discount(price, final_discount)
    current_balance = db["users"].get(user_id, {}).get("balance", 0)
    if current_balance < final_price:
        bot.send_message(user_id,
            t(user_id, "insufficient_balance", total=final_price, bal=current_balance, short=round(final_price-current_balance,2), usd=with_usd_equiv(user_id, current_balance)),
            reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
    if promo_code_used:
        apply_promo_usage(db, user_id, promo_code_used)
        # ⚡ Targeted write — শুধু promo data update করো
        update_db_path(f"/promo_codes/{promo_code_used}", db["promo_codes"][promo_code_used])
        update_db_path(f"/promo_usage/{promo_code_used}", db["promo_usage"].get(promo_code_used, {}))
    _dispatch_purchase(user_id, product_name, 1, final_price, final_price,
                     discount_percent=final_discount, promo_code=promo_code_used)

def handle_bulk_buy_from_keyboard(user_id, db):
    product_name = _pending_product_cache.get(user_id) or db["users"].get(user_id, {}).get("pending_product")
    is_api = product_name in API_PRODUCTS if product_name else False
    if not product_name or (not is_api and product_name not in db["products"]):
        bot.send_message(user_id, "⚠️ Please select a product first.",
            reply_markup=get_product_buy_keyboard(user_id)); return
    # ✅ BUG FIX: API product এর price DB তে না থাকলে error দাও
    price = db["products"].get(product_name)
    if price is None:
        bot.send_message(user_id,
            f"⚠️ <b>{product_name}</b> এর price সেট করা নেই!\n\n"
            f"Admin panel থেকে এই product এর price সেট করুন।",
            parse_mode="HTML", reply_markup=get_main_menu(user_id))
        logging.error(f"Price not set for API product: {product_name}")
        return
    price = float(price)

    # ── Out of Stock check ──
    stock_now = get_stock_count(product_name)
    # API product — API তে live stock থাকলে allow করো (local 0 হলেও চলবে)
    _is_api_bulk = product_name in API_PRODUCTS
    if stock_now <= 0 and not _is_api_bulk:
        bot.send_message(user_id,
            f"🔴 <b>Out of Stock!</b>\n\n"
            f"😔 দুঃখিত! <b>{_proxy_display_name(product_name)}</b> এখন স্টকে নেই।\n"
            f"পরে আবার চেষ্টা করুন।\n\n"
            f"⬅️ Back চাপুন বা অন্য product বেছে নিন।",
            parse_mode="HTML", reply_markup=get_product_buy_keyboard(user_id))
        return

    # ── Promo feature চেক ──
    promo_feature_on = db.get("settings", {}).get("promo_feature_enabled", True)

    if promo_feature_on:
        # Promo ON — promo code জিজ্ঞেস করো
        cancel_btn = types.ReplyKeyboardMarkup(resize_keyboard=True)
        cancel_btn.add( KbBtn("⏭️ Skip", role="skip"), KbBtn("🔙 Back", role="back"))
        msg = bot.send_message(user_id,
            "🎟️ <b>Promo / Coupon Code আছে?</b>\n\n থাকলে লিখুন, না থাকলে<b>Skip</b> korun.",
            parse_mode="HTML", reply_markup=cancel_btn)
        bot.register_next_step_handler(msg, lambda m: _bulk_promo_step(m, product_name, price))
    else:
        # Promo OFF — personal discount apply করে quantity step এ যাও
        _personal_disc_bulk = get_effective_personal_discount(db, user_id, product_name)
        _bulk_price = apply_discount(price, _personal_disc_bulk)
        stock = get_stock_count(product_name)
        _bulk_markup = types.ReplyKeyboardMarkup(resize_keyboard=True)
        _bulk_markup.add( KbBtn("🔙 Back", role="back"))
        msg = bot.send_message(user_id,
            t(user_id, "bulk_prompt", name=product_name, price=_bulk_price, stock=stock),
            parse_mode="HTML", reply_markup=_bulk_markup)
        bot.register_next_step_handler(msg, lambda m: receive_bulk_quantity(m, product_name, _bulk_price, None))

def _bulk_promo_step(message, product_name, price):
    user_id = str(message.chat.id)
    db = load_db()
    text = (message.text or "").strip()
    if text == "❌ Cancel":
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
    if text == "🔙 Back":
        show_product_detail_with_subnav(user_id, product_name, db); return
    # Personal discount auto-apply — global + product-specific
    personal_disc = get_effective_personal_discount(db, user_id, product_name)
    final_discount = personal_disc
    promo_code_used = None
    if text and text != "⏭️ Skip":
        is_valid, disc, msg_txt = validate_promo(db, user_id, text)
        if not is_valid:
            bot.send_message(user_id, msg_txt, parse_mode="HTML",
                reply_markup=get_main_menu(user_id)); return
        final_discount = max(disc, personal_disc)  # বড় discount নাও
        promo_code_used = text.strip().upper()
        bot.send_message(user_id, msg_txt, parse_mode="HTML")
    discounted_price = apply_discount(price, final_discount)
    stock = get_stock_count(product_name)
    _bulk_markup = types.ReplyKeyboardMarkup(resize_keyboard=True)
    _bulk_markup.add( KbBtn("🔙 Back", role="back"))
    msg = bot.send_message(user_id,
        t(user_id, "bulk_prompt", name=product_name, price=discounted_price, stock=stock),
        parse_mode="HTML", reply_markup=_bulk_markup)
    bot.register_next_step_handler(msg, lambda m: receive_bulk_quantity(m, product_name, discounted_price, promo_code_used))

def receive_bulk_quantity(message, product_name, price, promo_code=None):
    user_id = str(message.chat.id)
    db = load_db()
    lang = get_user_lang(user_id)
    L = LANG[lang]
    if message.text in (L["back"], L["cancel"], "🔙 Back"):
        show_product_detail_with_subnav(user_id, product_name, db); return
    _bulk_back = types.ReplyKeyboardMarkup(resize_keyboard=True)
    _bulk_back.add( KbBtn("🔙 Back", role="back"))
    if not message.text or not message.text.strip().isdigit():
        msg = bot.send_message(user_id, t(user_id, "invalid_number"),
            reply_markup=_bulk_back, parse_mode="HTML")
        bot.register_next_step_handler(msg, lambda m: receive_bulk_quantity(m, product_name, price, promo_code)); return
    quantity = int(message.text.strip())
    if quantity <= 0:
        msg = bot.send_message(user_id, t(user_id, "qty_zero"),
            reply_markup=_bulk_back, parse_mode="HTML")
        bot.register_next_step_handler(msg, lambda m: receive_bulk_quantity(m, product_name, price, promo_code)); return
    if quantity > MAX_BULK_QUANTITY:
        msg = bot.send_message(user_id,
            f"❌ <b>সর্বোচ্চ {MAX_BULK_QUANTITY} পিস একসাথে কেনা যাবে!</b>",
            reply_markup=_bulk_back, parse_mode="HTML")
        bot.register_next_step_handler(msg, lambda m: receive_bulk_quantity(m, product_name, price, promo_code)); return
    stock = get_stock_count(product_name)
    if stock < quantity:
        bot.send_message(user_id,
            t(user_id, "insufficient_stock", qty=quantity, stock=stock),
            reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
    total_price = round(price * quantity, 2)
    current_balance = db["users"].get(user_id, {}).get("balance", 0)
    if current_balance < total_price:
        shortage = total_price - current_balance
        bot.send_message(user_id,
            t(user_id, "insufficient_balance", total=total_price, bal=current_balance, short=shortage, usd=with_usd_equiv(user_id, current_balance)),
            reply_markup=get_main_menu(user_id), parse_mode="HTML"); return
    if promo_code:
        apply_promo_usage(db, user_id, promo_code)
        # ⚡ Targeted write — শুধু promo data update করো
        update_db_path(f"/promo_codes/{promo_code}", db["promo_codes"][promo_code])
        update_db_path(f"/promo_usage/{promo_code}", db["promo_usage"].get(promo_code, {}))
    _dispatch_purchase(user_id, product_name, quantity, price, total_price, promo_code=promo_code)

