def show_referral_info(user_id, db=None):
    if db is None:
        db = load_db()
    referral_link = f"https://t.me/{BOT_USERNAME}?start={user_id}"
    bonus = db["settings"].get("refer_bonus", 2)
    refer_count = db["users"].get(user_id, {}).get("refer_count", 0)
    total_earned = refer_count * bonus
    share_text = t(user_id, "share_link_share_text", bonus=bonus)
    # ✅ Telegram এর native share/forward ডায়ালগ ওপেন করে — ইউজার
    # সরাসরি যেকোনো কন্টাক্ট/গ্রুপ/চ্যানেলে লিংকটা ফরোয়ার্ড করতে পারবে
    share_url = f"https://t.me/share/url?url={_url_quote(referral_link, safe='')}&text={_url_quote(share_text, safe='')}"
    markup = types.InlineKeyboardMarkup()
    markup.add(InlineBtn(t(user_id, "share_link_btn"), style="success", url=share_url))
    bot.send_message(user_id,
        t(user_id, "refer_msg",
          link=referral_link, bonus=bonus,
          count=refer_count, total=total_earned),
        parse_mode="HTML", reply_markup=markup)

