def show_deposit_menu(user_id, message_id=None):
    lang = get_user_lang(user_id)
    L = LANG[lang]
    db = load_db()
    cashback_on = db.get("settings", {}).get("cashback_enabled", True)
    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn(L["do_deposit"], style="success", callback_data="deposit_start_menu"))
    markup.add(InlineBtn(L["how_deposit"], style="success", callback_data="deposit_help"))
    markup.add(InlineBtn(L["dep_history_btn"], style="success", callback_data="deposit_history"))
    base_msg = t(user_id, "deposit_menu",
          bkash=BKASH_NUMBER, nagad=NAGAD_NUMBER,
          rocket=ROCKET_NUMBER, binance=BINANCE_ID)
    # Cashback OFF থাকলে cashback অফার অংশ বাদ দাও
    if not cashback_on:
        # Cashback Offer section strip করো
        for marker in ["🎁 <b>Cashback Offer:</b>", "🎁 <b>ক্যাশব্যাক অফার:</b>"]:
            idx = base_msg.find(marker)
            if idx != -1:
                base_msg = base_msg[:idx].rstrip()
                break
    # ⚡ message_id দেওয়া থাকলে সেই মেসেজটাই এডিট করো (Back নেভিগেশনে
    # ব্যবহার হয়), না দিলে নতুন মেসেজ পাঠাও (প্রথমবার ঢোকার সময়)
    if message_id:
        try:
            bot.edit_message_text(base_msg, user_id, message_id,
                reply_markup=markup, parse_mode="HTML")
            return
        except Exception:
            pass
    bot.send_message(user_id, base_msg, parse_mode="HTML", reply_markup=markup)

@bot.callback_query_handler(func=lambda call: call.data in ("deposit_start", "deposit_start_account", "deposit_start_menu"))
def start_deposit_process(call):
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_deposit_start_worker, call)

def _render_dep_method_select(user_id, message_id=None):
    """💳 Payment method বেছে নেওয়ার স্ক্রিন — message_id দিলে এডিট করবে, না দিলে নতুন পাঠাবে"""
    lang = get_user_lang(user_id)
    L = LANG[lang]
    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.row(
        InlineBtn("🟠 Bkash (auto)", style="primary", callback_data="dep_method_bkash"),
        InlineBtn("🟢 Nagad (auto)", style="success", callback_data="dep_method_nagad"),
    )
    markup.row(
        InlineBtn("🔴 Rocket (auto)", style="danger", callback_data="dep_method_rocket"),
        InlineBtn("🔵 Binance (auto)", callback_data="dep_method_binance_auto"),
    )
    markup.row(InlineBtn(L["go_back"], style="primary", callback_data="dep_back_to_origin"))
    # ✅ 'Make a Deposit' থেকে শুরু হওয়া প্রতিটা স্ক্রিনেই Cancel বাটন (লাল) থাকবে
    markup.row(InlineBtn(L["cancel"], style="danger", callback_data="dep_cancel_flow"))
    if message_id:
        try:
            bot.edit_message_text(t(user_id, "dep_method_select"),
                user_id, message_id, reply_markup=markup, parse_mode="HTML")
            return
        except Exception:
            pass
    bot.send_message(user_id, t(user_id, "dep_method_select"),
        reply_markup=markup, parse_mode="HTML")

def _deposit_start_worker(call):
    try:
        user_id = str(call.message.chat.id)
        # ⚡ কোন স্ক্রিন থেকে Deposit flow-এ ঢুকেছে সেটা মনে রাখো (Back বাটনের জন্য)
        origin = "menu" if call.data == "deposit_start_menu" else "account"
        _dep_set_origin(user_id, origin)
        _render_dep_method_select(user_id, message_id=call.message.message_id)
    except Exception as e:
        _cw_generic_crash_handler(call, "start_deposit_process", e)

@bot.callback_query_handler(func=lambda call: call.data.startswith("dep_method_"))
def handle_deposit_method(call):
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_deposit_method_worker, call)

def _deposit_method_worker(call):
    user_id = str(call.message.chat.id)
    method_data = {
        "dep_method_bkash":        ("Bkash",       BKASH_NUMBER,  True),
        "dep_method_nagad":        ("Nagad",       NAGAD_NUMBER,  True),
        "dep_method_rocket":       ("Rocket",      ROCKET_NUMBER, True),
        "dep_method_binance_auto": ("BinanceAuto", BINANCE_ID,    True),
    }
    if call.data not in method_data:
        bot.answer_callback_query(call.id, "Invalid method!", show_alert=True); return

    method, account, is_auto = method_data[call.data]

    instruction_key = "dep_binance_auto_instruction" if method == "BinanceAuto" else "dep_instruction"

    lang = get_user_lang(user_id)
    L = LANG[lang]

    # ✅ Binance এর instruction এ admin-সেট current USD→BDT rate দেখানো হয়,
    # যাতে ইউজার amount লেখার আগেই জানতে পারে ঠিক কত BDT এ কনভার্ট হবে
    text = t(user_id, instruction_key, method=method, account=account, rate=get_usd_bdt_rate())
    # ✅ FIX: আগে এখানে 'Select Payment Method' মেসেজটা ডিলিট করে নতুন মেসেজে
    # instruction পাঠানো হতো — ফলে মেথড লিস্ট মেসেজটা হঠাৎ উধাও হয়ে যেত।
    # এখন সেই একই মেসেজটাই edit করে ভিতরে deposit instruction (নম্বর + amount
    # প্রম্পট) দেখানো হচ্ছে, কিছু ডিলিট হচ্ছে না। শুধু persistent reply-keyboard
    # (লাল Cancel বাটন) edit_message_text দিয়ে সেট করা যায় না বলে সেটার জন্য
    # ছোট্ট একটা আলাদা মেসেজ পাঠানো হচ্ছে — মূল মেসেজটা অক্ষত থাকে।
    edited_ok = False
    try:
        bot.edit_message_text(text, chat_id=user_id, message_id=call.message.message_id,
            parse_mode="HTML")
        edited_ok = True
    except Exception:
        edited_ok = False
    if not edited_ok:
        bot.send_message(user_id, text, parse_mode="HTML")

    # instruction মেসেজেই "Enter Your Amount:👇" প্রম্পট আছে, তাই এখানে সেটা
    # আবার লেখা হচ্ছে না — শুধু persistent Cancel reply-keyboard বসানোর জন্য
    # ছোট্ট একটা মেসেজ পাঠানো হচ্ছে।
    sent_msg = bot.send_message(user_id, "👇", reply_markup=get_cancel_button(user_id))

    # ✅ নতুন amount-session শুরু — আগের stray-click fail counter রিসেট করো
    _dep_amount_clear_fail(user_id)
    bot.register_next_step_handler(sent_msg, lambda m: ask_for_amount(m, method, account, is_auto))

def ask_for_amount(message, method, account, is_auto):
    user_id = str(message.chat.id)
    try:
        lang = get_user_lang(user_id)
        L = LANG[lang]
        if message.text == L["cancel"]:
            _deposit_cancel_to_main(user_id); return
        try:
            amount_val = float(message.text.strip().replace(',', '.'))
            if amount_val <= 0:
                raise ValueError
            amount = amount_val
            _dep_amount_clear_fail(user_id)  # ✅ ভ্যালিড amount — fail counter রিসেট
        except (ValueError, AttributeError):
            # ══════════════════════════════════════════════════════
            # STRAY-CLICK GUARD — amount না লিখে অন্য বাটনে ক্লিক করলে
            # ১ম বার শুধু error দেখাবে (amount এর অপেক্ষা চালিয়ে যাবে),
            # ২য়বার আগের amount-সেশন বাতিল করে ওই ক্লিক/মেসেজ অনুযায়ী
            # স্বাভাবিকভাবে কাজ করবে (normal handler pipeline এ পাঠিয়ে)
            # ══════════════════════════════════════════════════════
            if _dep_amount_bump_fail(user_id) >= 2:
                _dep_amount_clear_fail(user_id)
                try:
                    bot.clear_step_handler_by_chat_id(chat_id=message.chat.id)
                except Exception:
                    pass
                bot.process_new_messages([message])
                return
            msg = bot.send_message(user_id, t(user_id, "dep_invalid_amount"),
                parse_mode="HTML", reply_markup=get_cancel_button(user_id))
            bot.register_next_step_handler(msg, lambda m: ask_for_amount(m, method, account, is_auto)); return

        # 🔵 Binance Auto — এখানে ইউজার USDT amount দিচ্ছে (BDT নয়), তাই
        # deposit limit চেক করার আগে BDT equivalent এ কনভার্ট করা দরকার।
        # limit চেক শেষে username জিজ্ঞাসা করে আলাদা inner handler এ যাও।
        if method == "BinanceAuto":
            bdt_equivalent = round(amount * get_usd_bdt_rate(), 2)
            if bdt_equivalent < MIN_DEPOSIT:
                msg = bot.send_message(user_id, t(user_id, "dep_min"),
                    parse_mode="HTML", reply_markup=get_cancel_button(user_id))
                bot.register_next_step_handler(msg, lambda m: ask_for_amount(m, method, account, is_auto)); return
            if bdt_equivalent > MAX_DEPOSIT_AMOUNT:
                msg = bot.send_message(user_id,
                    f"❌ <b>সর্বোচ্চ ডিপোজিট {MAX_DEPOSIT_AMOUNT} BDT!</b>\n\n"
                    f"একবারে এর বেশি ডিপোজিট করা যাবে না।\n"
                    f"সাহায্যের জন্য: @{SUPPORT_USERNAME}",
                    parse_mode="HTML", reply_markup=get_cancel_button(user_id))
                bot.register_next_step_handler(msg, lambda m: ask_for_amount(m, method, account, is_auto)); return

            lang_bn = (lang == "bn")
            display_usdt = int(amount) if amount == int(amount) else amount
            # ✅ FIX: আগে int(bdt_equivalent) দিয়ে পয়সার অংশ truncate হয়ে যেত
            # (যেমন 1259.50 → 1259 দেখাতো, ৫০ পয়সা হারিয়ে)। এখন fmt_bdt_precise
            # দিয়ে ঠিক ততটাই দেখানো হচ্ছে যতটা approve হলে ক্রেডিট হবে।
            display_bdt = fmt_bdt_precise(bdt_equivalent)
            prompt = (
                (
                    f"⚡ <b>Binance ডিপোজিট</b>\n\n"
                    f"💰 Amount: <b>{display_usdt}USDT</b> (≈{display_bdt}BDT)\n\n"
                    f"👉আপনার Binance Username পাঠান:👇"
                ) if lang_bn else (
                    f"⚡ <b>Binance Deposit</b>\n\n"
                    f"💰 Amount: <b>{display_usdt}USDT</b> (≈{display_bdt}BDT)\n\n"
                    f"👉Send your Binance Username:👇"
                )
            )
            username_kb = types.ReplyKeyboardMarkup(resize_keyboard=True)
            username_kb.add(KbBtn(LANG[lang]["cancel"], role="cancel"))
            msg = bot.send_message(user_id, prompt,
                parse_mode="HTML", reply_markup=username_kb)
            bot.register_next_step_handler(msg,
                lambda m: process_binance_auto_username(m, account, amount, bdt_equivalent))
            return

        if amount < MIN_DEPOSIT:
            msg = bot.send_message(user_id, t(user_id, "dep_min"),
                parse_mode="HTML", reply_markup=get_cancel_button(user_id))
            bot.register_next_step_handler(msg, lambda m: ask_for_amount(m, method, account, is_auto)); return

        # ✅ SECURITY: সর্বোচ্চ deposit limit
        if amount > MAX_DEPOSIT_AMOUNT:
            msg = bot.send_message(user_id,
                f"❌ <b>সর্বোচ্চ ডিপোজিট {MAX_DEPOSIT_AMOUNT} BDT!</b>\n\n"
                f"একবারে এর বেশি ডিপোজিট করা যাবে না।\n"
                f"সাহায্যের জন্য: @{SUPPORT_USERNAME}",
                parse_mode="HTML", reply_markup=get_cancel_button(user_id))
            bot.register_next_step_handler(msg, lambda m: ask_for_amount(m, method, account, is_auto)); return

        # amount integer format এ দেখাও (12.0 → 12)
        display_amount = int(amount) if amount == int(amount) else amount

        msg = bot.send_message(user_id,
            t(user_id, "dep_trxid_prompt", method=method, amount=display_amount),
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg,
            lambda m: process_deposit_request(m, method, account, amount, is_auto))

    except Exception as e:
        tb = traceback.format_exc()
        logging.error(f"ask_for_amount CRASH | user={user_id} | err={e}\n{tb}")
        try:
            bot.send_message(user_id,
                "❌ <b>কিছু একটা সমস্যা হয়েছে!</b>\n\n"
                "আবার চেষ্টা করুন অথবা সাপোর্টে যোগাযোগ করুন:\n"
                f"@{SUPPORT_USERNAME}",
                parse_mode="HTML", reply_markup=get_main_menu(user_id))
        except Exception:
            pass
        # 🆕 FIX: এই handler এ আগে admin notification ছিল না (নিচের
        # process_deposit_request এ ছিল) — এখন consistent ভাবে admin কেও জানানো হচ্ছে
        try:
            bot.send_message(ADMIN_ID,
                f"🚨 <b>ask_for_amount Crash!</b>\n\n"
                f"👤 User: <code>{user_id}</code>\n"
                f"💳 Method: {method}\n"
                f"❌ Error: <code>{str(e)[:300]}</code>",
                parse_mode="HTML")
        except Exception:
            pass

def process_deposit_request(message, method, account, amount, is_auto):
    """
    ══════════════════════════════════════════════════════════
    🔒 SECURE DEPOSIT VERIFICATION — v2.1
    ══════════════════════════════════════════════════════════
    Bkash/Nagad/Rocket:
      • TrxID submit → বট SMS server এ check করে
      • SMS confirmed থাকলে → সাথে সাথে APPROVE
      • SMS না থাকলে → Pending save (SMS আসলে auto approve)
      • User reject হলে আবার চেষ্টা করতে পারবে
    Binance:
      • আগের মতোই manual admin approval
    ══════════════════════════════════════════════════════════
    """
    user_id = str(message.chat.id)
    try:
        _process_deposit_request_inner(message, user_id, method, account, amount, is_auto)
    except Exception as e:
        logging.error(f"process_deposit_request CRASH | user={user_id} | method={method} | err={e}", exc_info=True)
        try:
            bot.send_message(user_id,
                "❌ <b>কিছু একটা সমস্যা হয়েছে!</b>\n\n"
                "আবার চেষ্টা করুন অথবা সাপোর্টে যোগাযোগ করুন:\n"
                f"@{SUPPORT_USERNAME}",
                parse_mode="HTML",
                reply_markup=get_main_menu(user_id))
        except Exception:
            pass
        try:
            bot.send_message(ADMIN_ID,
                f"🚨 <b>Deposit Handler Crash!</b>\n\n"
                f"👤 User: <code>{user_id}</code>\n"
                f"💳 Method: {method}\n"
                f"💰 Amount: {amount}\n"
                f"❌ Error: <code>{str(e)[:300]}</code>",
                parse_mode="HTML")
        except Exception:
            pass

def _process_deposit_request_inner(message, user_id, method, account, amount, is_auto):
    """Inner handler — process_deposit_request এর try/except এ wrapped।"""
    lang = get_user_lang(user_id)
    L = LANG[lang]

    if message.text == L["cancel"]:
        _deposit_cancel_to_main(user_id); return

    transaction_id = (message.text or "").strip().upper()

    # ── TrxID format validation ──
    if not transaction_id or len(transaction_id) < 5:
        msg = bot.send_message(user_id,
            "❌ <b>ভুল Transaction ID!</b>\n\n"
            "TrxID কমপক্ষে ৫ অক্ষরের হতে হবে।\n"
            "আবার চেষ্টা করুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg,
            lambda m: process_deposit_request(m, method, account, amount, is_auto))
        return

    # শুধু alphanumeric চরিত্র থাকতে হবে
    # Rocket এর TrxID numeric-only হতে পারে (10-14 digits), তাই সেটাও allow
    if not re.match(r'^[A-Z0-9]+$', transaction_id):
        msg = bot.send_message(user_id,
            "❌ <b>ভুল Transaction ID format!</b>\n\n"
            "TrxID শুধু letters ও numbers দিয়ে হয়।\n"
            "উদাহরণ: <code>ABC1234XYZ</code> বা <code>1234567890</code>\n\n"
            "আবার চেষ্টা করুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg,
            lambda m: process_deposit_request(m, method, account, amount, is_auto))
        return

    db = load_db()

    # Cooldown removed — যেকোনো সময় deposit করা যাবে

    # ✅ SECURITY: Daily deposit limit check
    today = datetime.now(BD_TZ).strftime("%d/%m/%Y")
    daily_total = sum(
        int(float(r.get("amount", 0)))
        for r in db.get("deposit_requests", {}).values()
        if r.get("user_id") == user_id
        and r.get("status") == "approved"
        and r.get("date", "").startswith(today)
    )
    if daily_total + amount > MAX_DAILY_DEPOSIT:
        remaining_limit = MAX_DAILY_DEPOSIT - daily_total
        bot.send_message(user_id,
            f"❌ <b>দৈনিক ডিপোজিট সীমা অতিক্রম!</b>\n\n"
            f"\n"
            f"📊 আজ করেছেন: <b>{daily_total} BDT</b>\n"
            f"✅ আজ আর করতে পারবেন: <b>{max(0, remaining_limit)} BDT</b>\n"
            f"🔄 সীমা রিসেট হয় প্রতি মধ্যরাতে।\n"
            f"\n"
            f"বেশি লাগলে সাপোর্টে যোগাযোগ করুন।",
            parse_mode="HTML", reply_markup=get_main_menu(user_id))
        return

    # ══════════════════════════════════════════════════
    # 🔒 SECURITY CHECK 0: TrxID blocked check (3 attempt limit)
    # ══════════════════════════════════════════════════
    if is_trx_blocked(db, user_id, transaction_id):
        bot.send_message(user_id,
            "🚫 <b>এই TrxID Block করা হয়েছে!</b>\n\n"
            "\n"
            "আপনি এই TrxID দিয়ে ৩ বারের বেশি\n"
            "চেষ্টা করেছেন। এটি block করা হয়েছে।\n\n"
            f"📞 সাপোর্টে যোগাযোগ করুন:\n"
            f"@{SUPPORT_USERNAME}\n"
            "",
            parse_mode="HTML",
            reply_markup=get_main_menu(user_id))
        return

    # ══════════════════════════════════════════════════
    # 🔒 SECURITY CHECK 1: আগেই approve হওয়া TrxID block
    # ══════════════════════════════════════════════════
    if is_trxid_already_used(db, transaction_id):
        logging.warning(f"SECURITY: Duplicate TrxID attempt | User: {user_id} | TrxID: {transaction_id}")
        bot.send_message(user_id,
            "🚫 <b>এই Transaction ID আগেই ব্যবহার হয়েছে!</b>\n\n"
            "\n"
            "❌ একই TrxID দিয়ে দুইবার deposit সম্ভব নয়।\n"
            "✅ সঠিক TrxID দিয়ে আবার চেষ্টা করুন।\n"
            "\n\n"
            "সমস্যা হলে support এ যোগাযোগ করুন।",
            parse_mode="HTML", reply_markup=get_main_menu(user_id))
        # Admin কে alert
        try:
            bot.send_message(ADMIN_ID,
                f"🚨 <b>Duplicate TrxID Attempt!</b>\n\n"
                f"👤 <b>User:</b> <code>{user_id}</code>\n"
                f"🔑 <b>TrxID:</b> <code>{transaction_id}</code>\n"
                f"💳 <b>Method:</b> {method}\n"
                f"💰 <b>Amount:</b> {amount} BDT\n"
                f"📅 <b>Time:</b> {get_now()}\n\n"
                f"⚠️ <i>সম্ভাব্য fraud attempt!</i>",
                parse_mode="HTML")
        except: pass
        return

    # ══════════════════════════════════════════════════════════
    # 🔒 BKASH / NAGAD / ROCKET — SMS Verification
    # ══════════════════════════════════════════════════════════
    # Logic:
    #   Case 1: SMS আছে + TrxID match + Amount match → ✅ AUTO APPROVE
    #   Case 2: SMS আছে + TrxID match + Amount মিলছে না → ❌ Error msg (pending না)
    #   Case 3: SMS নেই (TrxID unknown) → ❌ TrxID not found msg (pending না)
    #   Case 4: SMS আছে কিন্তু TrxID মিলছে না → ❌ TrxID not found msg
    #   Special: TrxID+Amount দুটোই match কিন্তু SMS bot এ আসেনি →
    #            ⏳ Pending (SMS আসলে auto approve হবে)
    # ══════════════════════════════════════════════════════════
    if is_auto:
        # 🔒 BUG FIX (double auto-approve): user submit ও SMS webhook
        # একই সময়ে চললে যাতে একই TrxID দুইবার approve না হয়, তাই এই
        # lock ব্যবহার করা হচ্ছে (process_sms এও একই lock ব্যবহার হয়)।
        with get_trx_lock(transaction_id):
            sms_pending = db.get("sms_pending_trxids", {})
            sms_data = sms_pending.get(transaction_id)  # TrxID দিয়ে SMS খোঁজো

            if sms_data:
                # ════════════════════════════════════════
                # SMS পাওয়া গেছে — Amount check করো
                # ════════════════════════════════════════
                sms_amount = sms_data.get("amount")
                sms_method = sms_data.get("method", "")

                # Method mismatch → error
                if sms_method.upper() != method.upper():
                    logging.warning(f"Method mismatch | User={user_id} | Claimed={method} | SMS={sms_method} | TrxID={transaction_id}")
                    bot.send_message(user_id,
                        f"❌ <b>ডিপোজিট ভেরিফাই হয়নি!</b>\n\n"
                        f"আপনার দেওয়া Amount বা TrxID সঠিক নয়।\n"
                        f"সঠিক তথ্য দিয়ে আবার চেষ্টা করুন।\n\n"
                        f"⚠️ সমস্যা হলে: @{SUPPORT_USERNAME}",
                        parse_mode="HTML", reply_markup=get_main_menu(user_id))
                    return

                # Amount mismatch → error msg, pending না
                # ✅ FIX: int() দিয়ে truncate করলে দশমিক মান (যেমন 10.5) হারিয়ে
                # যায় এবং ভুল amount ম্যাচ হয়ে যেতে পারে। তাই round(2) দিয়ে
                # compare করা হচ্ছে — দশমিক মান ঠিকভাবে ধরে রাখার জন্য।
                if sms_amount is not None:
                    try:
                        if round(float(sms_amount), 2) != round(float(amount), 2):
                            logging.warning(f"Amount mismatch | User={user_id} | Claimed={amount} | SMS={sms_amount} | TrxID={transaction_id}")
                            bot.send_message(user_id,
                                f"❌ <b>ডিপোজিট ভেরিফাই হয়নি!</b>\n\n"
                                f"আপনার দেওয়া Amount বা TrxID সঠিক নয়।\n"
                                f"সঠিক তথ্য দিয়ে আবার চেষ্টা করুন।\n\n"
                                f"⚠️ সমস্যা হলে: @{SUPPORT_USERNAME}",
                                parse_mode="HTML", reply_markup=get_main_menu(user_id))
                            return
                    except (ValueError, TypeError):
                        pass  # parse error → amount check skip, approve করো

                # ✅ TrxID + Method + Amount সব match → AUTO APPROVE
                # ✅ FIX: int() truncate করলে দশমিক মান (যেমন 10.5 → 10) হারিয়ে
                # যেত, তাই round(2) ব্যবহার করা হচ্ছে দশমিক মান ঠিক রাখতে।
                final_amount = round(float(sms_amount), 2) if sms_amount is not None else round(float(amount), 2)
                request_id   = f"DEP-{uuid.uuid4().hex[:6].upper()}"
                current_time = get_now()
                deposit_record = {
                    "request_id": request_id, "user_id": user_id,
                    "method": method, "amount": final_amount,
                    "transaction_id": transaction_id, "status": "pending",
                    "date": current_time, "is_auto": True
                }
                db["deposit_requests"][request_id] = deposit_record
                db["sms_pending_trxids"].pop(transaction_id, None)
                # ⚡ Targeted write — শুধু deposit record save করো
                update_db_path(f"/deposit_requests/{request_id}", deposit_record)
                _fb_ref(f"/sms_pending_trxids/{transaction_id}").delete()
                logging.info(f"AUTO APPROVE | User={user_id} | TrxID={transaction_id} | Method={method} | Amount={final_amount}")
                auto_approve_deposit(request_id, deposit_record, transaction_id, final_amount)
                return

            else:
                # ════════════════════════════════════════════════════════
                # SMS এ এই TrxID নেই।
                # দুটো সম্ভাবনা:
                #   A) TrxID ভুল → error msg দাও
                #   B) TrxID সঠিক কিন্তু SMS এখনো bot এ আসেনি → Pending save করো
                #
                # আমরা সবসময় Pending save করি — কারণ SMS delay হতে পারে।
                # SMS আসলে process_sms() নিজেই TrxID+Amount match করে auto approve করবে।
                # ════════════════════════════════════════════════════════

                # 3 বারের বেশি ভুল TrxID দিলে block করো
                attempt_count = increment_trx_attempt(db, user_id, transaction_id)
                if attempt_count >= 3:
                    block_trx_id(db, user_id, transaction_id)
                    # ⚡ Targeted write — শুধু blocked TrxID save করো
                    update_db_path(f"/blocked_trxids/{transaction_id}", db.get("blocked_trxids", {}).get(transaction_id, {}))
                    bot.send_message(user_id,
                        f"🚫 <b>এই TrxID block হয়ে গেছে!</b>\n\n"
                        f"আপনি {attempt_count} বার ভুল TrxID দিয়েছেন।\n"
                        f"সাহায্যের জন্য: @{SUPPORT_USERNAME}",
                        parse_mode="HTML", reply_markup=get_main_menu(user_id))
                    try:
                        bot.send_message(ADMIN_ID,
                            f"⛔ <b>TrxID Blocked ({attempt_count} attempts)</b>\n\n"
                            f"👤 User: <code>{user_id}</code>\n"
                            f"🔑 TrxID: <code>{transaction_id}</code>\n"
                            f"💳 Method: {method}\n"
                            f"📅 {get_now()}",
                            parse_mode="HTML")
                    except: pass
                    return

                # ⏳ Pending save — SMS আসলে auto approve হবে
                request_id   = f"DEP-{uuid.uuid4().hex[:6].upper()}"
                current_time = get_now()
                deposit_record = {
                    "request_id": request_id, "user_id": user_id,
                    "method": method, "amount": amount,
                    "transaction_id": transaction_id, "status": "pending",
                    "date": current_time, "is_auto": True
                }
                db["deposit_requests"][request_id] = deposit_record
                # ⚡ Targeted write — শুধু deposit record save করো
                update_db_path(f"/deposit_requests/{request_id}", deposit_record)
                logging.info(f"PENDING (SMS not received yet) | User={user_id} | TrxID={transaction_id} | Method={method} | Amount={amount}")

                try:
                    bot.send_message(ADMIN_ID,
                        f"⏳ <b>Pending Deposit (পেমেন্ট এখনো কনফার্ম হয়নি)</b>\n\n"
                        f"👤 User: <code>{user_id}</code> (@{get_cached_username(user_id)})\n"
                        f"🔑 TrxID: <code>{transaction_id}</code>\n"
                        f"💳 Method: {method}\n"
                        f"💰 Amount: {amount} BDT\n"
                        f"🆔 Request: <code>{request_id}</code>\n"
                        f"📅 {current_time}\n\n"
                        f"<i>Payment received হলে TrxID+Amount match হয়ে অটো approve হবে।</i>",
                        parse_mode="HTML")
                except: pass

                bot.send_message(user_id,
                    f"⏳ <b>Request Submitted!</b>\n\n"
                    f"🆔 <b>Request ID:</b> <code>{request_id}</code>\n"
                    f"💳 <b>Method:</b> {method}\n"
                    f"💰 <b>Amount:</b> {int(float(amount))} BDT\n"
                    f"🔑 <b>TrxID:</b> <code>{transaction_id}</code>\n"
                    f"📅 <b>Time:</b> {current_time}\n\n"
                    f"✅ It will be <b>automatically approved</b> once payment is received.\n\n"
                    f"⚠️ <i>If you face any issue: @{SUPPORT_USERNAME}</i>",
                    parse_mode="HTML", reply_markup=get_main_menu(user_id))
                return

    # ══════════════════════════════════════════════════
    # 🔵 BINANCE — Manual Admin Approval (আগের মতোই)
    # ══════════════════════════════════════════════════
    request_id = f"DEP-{uuid.uuid4().hex[:6].upper()}"
    current_time = get_now()

    deposit_record = {
        "request_id": request_id, "user_id": user_id,
        "method": method, "amount": amount,
        "transaction_id": transaction_id, "status": "pending",
        "date": current_time, "is_auto": False
    }
    db["deposit_requests"][request_id] = deposit_record
    # ⚡ Targeted write — শুধু deposit record save করো
    update_db_path(f"/deposit_requests/{request_id}", deposit_record)

    bot.send_message(user_id,
        t(user_id, "dep_submitted_manual", req_id=request_id, method=method,
          amount=amount, trx=transaction_id, date=current_time),
        parse_mode="HTML", reply_markup=get_main_menu(user_id))

    # Admin notification
    admin_message = (
        f"\n"
        f"🔵 Binance <b>Deposit Request</b>\n"
        f"\n\n"
        f"🆔 <b>Request ID:</b> <code>{request_id}</code>\n"
        f"👤 <b>User ID:</b> <code>{user_id}</code> (@{get_cached_username(user_id)})\n"
        f"💳 <b>Method:</b> {method}\n"
        f"💰 <b>Amount:</b> {amount} BDT\n"
        f"🔑 <b>TrxID:</b> <code>{transaction_id}</code>\n"
        f"📅 <b>Date:</b> {current_time}\n"
        f""
    )
    markup = types.InlineKeyboardMarkup()
    markup.add(
        InlineBtn("✅ Approve", style="success", callback_data=f"dep_approve_{request_id}"),
        InlineBtn("❌ Reject", style="danger", callback_data=f"dep_reject_{request_id}")
    )
    try:
        bot.send_message(ADMIN_ID, admin_message, reply_markup=markup, parse_mode="HTML")
    except: pass

    log_action("DEPOSIT_REQUEST", user_id,
               f"Method: {method}, Amount: {amount}, TrxID: {transaction_id}, Auto: {is_auto}")

def process_binance_auto_username(message, account, usdt_amount, bdt_equivalent):
    """
    Binance Auto ডিপোজিট flow এর শেষ ধাপ — ইউজারের (ঐচ্ছিক) masked
    username নিয়ে pending deposit_request তৈরি করে। ইউজার username না
    জানলে "skip" লিখতে পারে — তখন শুধু amount দিয়েই ম্যাচ করা হবে
    (ততক্ষণ পর্যন্তই নিরাপদ যতক্ষণ একই সময়ে দুইটা কাছাকাছি amount এর
    pending request না থাকে — _process_binance_auto_sms সেটা নিজেই
    ambiguous হলে auto-approve না করে admin কে জানায়)।
    """
    user_id = str(message.chat.id)
    try:
        lang = get_user_lang(user_id)
        L = LANG[lang]
        if message.text == L["cancel"]:
            _deposit_cancel_to_main(user_id); return

        raw = (message.text or "").strip()
        if not raw:
            lang_bn = (lang == "bn")
            retry_prompt = (
                "⚠️ Username দেওয়া বাধ্যতামূলক।\n\n👉আপনার Binance Username পাঠান:👇"
                if lang_bn else
                "⚠️ Username is required.\n\n👉Send your Binance Username:👇"
            )
            retry_kb = types.ReplyKeyboardMarkup(resize_keyboard=True)
            retry_kb.add(KbBtn(L["cancel"], role="cancel"))
            msg = bot.send_message(user_id, retry_prompt, parse_mode="HTML",
                reply_markup=retry_kb)
            bot.register_next_step_handler(msg,
                lambda m: process_binance_auto_username(m, account, usdt_amount, bdt_equivalent))
            return
        username = raw[:60]

        db = load_db()
        request_id = f"DEP-{uuid.uuid4().hex[:6].upper()}"
        current_time = get_now()

        deposit_record = {
            "request_id": request_id, "user_id": user_id,
            "method": "BinanceAuto", "amount": bdt_equivalent,
            "usdt_amount": usdt_amount, "binance_username": username,
            "transaction_id": f"BNCAUTO-{request_id}",
            "status": "pending", "date": current_time, "is_auto": True
        }
        db["deposit_requests"][request_id] = deposit_record
        update_db_path(f"/deposit_requests/{request_id}", deposit_record)
        _update_db_cache_in_place(db)

        # ✅ Notification হয়তো এই request submit করার আগেই এসে গেছে —
        # sms_pending_trxids এ থাকা BinanceAuto entries এর সাথে একবার
        # সাথে সাথে মিলিয়ে দেখো।
        matched = False
        for key, entry in list(db.get("sms_pending_trxids", {}).items()):
            if entry.get("method") != "BinanceAuto":
                continue
            try:
                entry_usdt = float(entry.get("amount", 0) or 0)
            except (ValueError, TypeError):
                continue
            if entry_usdt <= 0:
                continue
            diff_pct = abs(entry_usdt - usdt_amount) / entry_usdt * 100
            if diff_pct > BINANCE_SMS_AMOUNT_TOLERANCE_PCT:
                continue
            entry_username = (entry.get("username") or "").strip().lower()
            if username and entry_username and entry_username != username.lower():
                continue

            with get_trx_lock(key):
                fresh_db = load_db()
                if is_trxid_already_used(fresh_db, key):
                    continue
                # ✅ BUG FIX: আগে এখানে mark_trxid_used() কল করা হতো
                # auto_approve_deposit() এর *আগেই* — যার ফলে
                # auto_approve_deposit() এর নিজের "already used" চেক
                # সবসময় True পেত এবং approve না করেই SKIP করে দিত।
                # auto_approve_deposit() নিজেই approve সফল হলে TrxID
                # mark করে দেয়, তাই এখানে আলাদাভাবে mark করার দরকার নেই —
                # শুধু sms_pending_trxids থেকে entry সরিয়ে ফেলা হচ্ছে।
                fresh_db.get("sms_pending_trxids", {}).pop(key, None)
                update_db_path("/sms_pending_trxids", fresh_db.get("sms_pending_trxids", {}))
                _update_db_cache_in_place(fresh_db)
                auto_approve_deposit(request_id, deposit_record, key, bdt_equivalent)
            matched = True
            break

        if matched:
            return

        display_usdt = int(usdt_amount) if usdt_amount == int(usdt_amount) else usdt_amount
        # ✅ FIX: int(bdt_equivalent) পয়সা truncate করত — fmt_bdt_precise দিয়ে
        # প্রকৃত ক্রেডিট হবে এমন পুরো precision-সহ amount দেখানো হচ্ছে
        display_bdt = fmt_bdt_precise(bdt_equivalent)
        username_line = f"🔵 <b>Binance Username:</b> <code>{username}</code>\n"
        bot.send_message(user_id,
            f"⏳ <b>Request Submitted!</b>\n\n"
            f"🆔 Request ID: <code>{request_id}</code>\n"
            f"💳 Method: Binance\n"
            f"💰 Amount: {display_usdt} USDT (≈ {display_bdt} BDT)\n"
            f"📅 Time: {current_time}\n\n"
            f"✅ It will be auto-approved once the payment is verified.\n\n"
            f"⚠️ If you face any issue: @{SUPPORT_USERNAME}",
            parse_mode="HTML", reply_markup=get_main_menu(user_id))

        try:
            markup = types.InlineKeyboardMarkup()
            markup.add(
                InlineBtn("✅ Approve", style="success", callback_data=f"dep_approve_{request_id}"),
                InlineBtn("❌ Reject", style="danger", callback_data=f"dep_reject_{request_id}")
            )
            bot.send_message(ADMIN_ID,
                f"⚡ <b>Binance Deposit Request (Pending Notification)</b>\n\n"
                f"🆔 Request: <code>{request_id}</code>\n"
                f"👤 User: <code>{user_id}</code> (@{get_cached_username(user_id)})\n"
                f"💰 Amount: {display_usdt} USDT (≈ {display_bdt} BDT)\n"
                f"{username_line}"
                f"📅 {current_time}\n\n"
                f"⏳ <i>Payment received হলে auto-check করবে, না মিললে নিচের বাটনে ম্যানুয়ালি approve করতে পারবেন।</i>",
                parse_mode="HTML", reply_markup=markup)
        except Exception:
            pass

        log_action("DEPOSIT_REQUEST", user_id,
                   f"Method: BinanceAuto, USDT: {usdt_amount}, BDT: {bdt_equivalent}, Username: {username or 'N/A'}")

    except Exception as e:
        tb = traceback.format_exc()
        logging.error(f"process_binance_auto_username CRASH | user={user_id} | err={e}\n{tb}")
        try:
            bot.send_message(user_id,
                "❌ <b>কিছু একটা সমস্যা হয়েছে!</b>\n\n"
                "আবার চেষ্টা করুন অথবা সাপোর্টে যোগাযোগ করুন:\n"
                f"@{SUPPORT_USERNAME}",
                parse_mode="HTML", reply_markup=get_main_menu(user_id))
        except Exception:
            pass
        # 🆕 FIX: admin notification যোগ করা হলো (আগে ছিল না)
        try:
            bot.send_message(ADMIN_ID,
                f"🚨 <b>process_binance_auto_username Crash!</b>\n\n"
                f"👤 User: <code>{user_id}</code>\n"
                f"❌ Error: <code>{str(e)[:300]}</code>",
                parse_mode="HTML")
        except Exception:
            pass


# ===========================
# DEPOSIT APPROVE / REJECT
# ===========================

def show_pending_deposits(admin_id):
    db = load_db()
    pending = {k: v for k, v in db["deposit_requests"].items() if v["status"] == "pending"}
    if not pending:
        bot.send_message(admin_id, "✅ <b>No pending deposits</b>", parse_mode="HTML"); return
    for req_id, data in list(pending.items())[:5]:
        auto_badge = "⚡ Auto" if data.get("is_auto") else "🔵 Manual"
        # ✅ Binance এর transaction_id শুধু request_id এর duplicate,
        # তাই আলাদা TrxID লাইন না দেখিয়ে শুধু Request ID দেখানো হচ্ছে।
        trx_line = "" if data.get("method") == "BinanceAuto" else f"🔑 TrxID: <code>{data['transaction_id']}</code>\n"
        message = (
            f"💰 <b>Pending Deposit</b> [{auto_badge}]\n"
            f"\n"
            f"🆔 <code>{req_id}</code>\n"
            f"👤 User: <code>{data['user_id']}</code> (@{get_cached_username(data['user_id'])})\n"
            f"💳 Method: {display_method_name(data['method'])}\n"
            f"💰 Amount: {data['amount']} BDT\n"
            f"{trx_line}"
            f"📅 Date: {data['date']}"
        )
        markup = types.InlineKeyboardMarkup()
        markup.add(
            InlineBtn("✅ Approve", style="success", callback_data=f"dep_approve_{req_id}"),
            InlineBtn("❌ Reject", style="danger", callback_data=f"dep_reject_{req_id}")
        )
        bot.send_message(admin_id, message, parse_mode="HTML", reply_markup=markup)

def approve_deposit(admin_id, request_id, call):
    # 🔒 RACE-CONDITION FIX: request_id ভিত্তিক lock — admin দ্রুত ডাবল-ট্যাপ
    # করলে বা Telegram duplicate callback পাঠালে দুইবার balance credit হওয়া
    # আটকায় (ঠিক auto_approve_deposit() এর trx_id lock এর মতোই)। lock এর
    # ভিতরে fresh db load + status re-check করা হয়, যাতে অন্য থ্রেড ইতিমধ্যে
    # approve করে থাকলে সেটা ধরা পড়ে।
    with get_trx_lock(request_id):
        db = load_db()
        if request_id not in db["deposit_requests"]:
            bot.answer_callback_query(call.id, "Request not found!", show_alert=True); return
        req = db["deposit_requests"][request_id]
        if req["status"] != "pending":
            bot.answer_callback_query(call.id, "Already processed!", show_alert=True); return
        user_id  = req["user_id"]
        # ✅ FIX: int() truncate করলে দশমিক মান (যেমন 10.5 → 10) হারিয়ে
        # যেত, তাই round(2) ব্যবহার করা হচ্ছে দশমিক মান ঠিক রাখতে।
        amount   = round(float(req["amount"]), 2)
        method   = req["method"]
        trx_id   = req.get("transaction_id", "N/A")   # ← BUG FIX: was undefined
        now      = get_now()

        if user_id not in db["users"]:
            db["users"][user_id] = {"balance": 0, "refer_count": 0, "orders": [],
                                    "join_date": now, "lang": "en"}
        new_bal = round(float(db["users"][user_id].get("balance", 0)) + float(amount), 2)
        # CASHBACK
        cashback = get_cashback(amount, db)
        if cashback > 0:
            new_bal = round(new_bal + cashback, 2)
        db["users"][user_id]["balance"] = new_bal
        req["status"] = "approved"
        req["approved_date"] = now
        mark_trxid_used(db, trx_id)
        # ⚡ OPTIMIZED: পুরো DB write বাদ — শুধু changed paths update করো
        update_db_path(f"/users/{user_id}/balance", new_bal, _async=False)
        update_db_path(f"/deposit_requests/{request_id}", req, _async=False)
        # verified_trxids আলাদা update
        _EXECUTOR.submit(_update_db_path_sync, "/verified_trxids",
                         {str(i): v for i, v in enumerate(db.get("verified_trxids", []))})
        _update_db_cache_in_place(db)  # cache sync করো

    # ⚡ User কে সাথে সাথে clear balance notification
    try:
        cashback_line = (
            f"\n🎁 <b>Cashback Bonus:</b> +{cashback} BDT 🎉"
        ) if cashback > 0 else ""

        lang_u = _lang_cache.get(user_id, "en")
        if lang_u == "bn":
            msg_text = (
                f"✅ <b>ডিপোজিট অ্যাপ্রুভ হয়েছে!</b>\n\n"
                f"💰 <b>+{amount} BDT যোগ হয়েছে</b>"
                f"{cashback_line}\n\n"
                f"💳 <b>নতুন Balance: {new_bal} BDT</b>\n"
                f"🆔 Request: <code>{request_id}</code>\n\n"
                f"🛍️ এখনই কেনাকাটা করুন!"
            )
        else:
            msg_text = (
                f"✅ <b>Deposit Approved!</b>\n\n"
                f"💰 <b>+{amount} BDT Added</b>"
                f"{cashback_line}\n\n"
                f"💳 <b>New Balance: {new_bal} BDT</b>{with_usd_equiv(user_id, new_bal)}\n"
                f"🆔 Request: <code>{request_id}</code>\n\n"
                f"🛍️ Start shopping now!"
            )
        shop_markup = types.InlineKeyboardMarkup()
        shop_markup.add(InlineBtn("🛍️ Buy Mail", style="primary", callback_data="go_to_shop"))
        bot.send_message(user_id, msg_text, parse_mode="HTML", reply_markup=shop_markup)
    except: pass

    # ✅ Channel এ শুধু APPROVE log — masked
    try:
        # Binance এর transaction_id শুধু request_id এর duplicate — আলাদা
        # TrxID লাইন বাদ দিয়ে শুধু Request ID দেখানো হচ্ছে।
        trx_line = "" if method == "BinanceAuto" else f"🔑 TrxID: <code>{mask_id(req['transaction_id'])}</code>\n"
        bot.send_message(LOG_CHANNEL_ID,
            f"✅ <b>Deposit Approved</b>\n"
            f"\n"
            f"👤 User: <code>{mask_id(user_id)}</code>\n"
            f"💳 Method: {display_method_name(method)}\n"
            f"💰 Amount: {amount} BDT\n"
            f"🆔 Request: <code>{mask_id(request_id)}</code>\n"
            f"{trx_line}"
            f"👤 Admin: Manual\n"
            f"📅 {now}",
            parse_mode="HTML")
    except: pass

    try:
        bot.edit_message_reply_markup(admin_id, call.message.message_id, reply_markup=None)
        bot.send_message(admin_id,
            f"✅ <b>Approved!</b> <code>{request_id}</code> | {amount} BDT → User <code>{user_id}</code>",
            parse_mode="HTML")
    except: pass
    log_action("DEPOSIT_APPROVED", admin_id, f"Request: {request_id}, Amount: {amount}")
    bot.answer_callback_query(call.id, "✅ Approved!", show_alert=False)

def reject_deposit(admin_id, request_id, call):
    # 🔒 RACE-CONDITION FIX: approve_deposit() এর মতোই request_id lock —
    # ডাবল-ট্যাপে duplicate reject message/log না যায়।
    with get_trx_lock(request_id):
        db = load_db()
        if request_id not in db["deposit_requests"]:
            bot.answer_callback_query(call.id, "Request not found!", show_alert=True); return
        req = db["deposit_requests"][request_id]
        if req["status"] != "pending":
            bot.answer_callback_query(call.id, "Already processed!", show_alert=True); return
        user_id = req["user_id"]
        now = get_now()
        req["status"] = "rejected"
        req["rejected_date"] = now
        # ⚡ Targeted write — শুধু deposit request status update করো
        update_db_path(f"/deposit_requests/{request_id}", req)
        _update_db_cache_in_place(db)
    try:
        bot.send_message(user_id,
            t(user_id, "dep_rejected", amount=req["amount"], req_id=request_id),
            parse_mode="HTML")
    except: pass

    # ✅ Reject log channel এ যাবে না — শুধু admin কে জানাবে
    # (Channel এ শুধু approve log যাবে)

    try:
        bot.edit_message_reply_markup(admin_id, call.message.message_id, reply_markup=None)
        bot.send_message(admin_id,
            f"❌ <b>Rejected!</b> Request: <code>{request_id}</code>",
            parse_mode="HTML")
    except: pass
    log_action("DEPOSIT_REJECTED", admin_id, f"Request: {request_id}")
    bot.answer_callback_query(call.id, "Rejected!", show_alert=False)

