# 📥 UPLOAD INFO — Firebase export থেকে শুধু user balance + refer_count import
# ══════════════════════════════════════════════════════════════════════
def admin_upload_info_receive_file(message):
    """admin_upload_info ফ্লো — admin যেই Firebase export .json পাঠায় সেখান
    থেকে শুধু users এর balance + refer_count বের করে preview দেখায়।
    বাকি সব key (orders, deposits, products, settings ইত্যাদি) সম্পূর্ণ skip।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return

    if message.content_type != 'document':
        msg = bot.send_message(user_id, "❌ <b>একটা .json ফাইল পাঠান!</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_upload_info_receive_file); return

    fname = message.document.file_name or ""
    if not fname.lower().endswith(".json"):
        msg = bot.send_message(user_id, "❌ <b>শুধু .json ফাইল সাপোর্ট করে!</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_upload_info_receive_file); return

    try:
        file_info = bot.get_file(message.document.file_id)
        downloaded = bot.download_file(file_info.file_path)
        payload = json.loads(downloaded.decode("utf-8"))
    except Exception as e:
        msg = bot.send_message(user_id, f"❌ <b>JSON ফাইল পড়া যায়নি!</b>\n<code>{str(e)}</code>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_upload_info_receive_file); return

    if not isinstance(payload, dict) or "users" not in payload or not isinstance(payload["users"], dict):
        msg = bot.send_message(user_id,
            "❌ <b>এই ফাইলে 'users' section পাওয়া যায়নি!</b>\nসঠিক Firebase export ফাইল পাঠান।",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_upload_info_receive_file); return

    # শুধুমাত্র 3টা জিনিস বের করো: user id, balance, refer_count — বাকি সব skip
    src_users = payload["users"]
    extracted = {}
    for uid, info in src_users.items():
        if not isinstance(info, dict):
            continue
        extracted[str(uid)] = {
            "balance": info.get("balance", 0),
            "refer_count": info.get("refer_count", 0),
        }

    if not extracted:
        bot.send_message(user_id, "⚠️ <b>ফাইলে কোনো valid user পাওয়া যায়নি!</b>", parse_mode="HTML")
        show_admin_panel(user_id); return

    _UPLOAD_INFO_PENDING[user_id] = extracted

    preview = "\n".join(
        f"🆔 <code>{uid}</code> — 💳 {d['balance']} BDT — 👥 {d['refer_count']}"
        for uid, d in list(extracted.items())[:10]
    )
    more = f"\n… এবং আরো {len(extracted) - 10}টি user" if len(extracted) > 10 else ""

    text = (
        f"📥 <b>Upload Info — Confirm করুন</b>\n\n"
        f"✅ <b>মোট {len(extracted)}টি user পাওয়া গেছে</b>\n"
        f"শুধু <b>User ID + Balance + Referral Count</b> save হবে, বাকি সব (orders, deposits, "
        f"products, settings ইত্যাদি) সম্পূর্ণ <b>skip</b> হবে।\n\n"
        f"<b>প্রিভিউ:</b>\n{preview}{more}\n\n"
        f"⚠️ বিদ্যমান user এর balance/referral overwrite হবে। নতুন user হলে তৈরি হবে।\n\n"
        f"এগিয়ে যাবেন?"
    )
    markup = types.InlineKeyboardMarkup()
    markup.add(
        InlineBtn("✅ Confirm & Upload", style="success", callback_data="admin_upload_info_confirm"),
        InlineBtn("❌ Cancel", style="danger", callback_data="admin_upload_info_cancel"),
    )
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)


def admin_upload_info_apply(pending):
    """Confirm করার পর সব user এর balance + refer_count MySQL এ লেখো।
    ⚡ IMPORTANT FIX (v2): users শার্ডেড — প্রতি user আলাদা MySQL row
    ('user:{uid}')। update_db_path("/users", ...) ব্যবহার করলে ভেতরে
    _set_whole_section() আগে সব পুরনো row DELETE করে, তারপর প্রতিটা user
    এর জন্য আলাদা আলাদা sequential INSERT করে — ১৯৬৮ user মানে ১৯৬৮টা
    আলাদা network round-trip, যা মিনিটের পর মিনিট লাগায়।
    তাই এখানে সরাসরি _mysql_bulk_upsert() ব্যবহার করা হচ্ছে — একটাই
    transaction এ batched executemany দিয়ে সব row একসাথে লেখা হয় (মাত্র
    কয়েকটা round-trip), আগের কোনো user row-ও delete হয় না।
    বিদ্যমান user হলে merge (অন্য field অক্ষত থাকবে), না থাকলে নতুন তৈরি হবে —
    এবং refer_count এই মান থেকে সামনে আরো referral হলে বাড়তে থাকবে
    (referral bonus flow ইতিমধ্যে refer_count কে +=1 করে বাড়ায়, override করে না)।"""
    db = load_db()
    users = db.setdefault("users", {})
    applied, failed = [], []
    to_write = {}

    for uid, data in pending.items():
        try:
            current = users.get(uid, {})
            if not isinstance(current, dict):
                current = {}
            updated = dict(current)
            updated["balance"] = data.get("balance", 0)
            updated["refer_count"] = data.get("refer_count", 0)
            users[uid] = updated
            to_write[uid] = updated
            applied.append(uid)
        except Exception as e:
            logging.error(f"admin_upload_info_apply merge error [{uid}]: {e}")
            failed.append(f"{uid} — {e}")

    # ⚡ একটাই batched transaction এ সব user row upsert — সেকেন্ডের মধ্যে শেষ
    try:
        _mysql_bulk_upsert("user", to_write, chunk_size=500)
        _update_db_cache_in_place(db)
    except Exception as e:
        logging.error(f"admin_upload_info_apply bulk write error: {e}")
        failed.extend([f"{uid} — bulk write failed: {e}" for uid in applied])
        applied = []
    _invalidate_db_cache()
    return applied, failed


