# 📥 User Data Import (Excel) ফ্লো — Confirm চাপার আগ পর্যন্ত অস্থায়ী hold
_USER_DATA_IMPORT_PENDING = {}

def admin_user_data_import_receive_file(message):
    """admin_user_data_import ফ্লো — 'User Data Export' থেকে পাওয়া অপরিবর্তিত
    .xlsx ফাইলটাই সরাসরি এখানে পাঠানো যায়। হেডার নাম দিয়ে কলাম খুঁজে বের করে
    (কলামের ক্রম বদলে গেলেও কাজ করবে):
      ✅ Balance, Refer Count, Referred By, Language, Join Date, Banned — এসব restore হবে
      🚫 Username, Total Orders, Total Spent — এগুলো skip হবে (derived ডেটা, সরাসরি
         সেভযোগ্য field না — Username Telegram থেকে আসে, Orders/Spent হিসাব হয় orders
         history থেকে)।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return

    if message.content_type != 'document':
        msg = bot.send_message(user_id, "❌ <b>একটা .xlsx ফাইল পাঠান!</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_user_data_import_receive_file); return

    fname = message.document.file_name or ""
    if not fname.lower().endswith((".xlsx", ".xls")):
        msg = bot.send_message(user_id, "❌ <b>শুধু .xlsx/.xls ফাইল সাপোর্ট করে!</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_user_data_import_receive_file); return

    try:
        file_info = bot.get_file(message.document.file_id)
        downloaded = bot.download_file(file_info.file_path)
        from io import BytesIO as _BytesIO
        wb = openpyxl.load_workbook(_BytesIO(downloaded), read_only=True, data_only=True)
        ws = wb.active
        rows_iter = ws.iter_rows(values_only=True)
        header_row = next(rows_iter, None)
    except Exception as e:
        msg = bot.send_message(user_id, f"❌ <b>Excel ফাইল পড়া যায়নি!</b>\n<code>{str(e)}</code>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_user_data_import_receive_file); return

    if not header_row:
        msg = bot.send_message(user_id, "❌ <b>ফাইলে কোনো ডেটা পাওয়া যায়নি!</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_user_data_import_receive_file); return

    # হেডার নাম case-insensitive match করে কলাম index বের করো
    header_map = {}
    for idx, h in enumerate(header_row):
        if h is None:
            continue
        key = str(h).strip().lower()
        header_map[key] = idx

    uid_col = header_map.get("user id")
    bal_col = header_map.get("balance")
    ref_col = header_map.get("refer count")
    # ঐচ্ছিক কলাম — না থাকলেও import চলবে, শুধু balance+refer_count হবে
    refby_col = header_map.get("referred by")
    lang_col = header_map.get("language")
    join_col = header_map.get("join date")
    banned_col = header_map.get("banned")

    if uid_col is None or bal_col is None or ref_col is None:
        msg = bot.send_message(user_id,
            "❌ <b>ফাইলে দরকারি কলাম পাওয়া যায়নি!</b>\n"
            "'User ID', 'Balance', 'Refer Count' — এই ৩টা কলাম হেডার লাগবে।\n"
            "<i>('User Data Export' থেকে পাওয়া ফাইলটাই সরাসরি পাঠান।)</i>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_user_data_import_receive_file); return

    extracted = {}
    for row in rows_iter:
        if row is None:
            continue
        try:
            raw_uid = row[uid_col]
            if raw_uid is None or str(raw_uid).strip() == "":
                continue
            uid = str(raw_uid).strip()
            # ফাইলে "1234.0"-এর মতো float হয়ে গেলেও ঠিক করো
            if uid.endswith(".0") and uid[:-2].isdigit():
                uid = uid[:-2]
            balance = float(row[bal_col]) if row[bal_col] not in (None, "") else 0
            refer_count = int(float(row[ref_col])) if row[ref_col] not in (None, "") else 0
            entry = {"balance": balance, "refer_count": refer_count}
            if refby_col is not None and row[refby_col] not in (None, ""):
                entry["referred_by"] = str(row[refby_col]).strip()
            if lang_col is not None and row[lang_col] not in (None, ""):
                entry["lang"] = str(row[lang_col]).strip()
            if join_col is not None and row[join_col] not in (None, ""):
                entry["join_date"] = str(row[join_col]).strip()
            if banned_col is not None and row[banned_col] not in (None, ""):
                entry["_banned"] = str(row[banned_col]).strip().lower() in ("yes", "true", "1")
            extracted[uid] = entry
        except Exception:
            continue

    if not extracted:
        bot.send_message(user_id, "⚠️ <b>কোনো valid user row পাওয়া যায়নি!</b>", parse_mode="HTML")
        show_admin_panel(user_id); return

    _USER_DATA_IMPORT_PENDING[user_id] = extracted

    preview = "\n".join(
        f"🆔 <code>{uid}</code> — 💳 {d['balance']} BDT — 👥 {d['refer_count']}"
        for uid, d in list(extracted.items())[:10]
    )
    more = f"\n… এবং আরো {len(extracted) - 10}টি user" if len(extracted) > 10 else ""

    extra_found = []
    if refby_col is not None: extra_found.append("Referred By")
    if lang_col is not None: extra_found.append("Language")
    if join_col is not None: extra_found.append("Join Date")
    if banned_col is not None: extra_found.append("Banned status")
    extra_line = (f"✅ সাথে এগুলোও restore হবে: {', '.join(extra_found)}\n" if extra_found else "")

    text = (
        f"📥 <b>User Data Import — Confirm করুন</b>\n\n"
        f"✅ <b>মোট {len(extracted)}টি user পাওয়া গেছে</b>\n"
        f"✅ Balance + Referral Count save হবে\n"
        f"{extra_line}"
        f"🚫 Username/Total Orders/Total Spent skip হবে (derived ডেটা)\n\n"
        f"<b>প্রিভিউ:</b>\n{preview}{more}\n\n"
        f"⚠️ বিদ্যমান user এর ডেটা overwrite হবে।\n\n"
        f"এগিয়ে যাবেন?"
    )
    markup = types.InlineKeyboardMarkup()
    markup.add(
        InlineBtn("✅ Confirm & Import", style="success", callback_data="admin_user_data_import_confirm"),
        InlineBtn("❌ Cancel", style="danger", callback_data="admin_user_data_import_cancel"),
    )
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)


def admin_user_data_import_apply(pending):
    """Confirm করার পর প্রতিটা user এর balance/refer_count + (থাকলে) referred_by/
    lang/join_date restore করো, এবং banned_users list-ও sync করো — সব একটাই
    fast batched MySQL transaction এ (_mysql_bulk_upsert), তাই হাজার হাজার
    user হলেও কয়েক সেকেন্ডে শেষ হয়।"""
    db = load_db()
    users = db.setdefault("users", {})
    applied, failed = [], []
    to_write = {}
    banned_set = set(db.get("banned_users", []) or [])
    banned_changed = False

    for uid, data in pending.items():
        try:
            current = users.get(uid, {})
            if not isinstance(current, dict):
                current = {}
            updated = dict(current)
            updated["balance"] = data.get("balance", 0)
            updated["refer_count"] = data.get("refer_count", 0)
            if "referred_by" in data:
                updated["referred_by"] = data["referred_by"]
            if "lang" in data:
                updated["lang"] = data["lang"]
            if "join_date" in data:
                updated["join_date"] = data["join_date"]
            users[uid] = updated
            to_write[uid] = updated
            applied.append(uid)

            if "_banned" in data:
                if data["_banned"] and uid not in banned_set:
                    banned_set.add(uid); banned_changed = True
                elif not data["_banned"] and uid in banned_set:
                    banned_set.discard(uid); banned_changed = True
        except Exception as e:
            logging.error(f"admin_user_data_import_apply merge error [{uid}]: {e}")
            failed.append(f"{uid} — {e}")

    try:
        _mysql_bulk_upsert("user", to_write, chunk_size=500)
        if banned_changed:
            db["banned_users"] = list(banned_set)
            update_db_path("/banned_users", db["banned_users"], _async=False)
        _update_db_cache_in_place(db)
    except Exception as e:
        logging.error(f"admin_user_data_import_apply bulk write error: {e}")
        failed.extend([f"{uid} — bulk write failed: {e}" for uid in applied])
        applied = []
    _invalidate_db_cache()
    return applied, failed


def admin_data_load_apply(pending):
    """Confirm করার পর আসল restore — প্রতিটা key MySQL এ synchronously write করে।"""
    db = load_db()
    applied, failed = [], []
    for key, value in pending.items():
        try:
            default_val = _DB_DEFAULT.get(key)
            if isinstance(default_val, list):
                new_val = _firebase_to_list(value, list)
            else:
                current = db.get(key, {})
                if not isinstance(current, dict):
                    current = {}
                overlay = value if isinstance(value, dict) else {}
                new_val = _deep_merge_dict(current, overlay)
            update_db_path(f"/{key}", new_val, _async=False)
            applied.append(key)
        except Exception as e:
            logging.error(f"admin_data_load_apply error [{key}]: {e}")
            failed.append(f"{key} — {e}")
    _invalidate_db_cache()
    return applied, failed

def admin_data_load_receive_file(message):
    """admin_data_load ফ্লো — admin যেই .json ফাইল পাঠায় সেটা receive করে।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return

    if message.content_type != 'document':
        msg = bot.send_message(user_id, "❌ <b>একটা .json ফাইল পাঠান!</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_data_load_receive_file); return

    fname = message.document.file_name or ""
    if not fname.lower().endswith(".json"):
        msg = bot.send_message(user_id, "❌ <b>শুধু .json ফাইল সাপোর্ট করে!</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_data_load_receive_file); return

    try:
        file_info = bot.get_file(message.document.file_id)
        downloaded = bot.download_file(file_info.file_path)
        payload = json.loads(downloaded.decode("utf-8"))
    except Exception as e:
        msg = bot.send_message(user_id, f"❌ <b>JSON ফাইল পড়া যায়নি!</b>\n<code>{str(e)}</code>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_data_load_receive_file); return

    if not isinstance(payload, dict):
        msg = bot.send_message(user_id, "❌ <b>ভুল ফরম্যাট!</b> Root object (dict) হতে হবে।",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_data_load_receive_file); return

    found_keys = [k for k in _DATA_LOAD_ALLOWED_KEYS if k in payload and payload[k]]
    skipped_keys = [k for k in payload.keys() if k not in _DATA_LOAD_ALLOWED_KEYS]

    if not found_keys:
        bot.send_message(user_id,
            "⚠️ <b>এই ফাইলে কোনো known preset key পাওয়া যায়নি!</b>\n\n"
            "প্রত্যাশিত keys: <code>settings, products, product_details, sub_products, "
            "vpn_products_*, proxy_products_*, promo_codes, bulkmail_products</code> ইত্যাদি।",
            parse_mode="HTML")
        show_admin_panel(user_id); return

    _DATA_LOAD_PENDING[user_id] = {k: payload[k] for k in found_keys}

    preview = "\n".join(f"✅ {k}" for k in found_keys)
    skip_preview = ("\n\n🚫 <b>Skip হবে (unknown/sensitive key):</b>\n" + "\n".join(f"• {k}" for k in skipped_keys)) if skipped_keys else ""
    text = (
        f"📥 <b>Preset পাওয়া গেছে — Restore করার আগে Confirm করুন</b>\n\n"
        f"<b>Import হবে ({len(found_keys)}টা):</b>\n{preview}"
        f"{skip_preview}\n\n"
        f"ℹ️ dict-টাইপ preset merge হবে (পুরনো data মুছবে না, শুধু নতুন data বসবে)।\n"
        f"❌ User balance/orders/deposit/ban/admin/ticket — কিচ্ছু touch হবে না।\n\n"
        f"এগিয়ে যাবেন?"
    )
    markup = types.InlineKeyboardMarkup()
    markup.add(
        InlineBtn("✅ Confirm & Restore", style="success", callback_data="admin_data_load_confirm"),
        InlineBtn("❌ Cancel", style="danger", callback_data="admin_data_load_cancel"),
    )
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)

