def _get_extra_admins_fresh():
    """সবসময় fresh DB থেকে extra_admins list (normalized) রিটার্ন করে।"""
    db = load_db()
    extra = db.get("extra_admins", [])
    if isinstance(extra, dict):
        extra = list(extra.values())
    return [str(a) for a in extra if a]

def show_admin_management(user_id, message_id=None):
    """Owner-only স্ক্রিন — বর্তমান admin list দেখায়, Add/Remove বাটন সহ।"""
    extra = _get_extra_admins_fresh()

    text = (
        f"\n👑 <b>Admin Management</b>\n"
        f"\n\n"
        f"🔑 <b>Owner:</b> <code>{ADMIN_ID}</code> <i>(সবসময় admin, remove করা যাবে না)</i>\n"
    )
    if extra:
        text += "\n👤 <b>Added Admins:</b>\n"
        for aid in extra:
            text += f"  • <code>{aid}</code>\n"
    else:
        text += "\n<i>এখনো কোনো extra admin যোগ করা হয়নি।</i>\n"

    markup = types.InlineKeyboardMarkup(row_width=1)
