def admin_kb_emoji_input_step(message, role):
    """Admin panel থেকে 'Button Emoji' ফ্লো-তে admin এর পাঠানো emoji
    text টা validate করে সেই role এর জন্য সেভ করো (in-memory + MySQL)।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return
    if role not in KB_BUTTON_ROLES:
        bot.send_message(user_id, "❌ Invalid button role."); return

    new_emoji = message.text.strip()
    m = _KB_LEADING_EMOJI_RE.match(new_emoji + " ")
    is_valid_emoji = bool(m and m.end() >= len(new_emoji))

    if not new_emoji or not is_valid_emoji:
        msg = bot.send_message(user_id,
            "❌ <b>শুধু একটা emoji পাঠান</b> (কোনো লেখা ছাড়া)।\nযেমন: 🚀, ⭐, 🔥\n\nআবার চেষ্টা করুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, lambda m2: admin_kb_emoji_input_step(m2, role)); return

    set_kb_button_emoji(role, new_emoji)
    db = load_db()
    if "settings" not in db:
        db["settings"] = {}
    if "kb_button_emojis" not in db["settings"]:
        db["settings"]["kb_button_emojis"] = {}
    db["settings"]["kb_button_emojis"][role] = new_emoji
    # ⚡ Targeted write — শুধু এই role এর emoji
    update_db_path(f"/settings/kb_button_emojis/{role}", new_emoji)
    _update_db_cache_in_place(db)

    label = KB_BUTTON_ROLES[role][0]
    bot.send_message(user_id,
        f"✅ <b>{label}</b> এর emoji আপডেট হয়েছে!\n\nনতুন emoji: {new_emoji}",
        parse_mode="HTML")

    markup = types.InlineKeyboardMarkup(row_width=1)
    for r, (lbl, _default) in KB_BUTTON_ROLES.items():
        ce = get_kb_button_emoji(r) or "➖"
        markup.add(InlineBtn(f"{ce} {lbl}", style="primary", callback_data=f"admin_kbe_role_{r}"))
    markup.add(InlineBtn("🔙 Admin Panel", style="primary", callback_data="back_admin"))
    bot.send_message(user_id,
        "😀 <b>Button Emoji</b>\n\nআরেকটা বাটন বেছে নিন, অথবা Admin Panel এ ফিরে যান 👇",
        parse_mode="HTML", reply_markup=markup)
    # Admin কে সাথে সাথে আপডেটেড reply keyboard দেখিয়ে দাও
    try:
        bot.send_message(user_id, "🔄 Main Menu (updated emoji):",
                          reply_markup=get_main_menu(user_id))
    except Exception:
        pass


def show_proxyprov_kb_admin_list(chat_id):
    """Proxy provider keyboard বাটন লিস্ট (ABC/Cli/9Proxy/Owl/Proxy5/Proxy6) —
    প্রতিটার পাশে বর্তমান On/Off স্ট্যাটাস সহ — আবার দেখায়।"""
