def admin_p2_setid_step(message, item_no):
    """Product2 এর একটা item কে bulkmail.shop Website Product ID এর সাথে
    কানেক্ট করার next-step handler। ID সেট হয়ে গেলে সাথে সাথে runtime এ
    virtual product register হয়ে যায় — এরপর শুধু Price ও Description সেট
    করলেই item টা লাইভ API-connected হয়ে যাবে।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return
    raw = (message.text or "").strip()
    if not raw.isdigit():
        msg = bot.send_message(user_id, "❌ <b>শুধু সংখ্যা লিখুন (bulkmail.shop product ID):</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, lambda m: admin_p2_setid_step(m, item_no)); return
    db = load_db()
    product_id = int(raw)
    set_product2_bulkmail_id(item_no, product_id, db)

    # ✅ ID সেট হওয়ার সাথে সাথেই সেই product_id এর live stock bulkmail.shop
    # থেকে fetch করে confirmation ম্যাসেজেই দেখিয়ে দাও — admin কে নিচের
    # detail view পর্যন্ত অপেক্ষা করতে হবে না, সাথে সাথেই বুঝে যাবে ID টা
    # ঠিকমতো কানেক্ট হয়েছে কিনা এবং stock কত আছে।
    _live_stock = bulkmail_get_stock(product_id)
    if _live_stock < 0:
        _stock_line_confirm = "⚠️ Live stock চেক করা যায়নি (API/ID ভুল হতে পারে)"
    elif _live_stock == 0:
        _stock_line_confirm = "🔴 Out of Stock"
    else:
        _stock_line_confirm = f"{_live_stock} pcs ✅"

    bot.send_message(user_id,
        f"✅ <b>Website Product ID কানেক্ট হয়েছে!</b>\n\n"
        f"🆕 Product2 — Item {item_no}\n"
        f"🆔 bulkmail.shop Product ID: <code>{product_id}</code>\n"
        f"📦 Live Stock: <code>{_stock_line_confirm}</code>\n\n"
        f"এখন 💰 Price ও 📝 Description সেট করে দিন — না দিলে price 0 থাকবে।",
        parse_mode="HTML")

    # 🔍 DEBUG: website এ stock থাকলেও bot এ Out of Stock দেখানোর সমস্যা
    # নির্ণয়ের জন্য bulkmail.shop এর raw API response সরাসরি দেখাও —
    # এখান থেকে বোঝা যাবে field name/format mismatch কোথায় হচ্ছে।
    try:
        _dbg_headers = {"Accept": "application/json"}
        if BULKMAIL_API_KEY:
            _dbg_headers["X-API-Key"] = BULKMAIL_API_KEY
        _dbg_resp = http_requests.get(
            f"{BULKMAIL_BASE_URL}/stock/check",
            params={"ids": str(product_id)},
            headers=_dbg_headers, timeout=8
        )
        _dbg_raw = _dbg_resp.text[:1200]
        bot.send_message(user_id,
            f"🔍 <b>Raw API Response (Debug)</b>\n"
            f"HTTP Status: <code>{_dbg_resp.status_code}</code>\n"
            f"API Key সেট করা আছে: <code>{'হ্যাঁ' if BULKMAIL_API_KEY else 'না ❌'}</code>\n\n"
            f"<code>{_dbg_raw}</code>",
            parse_mode="HTML")
    except Exception as _dbg_e:
        bot.send_message(user_id, f"🔍 Debug fetch error: <code>{_dbg_e}</code>", parse_mode="HTML")

    text_item, markup_item = _product2_item_detail_view(item_no, db)
    bot.send_message(user_id, text_item, parse_mode="HTML", reply_markup=markup_item)

