def admin_edit_balance_step2(message, target_user):
    user_id = str(message.chat.id)
    db = load_db()
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return
    value = message.text.strip()
    current_balance = float(db["users"][target_user].get("balance", 0))
    try:
        if value.startswith('+'):
            added = float(value[1:])
            new_balance = round(current_balance + added, 2)
            action_label = f"+{added} BDT যোগ হয়েছে"
        elif value.startswith('-'):
            deducted = float(value[1:])
            new_balance = round(max(0, current_balance - deducted), 2)
            action_label = f"-{deducted} BDT কাটা হয়েছে"
        else:
            new_balance = round(float(value), 2)
            action_label = f"Balance {new_balance} BDT সেট হয়েছে"

        diff = round(new_balance - current_balance, 2)

        # ⚡ INSTANT: শুধু balance path update — পুরো DB write নয়
        db["users"][target_user]["balance"] = new_balance
        _update_db_cache_in_place(db)  # cache সাথে সাথে update
        update_db_path(f"/users/{target_user}/balance", new_balance, _async=False)

        # Admin কে confirm
        bot.send_message(user_id,
            f"✅ <b>Balance Updated!</b>\n\n"
            f"👤 User: <code>{target_user}</code>\n"
            f"💳 আগে: <b>{current_balance} BDT</b>\n"
            f"💰 এখন: <b>{new_balance} BDT</b>\n"
            f"📊 পরিবর্তন: <code>{action_label}</code>",
            parse_mode="HTML")

        # ⚡ User কে সাথে সাথে notify — স্পষ্ট message
        try:
            lang_u = _lang_cache.get(target_user, "en")
            if diff > 0:
                user_msg = (
                    f"💰 <b>আপনার Balance আপডেট হয়েছে!</b>\n\n"
                    f"✅ <b>+{diff} BDT যোগ হয়েছে</b>\n\n"
                    f"💳 <b>নতুন Balance: {new_balance} BDT</b>\n\n"
                    f"🛍️ এখনই কেনাকাটা করুন!"
                ) if lang_u == "bn" else (
                    f"💰 <b>Your Balance Updated!</b>\n\n"
                    f"✅ <b>+{diff} BDT Added</b>\n\n"
                    f"💳 <b>New Balance: {new_balance} BDT</b>\n\n"
                    f"🛍️ Start shopping now!"
                )
            elif diff < 0:
                user_msg = (
                    f"⚠️ <b>Balance আপডেট হয়েছে</b>\n\n"
                    f"📉 <b>{abs(diff)} BDT কাটা হয়েছে</b>\n\n"
                    f"💳 <b>নতুন Balance: {new_balance} BDT</b>"
                ) if lang_u == "bn" else (
                    f"⚠️ <b>Balance Updated</b>\n\n"
                    f"📉 <b>{abs(diff)} BDT Deducted</b>\n\n"
                    f"💳 <b>New Balance: {new_balance} BDT</b>"
                )
            else:
                user_msg = (
                    f"💳 <b>Balance: {new_balance} BDT</b>\n\n"
                    f"<i>Admin আপনার balance set করেছেন।</i>"
                ) if lang_u == "bn" else (
                    f"💳 <b>Balance: {new_balance} BDT</b>\n\n"
                    f"<i>Admin has set your balance.</i>"
                )
            shop_markup = types.InlineKeyboardMarkup()
            shop_markup.add(InlineBtn("🛍️ Buy Mail", style="primary", callback_data="go_to_shop"))
            bot.send_message(target_user, user_msg, parse_mode="HTML", reply_markup=shop_markup)
        except: pass

    except ValueError:
        bot.send_message(user_id,
            "❌ <b>Invalid input!</b>\n\nUse: 500, +100, or -50", parse_mode="HTML")

def admin_ban_user_step(message):
    user_id = str(message.chat.id)
    try:
        db = load_db()
        if message.text == "❌ Cancel":
            show_admin_panel(user_id); return
        target_user = message.text.strip()
        if target_user not in db["users"]:
            bot.send_message(user_id, "❌ <b>User not found!</b>", parse_mode="HTML"); return
        # ✅ DEFENSIVE FIX: banned_users যদি কোনো কারণে dict হয়ে যায় (পুরনো cache
        # corruption), সেটাকে এখানেই list এ normalize করে নাও যাতে .append() ভেঙে না যায়।
        banned_list = db.get("banned_users", [])
        if isinstance(banned_list, dict):
            banned_list = list(banned_list.values())
        db["banned_users"] = banned_list
        if target_user in db["banned_users"]:
            bot.send_message(user_id, "⚠️ <b>User already banned!</b>", parse_mode="HTML"); return
        db["banned_users"].append(target_user)
        # ⚡ Targeted write — ✅ BUG FIX: list-ই পাঠাও, আগে-থেকে dict বানিয়ে না
        # (dict বানিয়ে পাঠালে cache এ banned_users dict হয়ে যেত, পরের ban এ crash হতো —
        # এই কারণেই ১ জনের বেশি ইউজার ban করা যাচ্ছিল না)
        update_db_path("/banned_users", db["banned_users"])
        bot.send_message(user_id,
            f"✅ <b>User banned!</b>\n\n👤 <code>{target_user}</code>", parse_mode="HTML")
        try:
            bot.send_message(target_user,
                "🚫 <b>You have been banned.</b>\n\nContact support.", parse_mode="HTML")
        except: pass
    except Exception as e:
        logging.error(f"admin_ban_user_step error: {e}", exc_info=True)
        try:
            bot.send_message(user_id, f"❌ <b>Ban failed:</b> <code>{str(e)[:200]}</code>", parse_mode="HTML")
        except: pass

def _broadcast_send_all(uids, send_one_fn):
    """✅ Fast Parallel Broadcast — সব ইউজারকে একসাথে (parallel থ্রেডে, dedicated
    _BROADCAST_EXECUTOR pool দিয়ে) মেসেজ পাঠায়, ফলে হাজার হাজার ইউজার হলেও
    সাধারণত ১-২ মিনিটের মধ্যেই broadcast শেষ হয়ে যায় (আগে ছিল sequential +
    প্রতি মেসেজে 0.05s sleep, যা বড় user base এ অনেক ধীর ছিল)।

    - আলাদা _BROADCAST_EXECUTOR pool ব্যবহার করে, যাতে normal ইউজার ইন্টারঅ্যাকশন
      হ্যান্ডেল করা থ্রেডগুলো (_EXECUTOR) ব্যস্ত না হয় — বট slow হবে না।
    - Telegram flood-control (429) হ্যান্ডেল করা হয় — retry_after অনুযায়ী একবার
      অপেক্ষা করে আবার চেষ্টা করে, নাহলে failed গোনা হয়।
    - send_one_fn(uid) কল হয় প্রতিটা user id এর জন্য — সফল হলে True/None, ব্যর্থ
      হলে exception raise করতে হবে (বা False রিটার্ন করলেও ধরা হবে)।

    Return: (sent_count, failed_count)
    """
    sent = 0
    failed = 0
    lock = threading.Lock()

    def _send_with_retry(uid):
        nonlocal sent, failed
        try:
            ok = send_one_fn(uid)
            if ok is False:
                raise Exception("send_one_fn returned False")
            with lock:
                sent += 1
        except telebot.apihelper.ApiTelegramException as e:
            # 🔁 Flood control (429) — Telegram এর বলে দেওয়া retry_after সময় অপেক্ষা করে
            # একবার মাত্র retry করা হয়, বারবার retry করলে broadcast আটকে থাকবে।
            retry_after = None
            try:
                retry_after = e.result_json.get("parameters", {}).get("retry_after")
            except Exception:
                pass
            if retry_after:
                try:
                    _time_module.sleep(min(float(retry_after), 5) + 0.1)
                    send_one_fn(uid)
                    with lock:
                        sent += 1
                    return
                except Exception:
                    pass
            with lock:
                failed += 1
        except Exception:
            with lock:
                failed += 1

    futures = [_BROADCAST_EXECUTOR.submit(_send_with_retry, uid) for uid in uids]
    for f in futures:
        try:
            f.result()
        except Exception:
            pass

    return sent, failed


def admin_broadcast_step(message):
    user_id = str(message.chat.id)
    db = load_db()

    # Cancel চাপলে (photo/other content type হলে message.text None থাকবে, তাই safe check)
    if message.content_type == "text" and message.text == "❌ Cancel":
        show_admin_panel(user_id); return

    all_uids = list(db["users"].keys())
    admin_chat_id = message.chat.id
    src_message_id = message.message_id

    bot.send_message(user_id,
        f"📢 <b>Broadcast শুরু হচ্ছে...</b>\n👥 <b>{len(all_uids)} জন</b> user কে পাঠানো হবে।\n"
        f"<i>Parallel এ (দ্রুত, ১-২ মিনিটের মধ্যে) পাঠানো হবে, bot slow হবে না।</i>",
        parse_mode="HTML", reply_markup=get_main_menu(user_id))

    # ✅ bot.copy_message() মূল মেসেজটা (টেক্সট/emoji/bold-italic formatting/photo+caption
    # সবকিছুসহ) হুবহু কপি করে পাঠায় — কোনো re-parsing হয় না, তাই admin যেভাবে লিখে/পাঠায়
    # ঠিক সেভাবেই সব ইউজারকে broadcast হবে। Photo broadcast করতেও এই একই ফাংশন কাজ করে।
    # ⚡ FAST PARALLEL BROADCAST: আগে sequential + 0.05s sleep per message ছিল (অনেক ধীর,
    # হাজার হাজার user এ কয়েক মিনিট থেকে ঘণ্টাখানেক লাগতো)। এখন _broadcast_send_all()
    # দিয়ে সব ইউজারকে একসাথে (25 parallel থ্রেডে) পাঠানো হয় — normal ইউজার
    # ইন্টারঅ্যাকশন হ্যান্ডেল করা থ্রেড আলাদা থাকায় বট slow হয় না।
    def _do_admin_broadcast(uids, admin_chat_id, src_message_id):
        sent, failed = _broadcast_send_all(
            uids,
            lambda uid: bot.copy_message(chat_id=uid, from_chat_id=admin_chat_id, message_id=src_message_id)
        )
        try:
            bot.send_message(user_id,
                f"✅ <b>Broadcast complete!</b>\n\n✅ Sent: {sent}\n❌ Failed: {failed}",
                parse_mode="HTML")
        except Exception:
            pass

    threading.Thread(target=_do_admin_broadcast, args=(all_uids, admin_chat_id, src_message_id), daemon=True).start()

