# 📊 DAILY SALES REPORT — প্রতিদিন রাত 11:59 PM এ বটের log channel এ পাঠানো হয়
# প্রতিটা প্রোডাক্ট কত pcs / কত টাকা বিক্রি হয়েছে, ও সব মিলিয়ে total pcs ও total tk
# ═══════════════════════════════════════════════════════════

def build_daily_sales_report(db=None, target_date_str=None):
    """আজকের (বা target_date_str দিয়ে দেওয়া তারিখের) সব completed order থেকে
    প্রোডাক্ট-ভিত্তিক pcs ও টাকার হিসাব বানিয়ে দেয়।
    date ফরম্যাট order_entry তে "%d/%m/%Y %I:%M %p" — তাই শুরুর অংশ মিলিয়ে ফিল্টার করি।
    """
    if db is None:
        db = load_db()
    if target_date_str is None:
        target_date_str = datetime.now(BD_TZ).strftime("%d/%m/%Y")

    per_product = {}   # product_name -> {"pcs": int, "tk": float}
    total_pcs = 0
    total_tk = 0.0

    for uid, udata in db.get("users", {}).items():
        for order in (udata.get("orders", []) or []):
            if not isinstance(order, dict):
                continue
            if order.get("status") != "completed":
                continue
            order_date = str(order.get("date", ""))
            if not order_date.startswith(target_date_str):
                continue
            pname = order.get("product_name", "Unknown")
            qty = int(order.get("quantity", 0) or 0)
            amt = float(order.get("total", 0) or 0)
            entry = per_product.setdefault(pname, {"pcs": 0, "tk": 0.0})
            entry["pcs"] += qty
            entry["tk"] += amt
            total_pcs += qty
            total_tk += amt

    return per_product, total_pcs, total_tk, target_date_str

def send_daily_sales_report(db=None, target_date_str=None):
    """Daily sales report বানিয়ে LOG_CHANNEL_ID তে পাঠায়।"""
    try:
        per_product, total_pcs, total_tk, date_str = build_daily_sales_report(db, target_date_str)

        if not per_product:
            report_lines = ["😴 <i>আজ কোনো সেল হয়নি।</i>"]
        else:
            report_lines = []
            for pname, stat in sorted(per_product.items(), key=lambda kv: kv[1]["tk"], reverse=True):
                tk_str = str(int(stat["tk"])) if stat["tk"] == int(stat["tk"]) else f"{stat['tk']:.2f}"
                report_lines.append(f"📦 <b>{pname}</b> — {stat['pcs']} pcs — {tk_str} TK")

        report_body = "\n".join(report_lines)
        total_tk_str = str(int(total_tk)) if total_tk == int(total_tk) else f"{total_tk:.2f}"

        msg = (
            f"📊 <b>Daily Sales Report</b>\n"
            f"📅 <b>{date_str}</b> (11:59 PM)\n"
            f"━━━━━━━━━━━━━━━━━━━━\n\n"
            f"{report_body}\n\n"
            f"━━━━━━━━━━━━━━━━━━━━\n"
            f"📦 <b>Total Pcs:</b> {total_pcs}\n"
            f"💰 <b>Total Tk:</b> {total_tk_str} TK"
        )
        bot.send_message(ADMIN_ID, msg, parse_mode="HTML")
        logging.info(f"Daily sales report sent | date={date_str} | pcs={total_pcs} | tk={total_tk_str}")
    except Exception as e:
        logging.error(f"send_daily_sales_report error: {e}", exc_info=True)
        try:
            bot.send_message(ADMIN_ID,
                f"🚨 <b>Daily Sales Report পাঠাতে ব্যর্থ!</b>\n\n❌ <code>{str(e)[:300]}</code>",
                parse_mode="HTML")
        except: pass

def daily_sales_report_worker():
    """Background thread — প্রতি মিনিটে চেক করে, রাত 11:59 PM (Asia/Dhaka) হলে
    দিনের sales report পাঠায়। একই দিনে দুইবার না পাঠানোর জন্য last-sent date track করে।
    """
    last_sent_date = None
    while True:
        try:
            now = datetime.now(BD_TZ)
            today_str = now.strftime("%d/%m/%Y")
            if now.hour == 23 and now.minute == 59 and last_sent_date != today_str:
                send_daily_sales_report(target_date_str=today_str)
                last_sent_date = today_str
        except Exception as e:
            logging.error(f"daily_sales_report_worker error: {e}", exc_info=True)
        _time_module.sleep(20)  # প্রতি 20s এ চেক — 11:59 মিনিটের window মিস হবে না


